/* A City That Works — Program data, generated from the canonical Notion
   master (The Program, v1.9.1, July 30, 2026). The framework no longer
   publishes a measure total — three earlier versions shipped a count that
   did not survive a hand count — so nothing here should render one either.
   Changelogs are deliberately excluded per the Notion build marker. */
const MEASURES = [
  {"id": "1", "pillar": "foundation", "section": "Honouring the Host Nations", "tier": "core", "title": "Standing government-to-government working tables", "body": "<p>Establish quarterly working tables between the City (Mayor + Chief Administrative Officer) and the elected leadership of the Songhees Nation and the Esquimalt Nation respectively. Standing agendas: shared infrastructure, land use, cultural protocols, economic opportunities, public safety coordination. Published meeting summaries (with Nation approval) so residents can see the partnership is real.</p>", "budget": "$150K/year for dedicated municipal staff time and Nations’ capacity support. The largest cost of broken relationships is litigation and stalled projects, and prevention is cheap."},
  {"id": "2", "pillar": "foundation", "section": "Honouring the Host Nations", "tier": "core", "title": "Indigenous procurement standard", "body": "<p>Adopt a municipal Indigenous procurement target consistent with the federal 5% standard. Prioritize Songhees and Esquimalt Nation-owned and -affiliated businesses where qualified. Simplify RFP processes for small Indigenous suppliers (single-point-of-contact, plain-language requirements, advance notification of upcoming contracts). <strong>Layered addition: regional supplier preference.</strong> Separately from and additional to the Indigenous procurement standard above, the City will apply a <strong>local and regional supplier weighting</strong> in procurement scoring for contracts below the applicable trade-agreement thresholds:</p><ul><li><strong>Scoring weight</strong> for suppliers based on southern Vancouver Island, as one criterion among price, capability and delivery record, not a set-aside and not a disqualifier</li><li><strong>Contract unbundling</strong> where a large tender can be split into lots a small local firm can realistically bid, without loss of coordination</li><li><strong>Advance procurement calendar</strong> published annually so local suppliers can prepare rather than discovering tenders at closing</li><li><strong>Trade-agreement compliance:</strong> local preferences are constrained above the monetary thresholds set by the Canadian Free Trade Agreement and the New West Partnership Trade Agreement. The weighting applies only below those thresholds, and the City will publish the applicable threshold values annually so the rule is auditable. The Indigenous procurement standard above operates under the CFTA's Indigenous-business exception and is unaffected by these thresholds</li></ul><p>These two preferences are additive, not competing. One reflects an intergovernmental relationship; the other keeps municipal spending circulating in the regional economy. A bid can qualify under both.</p>", "budget": "Revenue-neutral. The City is already procuring goods and services; we are changing who gets the work, not adding spending."},
  {"id": "3", "pillar": "foundation", "section": "Honouring the Host Nations", "tier": "core", "title": "lək̓ʷəŋən place names and signage", "body": "<p>Continue and accelerate dual-naming of streets, parks, and public buildings using lək̓ʷəŋən place names, with the participation and consent of the Nations. Where there is clear historical record and Nation support, restore Indigenous names that predate colonial ones.</p>", "budget": "$50K/year as part of normal signage lifecycle replacement."},
  {"id": "4", "pillar": "foundation", "section": "Honouring the Host Nations", "tier": "core", "title": "Cultural protocols for City operations", "body": "<p>Adopt clear protocols for Council meetings, civic events and major project consultations, including territorial acknowledgments developed <em>with</em> the Nations (not generic boilerplate), and Nation participation in major land use decisions affecting their territories.</p>", "budget": "$0. Protocol development and Nation participation in land use decisions are delivered inside the Measure 1 and Measure 5 envelope, already costed at $270K per year. Protocols change how existing processes run; they do not add a process."},
  {"id": "5", "pillar": "foundation", "section": "Honouring the Host Nations", "tier": "core", "title": "Permanent urban Indigenous services liaison", "body": "<p>The City does not deliver social services. But it can coordinate. Establish a permanent municipal liaison position for urban Indigenous services, working with the Victoria Native Friendship Centre, Surrounded by Cedar Child &amp; Family Services, and other organizations to ensure City infrastructure (parks, recreation, libraries, emergency services) is accessible and welcoming for urban Indigenous residents.</p>", "budget": "$120K/year (one FTE plus operating). Substantially offset by reduced friction on consultations and partnerships."},
  {"id": "6", "pillar": "liveable", "section": "Housing: A City Where You Can Live", "tier": "core", "title": "Beat provincial housing targets — with the right composition", "body": "<p>Victoria is running ahead on provincial housing targets in raw volume. The Province set the City a target of <strong>4,902 net new homes over five years</strong> in September 2023, measured in completed units with an occupancy permit rather than in starts, and after two years Victoria had delivered <strong>2,359 net new units, about 48% of the five-year target with three years still to run</strong> (<em>City of Victoria; Times Colonist, November 2025</em>). The City met its year-one quota of 659 units nearly threefold, at 1,477.</p><p><strong>The real problem is composition, and it is the part Victoria is failing.</strong> The same reporting records the City falling behind on below-market rental and on homes with three or more bedrooms, and CMHC data shows Victoria building <strong>56 apartments for every single townhouse.</strong> A city where families cannot find 3-bedroom homes is a city that exports young families. <strong>A volume number cannot fix a composition problem, and this framework does not pretend otherwise.</strong></p><p>Targets to 2030, <strong>with quarterly reporting on each:</strong></p><ul><li><strong>12,000+ net new homes total</strong> by 2030, against the provincial five-year target of 4,902 net new units and measured on the same basis</li><li><strong>At least 25%</strong> in the missing middle: townhomes, duplexes, triplexes, fourplexes, garden suites</li><li><strong>At least 20%</strong> as 3-bedroom or larger family-sized units</li><li><strong>At least 15%</strong> as below-market or non-market through partnerships with BC Housing</li><li><strong>At least 30%</strong> as purpose-built rental</li></ul><p>These targets stack: a single building can count toward more than one category. The point is to use the City's land, permit, and zoning levers to shift the <strong>mix</strong>, not just the headline number.</p><p>We will also identify and release city-owned land suitable for housing through a competitive process that scores developers on speed to completion, affordability commitments, and design quality — not just price.</p>", "budget": "Revenue-positive at full build-out. Property tax revenue from 12,000 new units, staged across the term: estimated $8–15M/year in new ongoing revenue by end of 2030, less in early years."},
  {"id": "6b", "pillar": "liveable", "section": "Housing: A City Where You Can Live", "tier": "sub", "title": "City land bank — continue and operationalize the 2022 commitment", "body": "<p>Mayor Alto's 2022 platform committed to establishing a city land bank — using City-owned and acquired land as a strategic instrument for affordable housing, civic infrastructure, and long-term value capture. The commitment has had cross-bloc support, but delivery has been limited. <strong>We will continue this commitment and give it operational discipline.</strong></p><ul><li><strong>Public inventory</strong> of all city-owned land suitable for housing, with parcel-level mapping, current use, and disposition status — published and updated quarterly</li><li><strong>Strategic acquisition fund</strong> for opportunistic purchases (foreclosures, surplus federal/provincial sites, distressed commercial blocks suitable for residential conversion)</li><li><strong>Competitive disposition</strong> that scores proposals on speed to completion, affordability commitments, design quality, and family-sized unit ratio (per Measure 6 composition targets) — not just price</li><li><strong>Right-of-first-refusal</strong> for non-profit and Indigenous-owned housing partners on a published share of disposed parcels</li><li><strong>Quarterly public reporting</strong> on holdings, dispositions, and resulting housing outcomes</li></ul><p>This is a continuation, not a new direction. The objective is to make a started commitment work — not to substitute for it.</p>", "budget": "Inventory platform and audit: $200K one-time. Strategic acquisition reserve: $2–5M initial fund, replenished from dispositions. Long-term: revenue-positive through land-value capture and affordability leverage."},
  {"id": "7", "pillar": "liveable", "section": "Housing: A City Where You Can Live", "tier": "core", "title": "Cut permit processing times by category — publish the numbers", "body": "<p>Victoria currently publishes no permit-processing benchmarks. That ends.</p><p><strong>Published targets by permit type:</strong></p><ul><li><strong>Simple residential building permits</strong> (single-family alterations, secondary suites): from 3–6 months to <strong>under 6 weeks</strong></li><li><strong>Complex building permits</strong> (multi-unit, mixed use): from 12+ months to <strong>under 6 months</strong></li><li><strong>Rezoning applications</strong>: from 12–18+ months to <strong>under 9 months</strong></li><li><strong>Development permits</strong> (form &amp; character, heritage alteration): published targets per category, audited quarterly</li></ul><p><strong>Concrete actions:</strong></p><ul><li><strong>One-stop development centre:</strong> a single physical and digital entry point for all permits</li><li><strong>Online e-permitting with real-time status tracking</strong> — you know exactly where your application stands at all times, like tracking a package</li><li><strong>Published service standards by permit type</strong>, with quarterly variance reports</li><li><strong>A tenure-based priority queue.</strong> Non-market, co-operative, and supportive housing applications, and purpose-built rental delivering against the Measure 6 composition targets, are processed ahead of the general queue <em>within</em> each permit category rather than in date order. The City cannot fund non-market housing at scale. It can stop being the reason a funded project waits. Published: median approval time for priority-queue files against the general queue, quarterly</li><li><strong>AI-assisted pre-screening of permit applications</strong> — software that generates a conformity report flagging issues for human review, on the model that Kelowna is currently developing (<em>ConstructConnect</em>). Kingston's DASH portal provides 24/7 online access with a 10-business-day target on simple permits (<em>Kingston Herald</em>). Kamloops launched paperless permits in November 2024 (<em>Castanet</em>). Victoria publishes no processing benchmarks and offers no comparable digital tools. We will match the best in BC within Year 1</li><li><strong>Statutory deadline review:</strong> Where the BC Local Government Act and Community Charter permit, introduce response-time triggers (e.g., escalation to senior staff, fee waivers for delayed files). Where statute restricts automatic advance, publish accountability metrics instead. The point is consequences for City delay, not lawlessness</li><li><strong>Simplify and clarify zoning rules.</strong> When rules are 2,000 pages long, even experts get lost. Clear rules mean faster approvals, fewer appeals, and less uncertainty for builders. The VRBA consistently criticizes Victoria's \"regulatory hurdles, slow approval processes, and escalating fees\" (<em>VRBA</em>)</li></ul>", "budget": "~$700K/year for e-permitting platform, AI pre-screening tools, and additional intake staff. Offset by faster file processing and a 4–6 FTE reduction in manual review over 3 years (~$400K–600K/year savings). Net: roughly neutral, with massive economic benefit from faster housing delivery."},
  {"id": "7b", "pillar": "liveable", "section": "Housing: A City Where You Can Live", "tier": "sub", "title": "Pre-approved pattern-book housing — standard designs, expedited stream", "body": "<p><strong>Currently:</strong> Victoria's missing-middle policy produced <strong>61 permits in 2024 against a target of 150</strong>, and 3 applications in its first six months. The binding constraint is no longer zoning, which Bill 44 and the September 2023 overhaul already opened. It is cost and delay. A homeowner adding a garden suite or a small builder constructing a triplex carries the same architectural, engineering, and permitting overhead as a large developer, spread across a fraction of the units. Measure 76 already commits to a pre-approved design library at <em>homeowner renovation</em> scale (garden suite, secondary suite, accessibility retrofit). Nothing covers the multi-unit missing-middle forms that Measure 6's 25% composition target actually depends on. <strong>ACTW:</strong> Publish a municipal pattern book, and give anything built from it a fast lane.</p><ul><li><strong>A pattern book of pre-approved designs</strong> for duplex, triplex, fourplex, townhouse, courtyard housing, and laneway forms, procured through an open architectural competition and published free of charge with no licensing fee</li><li><strong>Automatic expedited permit stream</strong> for any application using a pattern-book design unamended, on the Measure 7 simple-permit target of under 6 weeks. Compliance is pre-established, so review becomes confirmation rather than assessment</li><li><strong>Family-appropriate unit sizes written into the design brief</strong>, so the pattern book delivers against Measure 6's 20% three-bedroom-or-larger target rather than working against it</li><li><strong>Site-adaptation guidance</strong> published alongside each design: what varies by lot width, grade, and setback, and what amendment triggers exit from the expedited stream</li><li><strong>Heritage-compatible variants</strong> for the Heritage Conservation Areas, so the fast lane does not stop at the edge of Measure 43</li><li><strong>Scope boundary, stated to prevent double-counting:</strong> Measure 76's library stays as written and covers homeowner renovation scale. This measure covers the multi-unit forms. Neither is counted twice</li><li><strong>Published annually:</strong> applications using pattern-book designs, the share of missing-middle permits they represent, and median approval time against the standard stream</li></ul><p>British Columbia has already moved in this direction with provincially published standardized housing designs. A municipal pattern book calibrated to Victoria's lot geometry, heritage character, and infrastructure capacity is the local version, and it is the cheapest supply instrument available to a city that cannot lower interest rates.</p>", "budget": "<strong>150 to 250K one-time</strong> for the design competition, professional review, and publication, <strong>funded inside the existing Measure 7 platform envelope of roughly 700K per year rather than added to it.</strong> Recurring cost is nil, because a pattern-book application consumes materially less review time than a bespoke one, which is the same mechanism behind the 4 to 6 FTE review reduction Measure 7 already books. <strong>KPI:</strong> pattern book published within 12 months; share of missing-middle permits using a pattern-book design; median approval time in the expedited stream against the 6-week target."},
  {"id": "8", "pillar": "liveable", "section": "Housing: A City Where You Can Live", "tier": "core", "title": "Push vacancy rate to 5%", "body": "<p>A healthy market where renters have real choices. The vacancy rate has already risen from 1.6% (2023) to 3.3% (2025) — the highest in 26 years (<em>Victoria News</em>) — largely due to factors outside City control (reduced immigration, weak youth employment). But this progress is fragile. We must lock it in by continuing to accelerate supply, so the next economic cycle doesn't plunge us back into a crisis.</p><p><strong>Concrete actions:</strong></p><ul><li>Accelerate purpose-built rentals, garden suites, duplexes, triplexes, and infill housing across appropriate zones</li><li>Pre-zone residential areas for missing-middle housing — no rezoning hearings needed for duplexes and triplexes in single-family zones</li><li>Targeted DCC reductions for purpose-built rental projects, paired with a published infrastructure funding plan so the cuts do not strand essential infrastructure spending</li><li>Expedited permits for any project delivering below-market rental units</li></ul>", "budget": "$0 in this measure. A 5% vacancy rate is an outcome target, not a programme. The instruments that deliver it are costed elsewhere: supply under Measure 6, permit speed under Measure 7, short-term rental licensing under Measure 9b, and small-renovation fee relief under Measure 76. <strong>KPI:</strong> CMHC purpose-built vacancy rate published annually against the 5% target, reported alongside median asking rent so that a vacancy gain from falling demand is not reported as a supply win."},
  {"id": "8b", "pillar": "liveable", "section": "Housing: A City Where You Can Live", "tier": "sub", "title": "Legalize the suites that already exist — a time-limited amnesty and a permitting concierge", "body": "<p><strong>Currently:</strong> Thousands of secondary suites across Victoria sit outside the permit system. Built decades ago, occupied by long-term tenants, never formally approved. The tenancies are real, the rent is real, and the units are counted in nobody's housing target. Many owners are older residents on fixed incomes for whom legalization is slow, expensive, and risky enough that the rational choice is to do nothing and hope nobody complains. The result is a rental stock the City cannot inspect, cannot count, and cannot protect. <strong>ACTW:</strong> Bring them in, rather than pretending they are not there.</p><ul><li><strong>A 24-month legalization amnesty</strong> for existing secondary suites meeting basic life-safety standards: egress, smoke and CO alarms, ceiling height, and electrical. <strong>Life safety is the bar.</strong> Dimensional and aesthetic non-conformities that do not affect safety are grandfathered</li><li><strong>No retroactive penalty</strong> for the period of unpermitted operation where the owner comes forward inside the window. After the window closes, normal enforcement resumes, and we say so at the outset so the window means something</li><li><strong>A standardized approval package and a named permitting concierge</strong> who carries the owner through inspection, remediation scope, and sign-off as one file rather than five departments</li><li><strong>Tenant protection built in:</strong> legalization is not a ground for eviction and not an occasion for a rent reset. The concierge provides the tenant a plain-language notice of what is happening and what their rights are under the <em>Residential Tenancy Act</em> (per Measure 9)</li><li><strong>Remediation financing signposted</strong> to the Measure 60 Climate Friendly Homes rebates where the required work overlaps (insulation, electrical, heat pump), so one visit serves both purposes</li><li><strong>Published quarterly:</strong> suites brought forward, suites legalized, median application-to-sign-off time, and the running count of net new legal rental units</li></ul><p>Every legalized suite is a rental home added to Victoria's counted stock at zero land cost and zero construction. It is the cheapest housing in this framework.</p>", "budget": "one FTE concierge plus inspection capacity at <strong>120 to 150K per year for the 24-month amnesty window only</strong>, funded from Measure 15 managed-competition savings on the same basis and with the same sunset discipline as the Measure 28b business-security pilot. Partially offset inside the window by permit fees on legalized suites and by the enforcement cost the City already carries on complaint-driven unpermitted-suite files. <strong>The measure does not enter steady-state cost.</strong> <strong>KPI:</strong> suites legalized against a Year 1 target set in the first quarter; median application-to-sign-off time; net new counted legal rental units."},
  {"id": "9", "pillar": "liveable", "section": "Housing: A City Where You Can Live", "tier": "core", "title": "Protect tenants from demoviction", "body": "<p><strong>The problem:</strong> Redevelopment is essential to grow housing supply (Measure 6), but redevelopment without tenant protection creates churn that destabilizes neighbourhoods and prices long-time renters out of the city. The goal is more housing AND fewer displacements — not one or the other.</p><p><strong>What we will do:</strong></p><ul><li><strong>Stronger controls when buildings are redeveloped</strong> — minimum notice periods (12+ months for major redevelopment), moving-cost compensation indexed to local rents, and a documented right-of-return for displaced tenants</li><li><strong>Mandatory replacement rental units</strong> — buildings that displace rental tenants must replace those units in the new development at a documented ratio, with priority access for displaced tenants at a published below-market rate</li><li><strong>Renters' Hub</strong> — a single digital and physical front door for tenant rights information, continuing the existing partnership with the Tenant Resource and Advisory Centre and on the Coun. Krista Loughton / Coun. Dave Thompson 2025 motion concept. Plain-language guides on RTA process, sample letters, direct referral to legal aid</li><li><strong>Tenant assistance program during transitions</strong> — case management for vulnerable tenants (seniors, people with disabilities, language-barrier) facing displacement</li><li><strong>Coordinate with provincial enforcement</strong> — the Residential Tenancy Branch and the Compliance and Enforcement Unit handle most landlord-tenant disputes; the City's role is information, support, and aggressive advocacy for stronger provincial enforcement (per Measure 70b)</li></ul><p>More housing, not fewer tenants. Growth and protection go together.</p>", "budget": "$200K/year for Renters' Hub operations and case management. Largely revenue-neutral on enforcement (provincial jurisdiction). Significant indirect savings: a tenant who is helped to stay in their unit is a tenant who does not enter the homelessness pipeline (Measure 11)."},
  {"id": "9b", "pillar": "liveable", "section": "Housing: A City Where You Can Live", "tier": "sub", "title": "Short-term rental licensing — protect the long-term rental pool", "body": "<p>Tighten short-term rental (STR) licensing, enforcement, and platform-data reporting. STRs convert long-term rental units into part-time tourist accommodation, tightening vacancy in exactly the moment we are working to expand it. Within the BC framework, the City will: require platform-side licence display and data sharing on every listing; cap non-principal-residence STRs; cross-reference STR addresses against business licence and property tax records; impose meaningful penalties for unlicensed operation that escalate per offence; publish a quarterly STR compliance report by neighbourhood. <em>This measure addresses residential rental supply. The related but separate problem of commercial downtown storefront vacancy is handled under Measure 71.</em> <strong>Same function, adjacent duty — grant and contract condition compliance.</strong> The compliance capacity built for STR licensing is the same capacity required to verify that municipal grant and contract conditions were actually met. The City currently disburses grants against stated conditions and rarely verifies them afterward. The compliance officer's mandate will extend to: <strong>condition verification</strong> on municipal grants above the Measure 65 review threshold — was the money spent on what the application said; <strong>recovery of misapplied municipal funds</strong> where conditions were breached, through existing contractual repayment provisions; and a <strong>published annual summary</strong> of conditions verified, breaches found, and amounts recovered. <strong>Scope limit, stated deliberately:</strong> this covers municipal grants and municipal contracts only. It has no role in provincial or federal income assistance, disability benefits, or health programs — those are neither the City's money nor the City's jurisdiction. The City audits its own spending, and nobody else's residents.</p>", "budget": "$200K/year for an STR compliance officer + platform-data audit tools. Self-funding through licensing fees and penalty revenue within 2 years. Grant-condition verification adds ~0.25 FTE ($30–40K/year), typically recovered several times over in identified misapplication."},
  {"id": "9c", "pillar": "liveable", "section": "Housing: A City Where You Can Live", "tier": "sub", "title": "Advocate for vacancy control between tenancies", "body": "<p>Vacancy control between tenancies — limiting rent resets to tied-to-unit rather than tied-to-tenant — is provincial jurisdiction under the Residential Tenancy Act. The City does not control it. But the City can be a credible advocate. Council will pass a formal advocacy resolution calling on the Province to introduce inter-tenancy rent control on the model of Manitoba and parts of Quebec, conditional on offsetting protections for landlord operating-cost recovery so that maintenance investment is preserved.</p>", "budget": "$0 (advocacy only). Real impact requires provincial action."},
  {"id": "10", "pillar": "liveable", "section": "Housing: A City Where You Can Live", "tier": "core", "title": "Transparent housing allocation — digital, rules-based, no queue-jumping", "body": "<p>Modernize social housing waitlist coordination with a clear, digital process inspired by the best allocation systems in the world.</p><p><strong>How it works (within municipal authority — BC Housing remains the social housing operator):</strong></p><ul><li><strong>A single digital portal</strong> for City-affiliated waitlists and partner non-profits: upload your documents once. No more filling out multiple applications at different providers</li><li><strong>Transparent point-based scoring:</strong> criteria are public and rational. Sample weights: working in Victoria (+50), essential worker in healthcare/childcare/emergency services (+20), single parent (+20), disability in the household (+50), family with 3+ children (+10), time on waitlist (+1 per month, max 10)</li><li><strong>Real-time visibility:</strong> you see your position in the queue, the number of units available, the number of units coming available in the next months, and your probability of receiving an offer</li><li><strong>No outside intervention possible.</strong> No queue-jumping, no political favours. The algorithm assigns based on points</li><li><strong>Alerts:</strong> you receive a notification when a unit matching your criteria becomes available. You accept or decline. After three declines, you are moved to the back of the queue</li></ul><p>This replaces opaque processes with full transparency. It also optimizes occupancy — matching partial-week needs, flagging units sitting vacant, and maximizing the use of every available space.</p>", "budget": "$250K for platform development and maintenance. Savings of 3–5 FTEs in manual waitlist administration (~$300K–500K/year). Net: $50K–250K/year savings, with dramatically better service."},
  {"id": "11", "pillar": "liveable", "section": "Housing: A City Where You Can Live", "tier": "core", "title": "Reduce unsheltered homelessness by 50%", "body": "<p><strong>Currently:</strong> The Alto council has spent <strong>$25M+ on homelessness response since 2023</strong> without publishing outcome metrics, plus <strong>$11M repairing encampment damage</strong>. The 2025 Point-in-Time count found 1,749 people experiencing homelessness across the Capital Region, up from 1,665 in 2023 (<em>Globe and Mail</em>). The Community Safety and Well-Being plan was not endorsed until June 2025 — nearly three years into the term — and its Phase 1 was funded by raiding reserves rather than by operational savings.</p><p><strong>ACTW:<strong> Reduce unsheltered homelessness by 50% — from ~320 to under 160 — through Housing-First: supportive housing with wraparound mental health and addiction services, in partnership with BC Housing and local non-profits. </strong>With published outcome metrics, not just dollars spent.</strong></p><p>This is not about enforcement alone — it is about offering genuine alternatives and then enforcing consistently. You cannot enforce people off the streets if there is nowhere for them to go. <strong>The principle: build capacity first, then enforce, and never move people to nowhere — with published outcomes, not just published spending.</strong> Victoria bears a <strong>vastly disproportionate regional burden</strong>: 89% of shelter beds and 83% of supportive housing for the entire Capital Region, despite being one of 13 municipalities. Since 2017, the Province has funded 4,120+ homes in Victoria through BC Housing, with major projects like the 158-unit tower at 926–930 Pandora and 90 supportive units at 726 Discovery Street (<em>BC Gov News</em>). <strong>We will continue and accelerate these provincial partnerships</strong> — they are working. We will demand the other 12 municipalities take their fair share — and we will hold the Province accountable for every dollar spent by publishing outcomes, not just inputs. <strong>Throughput, not just intake — adopt a STEP-style program.</strong> Supportive housing in Victoria is effectively full at all times, even as people remain unsheltered. The bottleneck is <em>throughput</em>: residents who have stabilized are not transitioning out to market or non-market housing, so units stay occupied and new entrants have nowhere to go. On the Coun. Krista Loughton January 2026 motion and the Vancouver Streetohome / BC Housing / Vancouver Coastal Health STEP (Supporting Tenants, Enabling Pathways) model, the City will partner with BC Housing, Island Health, and Pacifica Housing to operate a transition program: case-managed pathway from supportive housing → bridging non-market rental → market rental, with maintained service connection through each step. Free up the supportive units; do not just add to them. Coordinated Access and Assessment (per the June 2025 Loughton/Thompson motion) is the intake side; STEP is the exit side. Both are required.</p><p><strong>Dollars-to-outcomes — what we will publish every quarter (per Measure 67):</strong></p><ul><li><strong>Cost per successful housing placement</strong>, by program and funding source — not just total dollars deployed</li><li><strong>STEP throughput</strong> — supportive-to-market and supportive-to-non-market transitions completed, and average time-to-transition</li><li><strong>Returns to homelessness</strong> within 12 months of placement</li><li><strong>Occupancy and turnover</strong> across shelter and supportive-housing stock</li><li><strong>Service-offer acceptance and refusal rates</strong> (per Measure 35)</li></ul><p>The current council reports dollars spent. We will report what the dollars achieved. Any program that cannot demonstrate its cost per successful outcome is restructured or reviewed under zero-based budgeting (Measure 65).</p>", "budget": "City's share estimated at $2–3M/year above current spending. Offset partially by reduced emergency-services costs ($11M in encampment damage repair would be dramatically reduced) and bylaw enforcement burden (currently consuming 80% of officer time). Requires provincial co-funding for supportive housing operations."},
  {"id": "12", "pillar": "liveable", "section": "A City That Works for Families", "tier": "core", "title": "Advocate aggressively for 500 new childcare spaces", "body": "<p>Childcare is provincially regulated, but the City controls zoning, permits, and city-owned buildings. We will use every municipal lever available:</p><ul><li><strong>Fast-track permits for childcare facilities</strong> — any new childcare centre application processed in 60 days or less</li><li><strong>Pre-zone community buildings, churches, and commercial spaces for childcare use</strong> — eliminate the rezoning step that adds 6–12 months</li><li><strong>Offer city-owned space at below-market rates to licensed childcare operators</strong> — we have community centres and buildings that are underused during daytime hours</li><li><strong>Advocate to the Province for priority housing for Early Childhood Educators</strong> — ECE workers earn $20–25/hour but cannot afford to live in the city where they work. If they can't afford to live here, they don't work here, and your children don't have childcare</li></ul>", "budget": "$300K/year in foregone lease revenue from city-owned spaces. Offset by increased labour force participation of parents (more property and business tax revenue). Advocacy to Province: $0 direct cost."},
  {"id": "13", "pillar": "liveable", "section": "A City That Works for Families", "tier": "core", "title": "Improve school food quality", "body": "<p>Victoria's school food programs should serve local, BC-sourced ingredients wherever possible. We will:</p><ul><li>Work with School District 61 to establish a \"Farm to School\" standard for school meal programs, prioritizing Vancouver Island producers</li><li>Partner with local chefs to redesign cafeteria menus — real food, made fresh, that children actually want to eat</li><li>Publish daily meal photos on school communication apps — parents see exactly what their children are served</li></ul><p>This is not the City's direct jurisdiction (education is provincial), but the City can convene, co-fund, and champion. It costs little and delivers enormous community goodwill.</p>", "budget": "$150K/year in City co-funding for local procurement premium. Leverages existing School District and provincial nutrition program budgets."},
  {"id": "13b", "pillar": "liveable", "section": "A City That Works for Families", "tier": "sub", "title": "Recruit family doctors with low/no-rent clinic space + permissive tax exemption", "body": "<p>Victoria, like much of BC, faces an acute family-doctor shortage. Healthcare is provincial jurisdiction, but the City controls property tax, zoning, and municipal real estate — three levers that materially affect where clinics can afford to operate. On the precedent of the Andrew 2022 platform plank and the Alto 2022 \"permissive tax exemptions for not-for-profit clinics\" commitment (still not delivered), the City will:</p><ul><li><strong>Permissive tax exemptions for not-for-profit primary care clinics</strong> under section 224 of the Community Charter, on the precedent of similar exemptions for not-for-profit social service providers</li><li><strong>Below-market lease of city-owned or city-affiliated space</strong> to recruited family practices, with affordability and bulk-billing conditions</li><li><strong>Fast-track permitting</strong> for new clinic builds and conversions, on the same timeline as childcare facilities (Measure 12)</li><li><strong>Co-funded recruitment partnership</strong> with Island Health and the Province for family doctors willing to commit to Victoria for a minimum term</li><li><strong>Housing as a recruitment tool</strong> — the Measure 6b land bank and the Measure 6 composition targets applied to health-professional attraction. Practitioners cite housing cost as a primary barrier to practising here, and it is the one barrier the City can actually move</li><li><strong>A published number</strong> — net new primary-care practitioners practising in Victoria, and where Island Health data permits, the share of Victoria residents attached to a family practice, reported annually on the quarterly dashboard (Measure 67). A measure without a number is a wish</li><li><strong>Regional coordination</strong> with Saanich, Oak Bay, and Esquimalt through the CRD. Attachment does not stop at a municipal boundary, and competing municipal incentive packages would waste public money on both sides of the line</li></ul><p><strong>What we will not claim.</strong> Health care delivery, physician compensation, and practice models are provincial. The City can make Victoria an easier and cheaper place to open and keep a practice. It cannot recruit doctors, and any candidate who says otherwise is promising someone else's job.</p>", "budget": "Foregone property tax and lease revenue: $200–400K/year at full uptake. Direct return is a healthier, more productive resident base; family-doctor access correlates strongly with reduced emergency-room utilization and is a top citable factor in resident retention surveys."},
  {"id": "13c", "pillar": "liveable", "section": "A City That Works for Families", "tier": "sub", "title": "Reach Victoria's young adults (18–25)", "body": "<p>Victoria's families and seniors are reasonably well-served by existing City programming. Its <strong>young adults</strong> — particularly those aging out of school programs, transitioning to independent housing, or new to the city for work or post-secondary education — are not. The result is out-migration of exactly the demographic the city depends on for its future. The City does not deliver youth services directly (BC and federal jurisdiction), but it controls space, programming budgets, and partnerships:</p><ul><li><strong>Youth-priority slots in below-market City-owned and -leased space</strong> for organizations serving 18–25 — including the Victoria Native Friendship Centre's youth programming, employment-training partners, and post-secondary partnership programs</li><li><strong>Late-evening recreation and community-centre hours</strong> in dedicated facilities, priced for off-peak access (free or near-free)</li><li><strong>Youth fare partnership</strong> with BC Transit — work toward continuation and expansion of existing youth and student fare structures</li><li><strong>Annual Youth Voice consultation</strong> with measurable response standards (per Measure 79) and youth representation on advisory committees affecting their neighbourhoods</li><li><strong>Co-investment with Camosun, UVic, and Royal Roads</strong> on student-housing and student-employment partnerships rooted in Victoria proper</li></ul>", "budget": "$200–300K/year for youth-priority space, late-hours operations, and consultation. Leverages existing School District, post-secondary, and provincial programming budgets at significant multiplier."},
  {"id": "13d", "pillar": "liveable", "section": "A City That Works for Families", "tier": "sub", "title": "A standing agreement with School District 61", "body": "<p><strong>Currently:</strong> School trustees are elected on the same October 17 ballot as council, and the two bodies share the same residents, the same streets, the same children, and in several cases the same land. The relationship is nonetheless ad hoc. This framework touches School District 61 in three places — school food (Measure 13), school-zone speed cameras (Measure 40), and Royal Athletic Park programming (Measure 52) — with no standing mechanism behind any of them. Education is provincial jurisdiction and this measure does not pretend otherwise. Crossing guards, playing fields, gyms, playgrounds, safe walking routes, and childcare siting are municipal or joint. <strong>ACTW:</strong> One agreement, one annual public meeting, one published work plan.</p><ul><li><strong>A standing joint agreement with School District 61</strong>, with a published annual work plan and a joint council-and-board meeting held in public once a year</li><li><strong>A joint-use agreement for facilities</strong> — school gyms, fields, and playgrounds available to residents and community sport outside school hours; City facilities available to schools during them. This is standard practice in comparable BC municipalities and it is the cheapest recreation capacity a city can add, because the buildings already exist. Same utilization logic as Measure 52</li><li><strong>Safe routes to school as a program, not a complaint queue</strong> — crossing guard coverage reviewed annually against enrolment and collision data, school-zone infrastructure delivered per Measure 40, walking-route gaps prioritized in the Measure 20b sidewalk inventory, and a published route map for every school</li><li><strong>Childcare on school sites</strong>, pursued jointly under Measure 12, where the Province funds the spaces and the binding constraint is land and building</li><li><strong>Playing field capacity and condition planned jointly</strong> rather than in parallel, feeding Measure 52</li><li><strong>A single named City contact</strong> for the District, published, so neither body is negotiating through councillors' inboxes (per Measure 79c)</li></ul>", "budget": "0 to 50K per year for coordination, absorbed within existing recreation and planning operations. <strong>Joint-use agreements are typically net-positive:</strong> shared facility access substitutes for capital the City would otherwise build. Crossing guard coverage is an existing line, reviewed rather than expanded. <strong>KPI:</strong> agreement signed within 12 months; joint public meeting held 1 of 1 years; published safe-route map per school; hours of joint-use facility access delivered."},
  {"id": "14", "pillar": "liveable", "section": "A Clean City", "tier": "core", "title": "90% of graffiti removed within 48 hours", "body": "<p>Rapid-response cleaning crews, expanded DVBA Clean Team contracts, real-time dispatch through the ConnectVictoria app. Establish this as a published service standard, tracked and reported quarterly. <strong>Continuing the DVBA partnership.</strong> The DVBA Clean Team removes over 12,000 graffiti tags per year — it is one of the most effective public-realm partnerships the City has. We will continue and expand the partnership, not replace it. The 48-hour standard is the discipline; the partnership is how we deliver it.</p>", "budget": "$0 net new. Graffiti removal is an existing Public Works Surface Infrastructure function and the DVBA Clean Team partnership already operates. This measure sets a service standard and publishes the result, rather than adding crews. <strong>If the 90% standard cannot be met from existing resourcing after two quarters of published data, the shortfall is costed and brought to council as a budget item rather than quietly missed.</strong> <strong>KPI:</strong> share removed within 48 hours and median report-to-removal time, published quarterly under Measure 67."},
  {"id": "15", "pillar": "liveable", "section": "A Clean City", "tier": "core", "title": "Competitive testing for waste collection and street cleaning — both directions, same specification", "body": "<p><strong>Currently:</strong> Victoria's roughly $12M/year in waste collection and street cleaning operates without any competitive benchmarking. The City does not know whether it pays market rates because it has never tested the market. <strong>ACTW:</strong> Cities that have introduced competitive bidding for waste collection and street cleaning have delivered substantial multi-year savings while improving service quality. <strong>Phoenix's managed competition program saved the city in excess of $25 million between 1978 and 1988 alone</strong> (<em>Frontier Centre for Public Policy, citing City of Phoenix Public Works records</em>) — the model is mature, well-documented, and has been adopted across North America. The private sector's core business is logistics and cleaning; their survival depends on better equipment, better routing, and better training.</p><p><strong>How we will do it:</strong></p><ul><li>Divide Victoria into zones and run a competitive process for each zone</li><li><strong>Test both directions.</strong> Every contract cycle, the City's own operation submits a costed bid alongside private bidders, on the same specification, scored the same way. The cheaper competent option wins. This is the Phoenix managed-competition model as it was actually built: City crews bid in every tender, and on the record there they frequently won (<em>GovTech</em>)</li><li>Require all bidders, City and private, to meet the same performance standards: response times, cleanliness scores, citizen satisfaction surveys</li><li><strong>Employee protection is not contingent on who wins:</strong> at least 80% of existing City workers in these roles must be offered equivalent positions at equal or higher pay by any winning bidder, and no worker is displaced by a process that concludes the City was already competitive</li><li><strong>Publish every bid comparison,</strong> including the ones the City wins</li><li>The City retains oversight and audits performance quarterly. Underperformance triggers re-tender, whoever holds the contract</li></ul><p><strong>Year-2 candidate functions — contingent, gated, published in advance.</strong> If — and only if — the waste and street-cleaning tender delivers, the same model will be tested on one or two additional functions in Year 2. Candidates: <strong>facilities maintenance, grounds and parks maintenance, and fleet servicing.</strong> The gates: audited savings at or above the 20% target; contracted service standards met for four consecutive quarters; the 80% re-hire floor demonstrably honoured, verified against payroll; and no net degradation in the public-realm KPIs reported under Measure 67. If any gate is missed, no further function is tendered this term. The condition is real — under the Phoenix managed-competition model, City workers bid in every tender, and on the record there they frequently win. <strong>Insourcing is a permitted outcome, not a failure.</strong> Cannes brought previously contracted urban-cleanliness work back in-house as part of a multi-year savings program, on the finding that in-house delivery was cheaper at that specification. If Victoria's own crews win the bid, that is the measure working as designed. The point is never to privatize. The point is to stop paying an untested price. This is not ideology — it is the same approach that has worked in cities across Canada and internationally. The CRD's own blue-box recycling is already contracted to GFL Environmental — the principle is proven regionally. <strong>On the savings target.</strong> The ~$2.4M/year figure is a property of the <em>specification</em>, not of the winner. A City bid that meets the standard at 20% below current cost delivers the same saving as a private bid at the same price, and the measures funded from it (Measure 27 extended bylaw hours, Measure 28b business-security pilot) are unaffected by which party wins.</p>", "budget": "Current waste and street cleaning costs: ~$12M/year. Expected savings at 20% (a conservative target consistent with documented multi-year programs elsewhere): <strong>$2.4M/year.</strong> Workers protected. Service improved. Savings redirected to frontline priorities, including the funded source for extended bylaw hours (Measure 27)."},
  {"id": "16", "pillar": "liveable", "section": "A Clean City", "tier": "core", "title": "Anti-rat and pest management plan", "body": "<p>Rat proliferation is a direct consequence of poor sanitation. The best anti-rat measure is removing food sources at street level.</p><ul><li>Locking lids on commercial waste bins — bins that open only when tipped by collection trucks</li><li>QR codes on public waste bins: residents scan to report a full bin, and crews are dispatched in real time</li><li>Dedicated pest control team using modern methods: dry ice, smart traps, grate covers on storm drains</li><li>Coordination with restaurant and food service operators on waste storage standards</li></ul>", "budget": "$200K/year for enhanced pest management. QR bin system: $50K setup, $20K/year maintenance. Offset by reduced property damage and health complaints."},
  {"id": "17", "pillar": "liveable", "section": "A Clean City", "tier": "core", "title": "Extended sanitation hours", "body": "<p>Daily street sweeping and bin emptying in the downtown core, including evenings and weekends. Clean when it matters, not just during office hours.</p>", "budget": "$0 net new, because extended hours are written into the service specification that both the in-house crew and any external bidder must price under Measure 15. The hours are procured, not added. Any cost above the current envelope is reported against the Measure 15 saving before a contract is awarded, and if extended hours cost more than they save, the specification is what changes, not the tax rate."},
  {"id": "18", "pillar": "liveable", "section": "A Clean City", "tier": "core", "title": "Community pride — replace graffiti with public art", "body": "<p>Expand the \"My Great Neighbourhood\" grants for community gardens, murals, and block clean-ups. Commission neighbourhood-specific murals and installations — art that tells Victoria's story: lək̓ʷəŋən history, maritime heritage, natural beauty. Neighbourhoods that take ownership stay clean.</p>", "budget": "$0 net new. Delivered from the City's existing public art budget, which the adopted 2026 plan carries at $207K for creation and $165K for maintenance, by directing a share of it to the surfaces that are repeatedly tagged. Community and school painting partnerships supply labour the City would otherwise pay for."},
  {"id": "19", "pillar": "liveable", "section": "A City Where You Can Get Around", "tier": "core", "title": "Adaptive traffic signal control on major corridors", "body": "<p>Progressively, traffic signals on Victoria's major corridors will be connected to an adaptive control system that adjusts signal timing in real time based on:</p><ul><li><strong>Local conditions at each intersection:</strong> if a queue threatens to block an adjacent intersection, the light stays green longer to prevent the bottleneck from spreading</li><li><strong>Corridor-level conditions:</strong> detecting congestion patterns, identifying streets to relieve, holding access roads at red longer to prevent saturation of main arteries</li><li><strong>Continuous learning:</strong> the more the system observes traffic patterns and driver behavior, the better it optimizes</li></ul><p>Pittsburgh's Surtrac adaptive control system, deployed at ~50 intersections, reduced travel times by 25% and emissions by 21% (<em>Carnegie Mellon Robotics Institute</em>). A 2024 study published in <em>Nature</em> of 100 cities with adaptive signals found an 11% average reduction in travel time during peak hours, 8% off-peak, with Boston reporting 13.5%.</p><p><strong>Realistic phased rollout:</strong></p><ul><li><strong>Year 1: Pilot of 10 intersections</strong> on the Douglas Street corridor, fully instrumented (controllers, detection, fibre/wireless backhaul, central software): <strong>$1.5–2M</strong></li><li><strong>Year 2–3: Evaluate pilot, then expand to 30–40 additional intersections on major corridors</strong> (Hillside, Blanshard): <strong>$3–4M</strong></li><li><strong>Year 4: Optionally extend to remaining major corridors</strong> based on measured results: <strong>$2–3M</strong></li></ul>", "budget": "Total investment over 4 years: <strong>$6–9M</strong> (revised from earlier estimates to reflect realistic per-intersection costs of $30K–100K including controller, detection, backhaul, software, and integration — not sensors alone). Annual maintenance: $300K/year at full deployment. Savings in commuter time and fuel: significant but hard to quantify. Reduction in emissions: measurable and reportable. <strong>Critical:</strong> do not proceed to Phase 2 without measured outcomes from Phase 1 against published baselines."},
  {"id": "20", "pillar": "liveable", "section": "A City Where You Can Get Around", "tier": "core", "title": "Complete the All Ages & Abilities bike network", "body": "<p>Close gaps in the 36 km built so far, extend protected lanes into neighbourhoods, improve bike parking and end-of-trip facilities. Physical separation from traffic — not painted lines. Victoria has the cycling culture; we need the infrastructure to match. <strong>Claim the success, then extend it.</strong> Victoria has <strong>36 km of All Ages and Abilities routes</strong> built since 2017, <strong>95% of residents within 500 metres</strong> of a safe cycling route — the highest share in Canada — and the country's highest bike-to-work rate at <strong>5.3%</strong> (<em>CBC News</em>). That is a genuine achievement of successive councils and this framework says so plainly. It is also unfinished: the network has known discontinuities, the standard varies segment to segment, and maintenance is inconsistent.</p><ul><li><strong>A published network gap map</strong> in Year 1, built from the Measure 53 GIS layers rather than a new survey contract, showing every discontinuity, substandard segment, and unprotected crossing on the AAA network</li><li><strong>A published coverage target</strong> — from 95% of residents within 500 metres to <strong>100% within 400 metres by 2030</strong>, reported annually in kilometres delivered. Capital is drawn from the existing active-transportation envelope with federal Active Transportation Fund cost-share pursued per Measure 70. <strong>No new capital is created by this target.</strong> If cost-share does not materialize, the timeline extends and we say so rather than quietly missing it</li><li><strong>Annual reporting</strong> on kilometres, coverage percentage, and cycling mode share on the quarterly dashboard (Measure 67)</li></ul><p><strong>Conditional tier, gated on verified savings.</strong> Two further commitments are real costs and are therefore <strong>not</strong> booked in the Balance Sheet. They proceed in Year 2 only if the Measure 15, Measure 65, and Measure 68 savings are verified as tracking at the end of Year 1:</p><ul><li><strong>A maintenance standard for the AAA network</strong> — sweeping, leaf and debris clearance, winter treatment, surface repair, and lighting (per Measure 37), with a published response time. A protected lane full of gravel is not a protected lane. <strong>150 to 250K per year</strong></li><li><strong>End-of-trip facilities</strong> — secure bike parking at civic facilities and in the downtown core, bike parking minimums in new development, and <strong>bike valet at major civic events</strong>, on Coun. Susan Kim's 2022 plank. <strong>100 to 150K per year</strong></li></ul>", "budget": "Gap map and coverage reporting: no incremental cost, produced from Measure 53 GIS. Network extension capital is a named allocation inside the existing active-transportation envelope with senior-government cost-share, not new capital. The maintenance standard and end-of-trip facilities are a gated conditional tier of <strong>250 to 400K per year</strong>, excluded from the Balance Sheet until the Year 1 savings verification, on the same discipline applied to the Measure 64b retrofit capital and the Measure 45c signature project. <strong>KPI:</strong> gap map published within 12 months; kilometres delivered and coverage percentage reported 4 of 4 quarters."},
  {"id": "20b", "pillar": "liveable", "section": "A City Where You Can Get Around", "tier": "sub", "title": "A walking city — sidewalks, crossings, and a published pedestrian standard", "body": "<p><strong>Currently:</strong> Victoria is a walkable city by geography and an inconsistent one by infrastructure. Walking is the mode used by every resident, including every transit rider at both ends of every trip, and it is the only mode in this framework with no commitment of its own — it appears inside the cycling, accessibility, waterfront, and pedestrianization measures and nowhere on its own. The City publishes no sidewalk gap inventory, no crossing-spacing standard, and no obstruction-clearance response time. <strong>ACTW:</strong> Walking gets its own commitment, its own numbers, and its own line on the dashboard.</p><ul><li><strong>A published sidewalk gap inventory</strong> in Year 1, built from the Measure 53 GIS layers rather than a new survey contract, mapping every block with a missing, substandard, or one-sided sidewalk, ranked by school route, transit-stop proximity, seniors' housing, and commercial frontage</li><li><strong>A published annual construction figure</strong> — kilometres of sidewalk gap closed per year, reported quarterly, funded as a <strong>named allocation inside the existing Measure 25 road capital envelope</strong> rather than as new money, and prioritized by the inventory ranking rather than by request volume</li><li><strong>A crossing standard</strong> — a published maximum spacing between controlled or protected crossings on arterial and collector streets, with the gap list published and closed on a schedule. Where a crossing cannot be signalized, a marked and lit crossing with curb extensions is the minimum</li><li><strong>Signal timing that assumes people walk at real speeds</strong> — delivered inside the Measure 19 adaptive signal rollout at no incremental cost: pedestrian clearance intervals timed to 1.0 metres per second rather than the 1.2 default, leading pedestrian intervals at every high-conflict downtown intersection, and no beg buttons on primary downtown crossings</li><li><strong>An obstruction and hazard clearance standard</strong> with a published response time for blocked sidewalks, construction encroachments, overgrowth, ice, and leaf accumulation, reported alongside the Measure 25b accessibility set</li><li><strong>Wayfinding</strong> on the pedestrian network in the Inner Harbour, downtown, and commercial corridors, integrated with the Measure 24b washroom map and the Measure 56 open data portal</li><li><strong>A published pedestrian collision and serious-injury figure by location</strong>, feeding the Measure 38 dangerous-intersection redesign list and the 12 Commitments scorecard</li></ul><p>Walking is not a subset of cycling and it is not a subset of accessibility. It is how the city is actually used.</p>", "budget": "Inventory and crossing-gap analysis <strong>60 to 80K one-time</strong>, substantially reduced by sequencing with the Measure 53 GIS work and the Measure 53c LIDAR scan. Standards development and program administration <strong>50K per year</strong>, absorbed within the Measure 68 attrition and technology envelope. Signal-timing changes carry no incremental cost and are delivered inside Measure 19. <strong>Sidewalk and crossing construction is a named allocation inside the existing Measure 25 capital envelope, not new capital</strong>, with federal Active Transportation Fund cost-share pursued per Measure 70. <strong>KPI:</strong> inventory published within 12 months; kilometres of gap closed reported 4 of 4 quarters; crossing-gap list published and reducing."},
  {"id": "21", "pillar": "liveable", "section": "A City Where You Can Get Around", "tier": "core", "title": "Modernize transit fare payment", "body": "<p>Work with BC Transit to finally deliver contactless payment (credit, debit, mobile). Free Wi-Fi on buses and at hubs. This is table stakes for a modern transit system — Victoria is behind every comparable Canadian city.</p>", "budget": "$0 to the City. Fare technology is BC Transit's to procure and the Victoria Regional Transit Commission's to approve. This is an advocacy and Commission-voting commitment delivered through Measure 23b, which also publishes how Victoria's representatives voted. We are not going to claim credit for a decision that is not ours or bill residents for one we cannot make."},
  {"id": "22", "pillar": "liveable", "section": "A City Where You Can Get Around", "tier": "core", "title": "Champion Westshore rapid transit and the E&N corridor", "body": "<p>A growing proportion of Victoria's daytime workforce lives in Langford, Colwood, and View Royal. Peak commutes routinely exceed 60 minutes one way. The City of Victoria does not control inter-municipal transit (that is BC Transit and provincial jurisdiction), but it sits at the geographic and political centre of the region and benefits massively from a functional regional network. <strong>Cross-bloc municipal work.</strong> Regional transit on the Westshore corridor is one of the rare points of multi-councillor and cross-municipality alignment — Coun. Jeremy Caradonna's CRD vice-chair role on regional housing connects to it, Mayor Alto's 2026 \"reimagine transportation\" plank touches it, and the Westshore mayors (Stewart Young in Langford, Doug Kobayashi in Colwood, Karen Harper in View Royal) have all signalled support in principle. Victoria's job is to refuse to be the regional bottleneck.</p><p><strong>The City will:</strong></p><ul><li><strong>Formally endorse Light Rail or Bus Rapid Transit on the E&amp;N corridor</strong> as the highest-priority regional transit investment, and request acceleration of the Province's South Island Transportation Strategy</li><li><strong>Protect the E&amp;N right-of-way for transit use</strong> within Victoria's boundaries through zoning and infrastructure decisions — no encroachment that forecloses future rail or BRT operation</li><li><strong>Co-fund station-area planning</strong> with the CRD and Westshore municipalities so that when provincial funding arrives, receiving infrastructure is ready</li><li><strong>Provide dedicated bus lanes on Douglas Street and Trans-Canada approaches</strong> to keep RapidBus 95 competitive with driving in the meantime</li><li><strong>Use the working table with the host Nations</strong> (Measure 1) to ensure E&amp;N planning respects treaty and reserve geography from day one, not as an afterthought</li></ul><p>A functional Westshore connection takes pressure off Victoria's own housing market, supports downtown employers, and reduces the carbon and congestion costs of single-occupancy commuting. The City cannot build it alone, but it can refuse to be the bottleneck.</p>", "budget": "$300K/year for dedicated transportation planning staff and CRD / provincial co-funding contributions. Long-term capital is provincial / federal."},
  {"id": "23", "pillar": "liveable", "section": "A City Where You Can Get Around", "tier": "core", "title": "Expand RapidBus and dedicated bus lanes", "body": "<p>Make transit time-competitive with driving on Douglas, Hillside, and other major corridors. If the bus is faster than the car, people will take the bus. If it isn't, they won't.</p>", "budget": "Transit priority on City streets is a named allocation inside the existing transportation capital envelope, per Measure 23b, not new capital. RapidBus service hours are BC Transit's cost, and Victoria's local share is bounded by the Measure 66 cap by construction. <strong>KPI:</strong> kilometres of bus priority delivered, and measured travel-time change on Douglas and Hillside, published annually."},
  {"id": "23b", "pillar": "liveable", "section": "A City Where You Can Get Around", "tier": "sub", "title": "Transit — what the City controls, what it will fund, and how it votes", "body": "<p><strong>Currently:</strong> Transit service in Victoria is planned and operated by BC Transit and funded and governed through the Victoria Regional Transit Commission. Routes, frequency, fares, fleet, and labour are not municipal decisions. This is the single most common place where municipal candidates promise what they cannot deliver, and residents have learned to discount transit promises accordingly. Victoria's actual levers are real but nowhere stated: street space, signal priority, curb allocation, stop and shelter infrastructure on City right-of-way, the sidewalk connections that make a stop usable, land use along corridors, and its representation on the Commission. <strong>ACTW:</strong> Say exactly what is ours, put money against it, and publish how we vote on the rest.</p><p><strong>What the City controls, and will fund:</strong></p><ul><li><strong>A named annual transit priority capital line</strong> for bus lanes, queue jumps, transit signal priority, boarding bulbs, and stop accessibility, allocated <strong>inside the existing transportation capital envelope</strong> and reported by project. Douglas Street and the Trans-Canada approaches first, per Measure 22</li><li><strong>Transit signal priority delivered inside Measure 19</strong> at no incremental cost, on every corridor the adaptive system reaches</li><li><strong>Curb and land-use decisions that do not foreclose transit priority</strong>, and station-area planning co-funded per Measure 22</li></ul><p><strong>What the City does not control, and will not pretend to:</strong></p><ul><li><strong>A published annual City transit position</strong>, adopted by Council in open session before the Commission's budget cycle, stating Victoria's position on service hours, frequency, fare policy, and the local share — carried by Victoria's Commission members and reported against publicly each year (extends Measure 79c). Commission members are appointed under the <em>British Columbia Transit Act</em> rather than elected to the Commission, so this is a published position and a reporting duty, not a direction to vote. We will not describe it as more than it is</li><li><strong>A published record of Commission decisions affecting Victoria</strong> on the quarterly dashboard (Measure 67), so residents can see what was decided on their behalf</li><li><strong>A stated funding posture</strong> — Victoria will fund its proportional local share of a BC Transit service expansion on the frequent network <strong>inside the Measure 66 tax cap</strong>, and will say so in advance rather than discovering it at budget. We will not commit to an open-ended share of a service plan we do not write</li><li><strong>Fare policy, honestly</strong> — contactless payment (Measure 21) is a BC Transit deliverable the City can press for and cannot deliver. We will report on the ask annually until it lands</li></ul><p><strong>Conditional tier, gated on verified savings.</strong> A <strong>published stop standard</strong> for every stop on a frequent route — accessible landing pad, connected sidewalk per Measure 20b, lighting per Measure 37, and shelter and seating where boardings justify it — at <strong>200 to 300K per year</strong>, proceeding in Year 2 only if the Measure 15, Measure 65, and Measure 68 savings are verified as tracking at the end of Year 1. It is excluded from the Balance Sheet until then.</p>", "budget": "Transit priority capital is a named allocation inside the existing transportation capital envelope, not new capital. The published position and decision record carry no incremental cost, absorbed within Measure 79c and Measure 67. The local-share commitment is bounded by the Measure 66 cap by construction. Stop-standard remediation is a gated conditional tier of 200 to 300K per year, excluded from the Balance Sheet. <strong>KPI:</strong> transit priority projects delivered against plan; City transit position and decision record published 1 of 1 years; share of frequent-network stops meeting the published standard once the tier is triggered."},
  {"id": "24", "pillar": "liveable", "section": "A City Where You Can Get Around", "tier": "core", "title": "Parking that supports business — rational pricing, real-time data", "body": "<p><strong>First-hour free parking in commercial areas.</strong> When you want to pop into a shop, grab a coffee, or pick up takeout, you shouldn't pay $3–5 just to park for 20 minutes. A free first hour supports local business, encourages foot traffic, and increases turnover. <strong>Real-time parking availability, without City street cameras.</strong> Approximately 30% of downtown traffic is drivers who have reached their destination but are circling for a spot. We will publish real-time space availability using <strong>City-owned parkade and surface-lot systems</strong> and <strong>non-imaging in-ground or optical occupancy sensors</strong> at metered on-street stalls, publishing <strong>space counts only</strong>, through the City's open data portal and integrations with major navigation apps. <strong>No City cameras on public streets and no retained identifiable imagery</strong>, consistent with Measure 30, Measure 28c, and Measure 53d. Occupancy sensors cost more per stall than cameras would. That is the price of the position, and it is worth paying. Less circling means: less traffic, less pollution, less noise, less wasted fuel, less frustration.</p>", "budget": "First-hour free: estimated $1.5–2.5M/year in foregone meter revenue (verified against actual downtown meter revenue, not the smaller estimate cited in some previous plans). Partially offset by increased commercial activity, business licence revenue, and turnover. Real-time parking system: $300K setup, $80K/year maintenance. <strong>Note:</strong> Direct sale of parking-availability data to navigation platforms is not a reliable revenue stream (mapping platforms derive parking signals from device telemetry, not municipal feeds). We do not budget revenue from data licensing."},
  {"id": "24b", "pillar": "liveable", "section": "A City Where You Can Get Around", "tier": "sub", "title": "Public bathrooms as transportation infrastructure", "body": "<p>On the Coun. Susan Kim 2022 platform plank: a city that asks residents and visitors to walk, cycle, take transit, and spend time in its public spaces must provide the basic dignity of a place to use a bathroom. Victoria's current network is sparse, poorly mapped, and inconsistently maintained — a daily problem for seniors, families with young children, people with medical conditions, transit users on long trips, and the vulnerable residents the city is trying to bring indoors.</p><ul><li><strong>Network expansion:</strong> at least one publicly-accessible 24/7 washroom every 500 metres in the downtown core, Inner Harbour, and major commercial corridors (Government, Douglas, Fort, Cook)</li><li><strong>Modern format mix:</strong> attended facilities where viable, automated kiosks (Sanisette-style) where attended is not</li><li><strong>Real-time location and status</strong> integrated with the ConnectVictoria app and open data portal (per Measure 56)</li><li><strong>Daytime extended access partnership</strong> with businesses and the DVBA in commercial areas</li><li><strong>Universal-design standard:</strong> every new facility built accessible to people with mobility devices, families with strollers, and people of all body sizes</li></ul><p>This is not a luxury. It is basic public-realm infrastructure. The DVBA Clean Team currently spends hundreds of hours per year on the consequences of insufficient facilities — a direct cost that disappears when the underlying need is met.</p>", "budget": "$400–600K/year operating at full deployment. $1.5–2M capital over the term for new units. Substantially offset by reduced sanitation calls and improved public-realm cleanliness scores (Measure 14)."},
  {"id": "25", "pillar": "liveable", "section": "A City Where You Can Get Around", "tier": "core", "title": "Fix roads first", "body": "<p>Prioritize the infrastructure maintenance backlog. Pothole repair targets: report-to-fix within 7 days. Road condition improvements tracked quarterly. Stop building new things while the old things crumble.</p>", "budget": "$0 net new. Road rehabilitation is already the largest line in the City's capital plan, carrying $11.5M for major street rehabilitation and $3.5M for local street rehabilitation in the adopted 2026 budget. This measure is a sequencing rule inside that envelope: condition-based prioritization, published quarterly. Measure 20b's sidewalk and crossing construction is a named allocation within the same envelope, not an addition to it."},
  {"id": "25b", "pillar": "liveable", "section": "A City That Works for Every Body", "tier": "sub", "title": "Universal accessibility audit and remediation program", "body": "<p>Treat accessibility as a city-wide infrastructure standard, not a one-off project.</p><ul><li><strong>Comprehensive accessibility audit</strong> of all City-owned sidewalks, public buildings, parks, washrooms, and transit-adjacent infrastructure over 24 months — using a published methodology (Rick Hansen Foundation Accessibility Certification or equivalent) and a public dashboard</li><li><strong>Remediation backlog</strong> funded as a dedicated annual capital line, prioritized by foot-traffic and population-density of residents with disabilities</li><li><strong>Universal-design standard</strong> for all new City builds and major renovations — best-practice, not minimum-code</li><li><strong>Curb cut, tactile paving, and audible-signal program</strong> at every controlled intersection within 4 years</li><li><strong>Sidewalk maintenance standard:</strong> response time for hazards and obstructions that disproportionately affect people with mobility devices</li><li><strong>Disability Advisory Committee with delegated review authority</strong> on major projects, integrated into the 5-step process (Measure 78)</li><li><strong>Accessibility lens</strong> required on all permitting and grant decisions</li></ul>", "budget": "Audit: $300K one-time. Remediation capital: $2–3M/year as a dedicated line, partially eligible for the federal Enabling Accessibility Fund and provincial co-funding. Disability Advisory Committee operating: $80K/year. The cost of inaccessibility — reduced participation, lawsuits, retrofit-after-build — is consistently higher than the cost of doing it right."},
  {"id": "26", "pillar": "safe", "section": "Strengthen Public Safety", "tier": "core", "title": "Create a Downtown Public Order Team (DPOT)", "body": "<p><strong>Currently:</strong> Public safety responses across VicPD, Bylaw, Public Works sanitation, and Outreach operate in silos. There is no unified command, no shared daily metrics, no single field supervisor per shift. The Alto council's CSWB plan added staff but did not change the operational structure. <strong>ACTW:</strong> One unified operation: VicPD + Bylaw + Public Works sanitation + Outreach workers. Single daily briefing at 8 AM, single set of weekly metrics, single field supervisor per shift. No more silos. During DPOT operating hours the team works from a <strong>single co-located operations desk</strong> rather than four separate buildings, so dispatch, bylaw, sanitation, and outreach see the same board at the same time. This is a co-location commitment within existing accommodation, not a new facility. This is the same principle that made the Olympic Games safe in every host city: unified command, constant presence, systematic intervention. There is no reason Victoria cannot have that level of coordination every day.</p><p><strong>DPOT Weekly Dashboard:</strong></p><div class=\"tbl-wrap\"><table class=\"dt\"><thead><tr><th>Category</th><th>KPI</th><th>Why It Matters</th></tr></thead><tbody><tr><td>Encampments</td><td># downtown encampments removed same-day</td><td>Visible order</td></tr><tr><td>Response</td><td>Median time from report → attendance</td><td>Accountability</td></tr><tr><td>Sidewalks</td><td># sidewalk obstructions cleared</td><td>Access/safety</td></tr><tr><td>Parks compliance</td><td>% shelters down by 7 AM in designated parks</td><td>Enforce existing rules</td></tr><tr><td>Public drug use</td><td># enforcement actions + referrals</td><td>Matches top concern</td></tr><tr><td>Needles</td><td># needles collected + hotspot map</td><td>Harm reduction + cleanliness</td></tr><tr><td>Outreach</td><td># placements to shelter/detox/services</td><td>Prevent churn</td></tr><tr><td>Crime focus</td><td># trafficking/weapon/violent-file actions</td><td>Target disorder drivers</td></tr></tbody></table></div>", "budget": "<strong>No separate DPOT budget is created.</strong> The team is a unified command structure over personnel the City already employs across Bylaw Services, Parks, Public Works and outreach coordination. The incremental staffing is the extended-hours cost of $1 to $1.5M per year, costed under Measure 27, and command, dispatch integration and the weekly reporting cycle are absorbed within that line. <strong>This measure is also the envelope that absorbs Measure 28c registry administration ($15 to $25K per year) and Measure 33b buffer-zone enforcement ($0).</strong> The Savings &amp; Revenue Analysis Part C1 now discloses both, so that no cost is charged to an envelope nobody can see."},
  {"id": "26b", "pillar": "safe", "section": "Strengthen Public Safety", "tier": "sub", "title": "Civilian crisis response — the right responder for the call", "body": "<p><strong>Currently:</strong> Measure 26 puts outreach workers inside the Downtown Public Order Team, which is the right structure. What it does not do is name the <em>response type</em>. A substantial share of the calls reaching VicPD and Victoria Fire are mental-health, wellness-check, and non-violent intoxication calls where a police or fire response is the available one rather than the appropriate one, and where the outcome is an emergency-room handoff. VicPD is <strong>50 to 55 officers short</strong> of authorized strength. Every call answered by the wrong responder is an officer unavailable for the calls only an officer can take. <strong>ACTW:</strong> Fund the responder that fits, and be honest about whose responsibility it is.</p><ul><li><strong>A civilian crisis response capacity</strong> for mental-health, wellness-check, and non-violent intoxication calls, staffed by trained crisis workers with clinical backup, <strong>dispatched from the same co-located board the Measure 26 team works from</strong> so there is one dispatch picture and not two</li><li><strong>Dispatch criteria published in advance</strong>, developed with VicPD, Victoria Fire, BC Emergency Health Services, and Island Health, stating which call types go to a civilian team, which go to police, and which go jointly. <strong>Ambiguity in dispatch criteria is what causes the wrong responder to arrive</strong>, and it is the part that is usually left unwritten</li><li><strong>A published diversion figure:</strong> calls diverted from police and fire response, outcomes by disposition, and hospital handoffs avoided, on the Measure 31 weekly dashboard and the Measure 67 quarterly dashboard</li><li><strong>Jurisdiction, stated plainly:</strong> mental health and addictions services are provincial, delivered through Island Health and BCEHS. The City can fund a partnership contribution, provide co-location, and press for provincial investment. <strong>It cannot operate a clinical service, and this measure does not claim it can</strong> (per Measure 70b)</li><li><strong>Complementary, not substitutional.</strong> This does not reduce the Measure 27 bylaw hours, the Measure 26 team, or the Measure 28 focused-deterrence work. <strong>Relentless with the dangerous, appropriate with the unwell.</strong> Those are not the same call and they have never been the same call</li></ul>", "budget": "City partnership contribution of <strong>200 to 350K per year, placed in the gated conditional tier and excluded from the Balance Sheet</strong>, on the same discipline as the Measure 20 maintenance standard and the Measure 23b stop standard. It proceeds <strong>only</strong> where a provincial or health-authority cost-share partner is confirmed, because municipally funding a clinical service outright is precisely the downloading Measure 70b exists to refuse. <strong>Absent a partner this measure is advocacy at zero cost, and we will report it that way rather than book it.</strong> <strong>KPI:</strong> dispatch criteria published before launch; calls diverted from police and fire response; hospital handoffs avoided."},
  {"id": "27", "pillar": "safe", "section": "Strengthen Public Safety", "tier": "core", "title": "Extend bylaw enforcement to 6 AM – 10 PM, 7 days a week", "body": "<p><strong>Currently:</strong> Bylaw enforcement operates <strong>7 AM – 4 PM weekdays only</strong> — missing the evenings and weekends when disorder actually peaks. The Alto council's CSWB Phase 1 added 12 bylaw staff but did not change the hours; <strong>80% of officer time is consumed by encampment management</strong> rather than general enforcement. <strong>ACTW:</strong> Extend bylaw enforcement to <strong>6 AM – 10 PM, 7 days a week</strong> — the hours when downtown is actually busy. Funded primarily by managed-competition savings on waste collection (Measure 15: ~$2.4M/year) — not by raising taxes or raiding reserves. <strong>Deployment follows the data, not the clock.</strong> Officer hours within the extended window are assigned by incident density using the Measure 28 hotspot data, not spread uniformly across shifts, and the resulting shift pattern is published so residents and businesses know when coverage exists. Cost-neutral: the same hours, allocated better.</p>", "budget": "$1–1.5M/year for additional bylaw officer shifts (revised upward to reflect collective agreement overtime/shift premiums). Funded primarily by managed competition savings on waste collection ($2.4M/year) — not by raiding reserves or raising taxes. Partially offset further by increased fine revenue and reduced cleanup costs from faster intervention."},
  {"id": "28", "pillar": "safe", "section": "Strengthen Public Safety", "tier": "core", "title": "Target chronic disorder drivers with data", "body": "<p><strong>The problem:</strong> A small number of individuals and locations account for a disproportionate share of downtown disorder calls. Coun. Stephen Hammond's 2023 FOI on VicPD call data surfaced that <strong>~24% of all 2022 police calls came from just 19 identified addresses</strong> — encampments and supportive-housing sites. Spreading enforcement evenly across the city misallocates VicPD's already-stretched capacity (50–55 officers short of authorized strength).</p><p><strong>What we will do:</strong></p><ul><li><strong>Focused-deterrence model</strong> on trafficking, weapons, and violent repeat offenders — coordinated with Crown counsel on bail decisions, sentencing requests, and conditions of release</li><li><strong>Data-driven hotspot identification</strong> updated weekly via the DPOT dashboard (Measure 26), with aggregate locations published quarterly (privacy-protected, no individual identification)</li><li><strong>Crown coordination</strong> on prolific offenders — pre-charge consultations, joint case management, consistent applications for conditions that reduce reoffending</li><li><strong>Outreach decoupled from enforcement</strong> for everyone else — vulnerable people in crisis get the wraparound response (Measure 11, Measure 26 outreach component), not the criminal-justice response</li><li><strong>Refusal-rate tracking</strong> (from Measure 35) identifies residents who decline services and may need a different intervention model</li></ul><p>The principle: <strong>relentless with the dangerous, compassionate with the vulnerable.</strong> These are not the same people, and they should not receive the same response.</p>", "budget": "Within existing VicPD operating envelope; no new officer FTEs. Coordination capacity may require 0.5 FTE Crown-liaison position ($100K/year)."},
  {"id": "28b", "pillar": "safe", "section": "Strengthen Public Safety", "tier": "sub", "title": "Business-security cost-spreading pilot — exposure-based, not blanket", "body": "<p>Pandora-corridor businesses and other disorder-exposed properties carry an enforcement burden the rest of the city does not. Insurance claims, broken glass, private security retainers, sharps removal — these are real costs paid by a small number of property owners. On the Hammond July 2023 motion concept (defeated 6-2 at the time, but the underlying problem is unresolved), the City will pilot a narrow, exposure-based cost-spreading instrument:</p><ul><li><strong>Eligibility:</strong> street-front commercial premises within designated high-exposure zones, defined by FOI-validated VicPD call-volume and Bylaw incident data (Hammond's 2023 FOI surfaced that ~24% of all 2022 police calls came from 19 identified addresses)</li><li><strong>Reimbursement:</strong> capped per-premises reimbursement for specific eligible costs (private security hours, glazing repair, sharps-bin servicing) above a deductible</li><li><strong>Sunset:</strong> 24 months, with renewal contingent on measurable downtown disorder reduction (Measure 32)</li><li><strong>Funded from:</strong> managed competition savings (Measure 15), not new tax revenue</li></ul>", "budget": "$500–800K/year for 24 months as a pilot, funded by reallocation. Sunset clause ensures the program does not become permanent if Phase A/B/C measures succeed."},
  {"id": "28c", "pillar": "safe", "section": "Strengthen Public Safety", "tier": "sub", "title": "Business camera registry — VicPD-led, voluntary, and no City cameras", "body": "<p><strong>Currently:</strong> When a downtown assault, break-in, or act of vandalism occurs, VicPD investigators spend the following day walking the block asking business owners whether they have footage. Some do. Much of the useful recording is overwritten before anyone asks. The delay is the loss. <strong>ACTW:</strong> A voluntary registry of <strong>camera locations only</strong>, operated by VicPD with City partnership, on the Kelowna model launched April 14, 2026. Businesses register where their cameras point. When an incident occurs nearby, investigators know within minutes which premises to approach.</p><ul><li><strong>Voluntary in both directions.</strong> Registration is optional. So is providing footage when asked. A registered business may decline any specific request and may withdraw from the registry at any time</li><li><strong>No live access.</strong> The registry records locations, not feeds. There is no monitoring station, no automatic upload, and no City or police access to any camera</li><li><strong>The City does not collect the video.</strong> Businesses retain custody and control of their own recordings under the private-sector <em>Personal Information Protection Act</em>. VicPD requests footage under its own <em>Police Act</em> mandate, in the course of an active investigation</li><li><strong>Published safeguards:</strong> the registry's privacy impact assessment is published in full before launch, sent to the OIPC for review and comment (there is no fee for an OIPC review), and reviewed annually</li><li><strong>Published performance:</strong> registered premises, footage requests made, and median request-to-receipt time, reported on the quarterly dashboard (Measure 67)</li></ul><p><strong>Why the City itself will not run cameras.</strong> In <em>Investigation Report 26-01</em> (January 2026), the OIPC found that the City of Richmond was <strong>not authorized</strong> under FIPPA to collect personal information through its public-safety camera field test, because a municipality does not have a mandate to police individuals. Victoria's policing mandate belongs to VicPD under the <em>Police Act</em>, not to the City. That distinction is the whole legal difference between this measure and Richmond's: <strong>the party requesting footage has the mandate, and the City's role is facilitation.</strong> Measure 30's commitments stand unchanged — no audio surveillance, no facial recognition, no behavioural AI, and no City cameras. We got the investigative benefit without putting a single City camera on the street, and we did it inside the law the OIPC has just written.</p>", "budget": "$40–70K one-time for the registry platform and business onboarding, then $15–25K/year for administration and the annual PIA review. Basis: a form, a map layer, and a contact list built on existing City web infrastructure — no hardware, no monitoring capability. Absorbed within the Measure 26 DPOT envelope. <strong>KPI:</strong> 250 registered premises within 12 months; median footage request-to-receipt under 48 hours."},
  {"id": "28d", "pillar": "safe", "section": "Strengthen Public Safety", "tier": "sub", "title": "Community paramedicine — reduce the calls, not just the response time", "body": "<p><strong>Currently:</strong> Measure 28 establishes that a small number of addresses generate a disproportionate share of calls. Coun. Hammond's FOI surfaced that roughly <strong>24% of all 2022 police calls came from 19 identified addresses.</strong> Council's <strong>January 5, 2026</strong> decision restricting Victoria Fire Department response to serious medical calls cut projected annual call volume from roughly <strong>12,000 to between 6,000 and 6,500</strong>. That decision addresses <em>what firefighters respond to</em>. Nothing in this framework, until now, addressed <strong>why so many calls are generated in the first place.</strong> Community paramedicine, which BC Emergency Health Services built primarily for rural and remote communities, places paramedics in a proactive relationship with high-frequency callers before the call happens. Victoria's downtown core, with its concentration of high-utilizing residents in supportive and transitional housing, is the urban environment where that model would be expected to perform best, and it has no equivalent.</p><p><strong>ACTW:</strong></p><ul><li><strong>Fund a City partnership contribution</strong> to an urban community-paramedicine program targeted at the high-frequency-caller geography Measure 28 already identifies, and provide municipal space and co-location at no cost to the program</li><li><strong>Advocate formally to the Province</strong> for a permanent <em>urban</em> community-paramedicine mandate rather than another time-limited pilot, through UBCM and directly to the Ministry of Health (per Measure 70b)</li><li><strong>Measure it against the call volume it exists to reduce:</strong> repeat-caller contacts, emergency-response calls avoided at the identified addresses, and emergency-department transports avoided, published on the Measure 67 dashboard</li><li><strong>Jurisdiction, stated plainly:</strong> community paramedicine in British Columbia is delivered by BC Emergency Health Services, a provincial Crown corporation. Victoria can fund a partnership and advocate. <strong>It cannot operate a paramedic service, and any candidate who says otherwise is promising someone else's job</strong></li><li><strong>Sequenced with Measure 26b and not duplicative of it:</strong> the civilian crisis team answers the call that comes in. Community paramedicine works on the resident who would otherwise place it. <strong>One is response, the other is prevention, and a city that funds only the first will pay for it forever</strong></li></ul>", "budget": "City partnership contribution of <strong>150 to 250K per year, placed in the gated conditional tier and excluded from the Balance Sheet.</strong> It proceeds only with confirmed BCEHS or provincial participation; <strong>absent that, the measure is advocacy at zero cost.</strong> Municipal space is forgone rent inside the Measure 69 envelope. <strong>KPI:</strong> partnership agreement executed or advocacy position published, 1 of 1 years; emergency-response calls avoided at the Measure 28 identified addresses; emergency-department transports avoided."},
  {"id": "29", "pillar": "safe", "section": "Strengthen Public Safety", "tier": "core", "title": "Resolve the VicPD funding dispute with Esquimalt", "body": "<p>Victoria pays <strong>86.33% of the joint VicPD budget</strong>; Esquimalt pays the remainder. Disputes have escalated to provincial appeals. This is dysfunctional governance: it consumes management attention, weakens the Police Board's ability to plan, and undermines public confidence in policing.</p><p><strong>Resolution path:</strong></p><ul><li>A renegotiated funding formula based on transparent service-consumption metrics (calls for service, officer-hours, geography), reviewed every 4 years</li><li>If the parties cannot agree, formal mediation through the BC Police Services Branch with a binding outcome</li><li>Until resolution, publish quarterly the actual service consumption split versus the funding split, so residents in both municipalities can see what they are paying for</li></ul><p>The annual public dispute serves neither Victoria nor Esquimalt residents. A four-year cycle with binding mediation creates predictability for both.</p>", "budget": "$0 to $1.5M/year depending on negotiated outcome. The principle: pay for the service consumed, full transparency on both sides."},
  {"id": "29b", "pillar": "safe", "section": "Strengthen Public Safety", "tier": "sub", "title": "Greater Victoria regional policing services review — binding mediation outcome", "body": "<p>The Capital Region operates <strong>four separate municipal police forces</strong> (VicPD, Saanich, Oak Bay, Central Saanich) plus RCMP detachments — for a region of roughly 400,000 people. Other Canadian metro areas of this scale and smaller operate one integrated service. The cost duplication (four command structures, four IT systems, four procurement streams, four collective agreements) is real and structural. Mayor Alto's May 2026 re-election platform raised regional policing consolidation as a priority; this measure absorbs that plank and gives it a concrete delivery mechanism. A <strong>Greater Victoria Policing Services Review</strong> — co-sponsored by Victoria, Saanich, Esquimalt, Oak Bay, View Royal, and the affected First Nations — will:</p><ul><li>Examine operational consolidation, joint-service expansion, or full amalgamation of municipal policing across the region</li><li>Be <strong>time-boxed to 18 months</strong> with terms of reference signed by all participating councils up front</li><li>Produce a costed recommendation with a published deliberative trail (modelled on the BC Police Act framework)</li><li>Trigger <strong>binding mediation through the BC Police Services Branch</strong> if participating jurisdictions cannot agree on a path forward within 6 months of the report</li><li>Preserve municipal accountability through a regional governance structure — not a provincial takeover</li></ul><p>This is a co-sponsorship plank, not a unilateral one. Victoria cannot impose this; Victoria can convene it.</p>", "budget": "$300–500K Victoria share of an 18-month independent review, partially recoverable from participating municipalities. Long-run savings from consolidation, where feasible, are in the millions per year — but the up-front commitment is to the <em>process</em>, not a predetermined outcome."},
  {"id": "30", "pillar": "safe", "section": "Strengthen Public Safety", "tier": "core", "title": "Modern smart streetlighting — Kelowna/Halifax model", "body": "<p>Victoria's LED streetlight conversion, budgeted at just $150,000, has been delayed by supplier issues. By contrast, <strong>Kelowna</strong> converted 17,000+ lights for $4.9M, achieving <strong>$1M/year in electricity savings alone</strong> and a <strong>400% ROI over 15 years</strong> (<em>Kelowna Now</em>). <strong>Halifax</strong> deployed 44,000 smart LED fixtures with an IoT platform, saving <strong>$5M/year</strong> and creating infrastructure for smart parking, traffic counters, and environmental sensors (<em>Lighting Design &amp; Specification</em>). Victoria has zero smart/connected streetlight capability.</p><p><strong>What we will deploy (and what we will not):</strong></p><p><strong>Yes:</strong></p><ul><li>Full LED conversion of Victoria's ~7,000–10,000 streetlights</li><li>IoT-connected platform for outage detection, brightness modulation, and energy management</li><li>Adaptive dimming (lower intensity during low-use hours, restore quickly on demand)</li><li>Optional add-on environmental sensors (air quality, noise levels) at selected locations</li><li>Better lighting design (warm tones, heritage-compatible fixtures, gap-filling on dark stretches)</li></ul><p><strong>No:</strong></p><ul><li>No audio surveillance (gunshot detection, scream detection, behaviour detection). The available evidence on these systems is mixed at best (the MacArthur Justice Center's analysis of ShotSpotter found weak crime-reduction impact; Chicago dropped the system in 2024). The privacy and Charter implications are serious. The OIPC of BC has cautioned strongly against municipal audio surveillance</li><li>No facial recognition, license-plate reading, or behavioural-pattern AI on streetlights</li><li>No \"directed brightness at suspect\" functionality — lights will brighten on schedule and on need, not in response to AI threat assessment</li><li><strong>No City-operated cameras of any kind.</strong> Where investigators need footage, the route is the voluntary business registry in Measure 28c, under which the City owns no cameras and holds no recordings</li></ul><p>The <strong>published evidence base</strong> for street-lighting and crime is real, and we cite it at its current, revised value: the updated 21-study meta-analysis (Welsh, Farrington &amp; Douglas, Brå / <em>Criminology &amp; Public Policy</em>, 2022, to Campbell Collaboration guidelines) finds a significant <strong>14% reduction in total crime</strong> in treated areas — down from the 21% reported in the earlier 13-study review, with effects at least as strong by day as by night, indicating the mechanism is community investment and guardianship rather than visibility alone. A benefit that does not depend on watching anyone needs no surveillance to capture. Victoria can take it — plus the operational savings of Kelowna and Halifax — without crossing that line.</p>", "budget": "$3–5M over 3 years for LED conversion + IoT platform at Victoria's scale. <strong>Self-financing within 3–4 years</strong> through electricity savings (~$500K–1M/year at full deployment) plus avoided maintenance costs from outage detection. Environmental sensor adders at $50K–100K each."},
  {"id": "31", "pillar": "safe", "section": "Strengthen Public Safety", "tier": "core", "title": "Weekly public safety dashboard", "body": "<p>Encampments cleared, response times, sidewalk obstructions addressed, public drug use enforcement actions, referrals to shelter/treatment, needles collected. Published weekly. Accountability you can see. No more governing in the dark. If we publish the numbers every week, there is nowhere to hide and no excuse for inaction.</p>", "budget": "$0 net new. The operational data is already captured by Bylaw Services, Parks and VicPD in the course of the work; publishing it weekly is a reporting change absorbed within the Measure 67 dashboard line. A weekly cadence was chosen over monthly deliberately, because street disorder runs on a weekly cycle and a monthly number lets a bad fortnight disappear inside an average."},
  {"id": "31b", "pillar": "safe", "section": "Strengthen Public Safety", "tier": "sub", "title": "Published enforcement record — what we enforced, and what came of it", "body": "<p><strong>Currently:</strong> Victoria publishes no accounting of bylaw enforcement activity. Residents are told enforcement is happening, businesses are told it is not, and there is no published number that settles the argument. Measure 33 commits to consistent enforcement; a commitment without a published count is a slogan. <strong>ACTW:</strong> Publish the enforcement record every quarter, alongside the public-realm KPIs already committed under Measure 67. Where Measure 31 reports <em>operations</em> weekly, this reports <em>enforcement outcomes</em> quarterly — the two are complementary, not duplicative.</p><ul><li><strong>Volume by category:</strong> bylaw notices and municipal tickets issued, by bylaw and by geography, for the contraventions this framework names — sidewalk obstruction, illegal dumping, graffiti, noise, unlicensed vending, daytime sheltering</li><li><strong>Outcome, not just activity:</strong> notices issued, disputed, upheld at adjudication, cancelled, and paid. Enforcement that collapses on review is not enforcement</li><li><strong>Voluntary compliance first:</strong> warnings and voluntary-compliance resolutions reported alongside penalties, so the record shows escalation rather than revenue</li><li><strong>Explicitly not a revenue target.</strong> No officer, team, or department will be given a quota, and the report states total penalty revenue against total enforcement cost each quarter so residents can judge the ratio themselves</li></ul><p>Victoria has two enforcement routes and they behave differently. Bylaw notices under the <em>Local Government Bylaw Notice Enforcement Act</em> run through independent adjudicators who cannot be municipal employees or elected officials, and are capped at $500 per notice. Municipal tickets under Part 8, Division 3 of the <em>Community Charter</em> reach up to $3,000 but proceed through Provincial Court. We will report both, and we will support the UBCM resolution asking the Province to raise the bylaw-notice cap to $1,000 so that the efficient route carries real deterrence.</p>", "budget": "approximately $0. The data already exists in the enforcement case-management system; publishing it is a reporting change absorbed within Measure 67 dashboard operations. <strong>KPI:</strong> enforcement record published within 30 days of each quarter end, 4 of 4 quarters. Adjudication uphold rate published, with no target in year 1 while a baseline is established."},
  {"id": "31c", "pillar": "safe", "section": "Strengthen Public Safety", "tier": "sub", "title": "Turn the community safety plan into a performance contract", "body": "<p><strong>Currently:</strong> Victoria's Community Safety and Well-Being plan was endorsed in <strong>June 2025</strong>, nearly three years into the council term, and its Phase 1 of <strong>10.35 million dollars</strong> was funded by drawing 2.5M from Centennial Square revitalization, 4M from the Financial Stability Reserve, and 1.5M from Royal Athletic Park upgrades (<em>Victoria Buzz</em>). The document reads in soft verbs: convene, support, advocate, explore. Its major commitments do not state which body holds the legal authority to act, who leads, by when, against what measurable target, or at what cost. <strong>More than 10 million dollars has been committed against a narrative</strong>, and reporting is annual and descriptive. <strong>ACTW:</strong> Keep the plan. Retrofit it with the five fields that turn a commitment into a commitment.</p><ul><li><strong>Every major commitment restated with five mandatory fields:</strong> legal authority, responsible lead body, implementation timeline, measurable target, projected cost. <strong>A commitment that cannot populate all five is not a commitment</strong>, and is reported as an aspiration rather than counted as a deliverable</li><li><strong>Where the legal authority turns out to be provincial</strong>, the commitment moves to the Measure 70b downloading ledger instead of being carried as a municipal deliverable. This is the single most useful output of the exercise: an honest split between what the City can actually do and what it has been quietly absorbing</li><li><strong>Quarterly public outcome reporting replaces annual narrative updates</strong>, on the Measure 67 dashboard: crime trend, street-disorder indicators, response times, shelter placements</li><li><strong>A published implementation matrix</strong> showing every commitment, its status, spend to date against budget, and measured result, so residents can track delivery without requesting a report. Hamilton and Toronto both operate public implementation matrices of this kind</li><li><strong>No re-plan.</strong> We are not commissioning a new safety strategy. Victoria has one, it cost real money and real time, and the deficiency is governance rather than content. <strong>Rewriting it would restart the three years this council spent producing it</strong></li></ul><p>The current council published a plan. We will publish whether it worked.</p>", "budget": "approximately zero. The retrofit is a one-time drafting exercise by existing staff, and the quarterly reporting is absorbed within the Measure 67 dashboard envelope alongside Measures 31 and 31b. <strong>What this measure actually costs is the discomfort of publishing a matrix that will show some commitments off track</strong>, which is the same cost every other reporting measure in this framework carries. <strong>KPI:</strong> matrix published within 6 months with all five fields populated for 100% of major commitments; quarterly outcome reporting delivered 4 of 4 quarters; count of commitments transferred to the Measure 70b ledger."},
  {"id": "32", "pillar": "safe", "section": "Strengthen Public Safety", "tier": "core", "title": "15% crime reduction by 2030", "body": "<p><strong>Continuing the momentum.</strong> Victoria's Crime Severity Index dropped 11% in 2024 to 152.65 — its lowest since 2020 — and property crimes fell to 2013 levels. Real progress that should not be undone. The additional 15% reduction by 2030 builds on this trajectory.</p><p><strong>How we get there:</strong></p><ul><li><strong>Hot-spot policing</strong> at data-identified locations (per Measure 28), with sustained presence shifted as patterns shift</li><li><strong>Visible bike and foot patrols</strong> downtown, Inner Harbour, Beacon Hill Park — Measure 36 specifies these geographies</li><li><strong>Better lighting</strong> (Measure 30, Measure 37, Measure 48) — the updated systematic-review evidence shows a ~14% total-crime reduction from improved lighting alone (Welsh, Farrington &amp; Douglas, 2022; 21% in the earlier 13-study review)</li><li><strong>Capacity-first enforcement</strong> (Measure 35) means enforcement is consistent and credible, not erratic</li><li><strong>Quarterly community safety surveys</strong> — not just statistics, but resident perception, tracked block-by-block</li></ul><p>This target is aggressive but achievable — cities that combine unified command, better lighting, and data-driven policing consistently achieve 15–25% reductions in comparable indices.</p>", "budget": "Captured within other measures (M26 DPOT, M27 bylaw hours, M30 smart streetlights, M37 lighting). No new spending in this measure itself."},
  {"id": "33", "pillar": "safe", "section": "Restore Order to Public Spaces", "tier": "core", "title": "Enforce existing bylaws consistently", "body": "<p>Victoria already has rules for overnight sheltering in designated parks (down by 7 AM), sidewalk obstruction, and public space use. The problem is enforcement capacity, not missing rules. We don't need new laws — we need to enforce the ones we have.</p>", "budget": "$0. This measure adds no rules and no staff. The enforcement capacity is the Measure 27 extended-hours line, already costed at $1 to $1.5M per year. This is the commitment to apply it consistently, and Measure 31b publishes whether we did, including the adjudication uphold rate, because enforcement that collapses on review is not enforcement."},
  {"id": "33b", "pillar": "safe", "section": "Restore Order to Public Spaces", "tier": "sub", "title": "Drug-use buffer zones around child-focused spaces", "body": "<p>On the Hammond September 2023 concept (drafted then shelved when the Province pivoted on decriminalization), with the post-May 2024 legal framework now restored: prohibit illicit drug use and possession within 30 metres of expanded \"child-focused spaces\" — defined to include schools, playgrounds, sports fields, tennis courts, picnic tables, bus shelters serving schools, public libraries, and community centres. Enforcement model:</p><ul><li>Verbal direction to move along (first contact)</li><li>Seizure of substances (second contact)</li><li>Referral to outreach and treatment intake, paired with the Phase B capacity work in Measure 35</li><li>Arrest only where required for public safety or persistent non-compliance</li></ul><p>This is not a return to broad criminalization; it is a precisely-scoped buffer rule around the spaces where children gather, consistent with the post-May 7, 2024 BC public-use legal framework.</p>", "budget": "$0 net — enforcement absorbed within DPOT (Measure 26) and extended bylaw hours (Measure 27)."},
  {"id": "34", "pillar": "safe", "section": "Restore Order to Public Spaces", "tier": "core", "title": "Rapid removal protocol for downtown", "body": "<p>Same-day clearing of structures obstructing sidewalks and doorways. Documented process: compliance window (30–60 min) + outreach engagement → if non-compliant, remove, clean, restore. Property stored for retrieval. Humane, consistent, predictable.</p>", "budget": "$0 net new. Delivered by the Measure 26 team inside the Measure 27 hours. Property storage and retrieval is already an obligation under the current bylaw and already a cost; writing the protocol down reduces the legal exposure that attaches to inconsistent practice, which is the more expensive alternative."},
  {"id": "35", "pillar": "safe", "section": "Restore Order to Public Spaces", "tier": "core", "title": "Capacity-first enforcement", "body": "<p>At 5 PM daily, publish available shelter spaces, suitability flags (women-only, couples, pets, mobility), and intake paths on a public dashboard. When capacity exists and transport is offered, enforce consistently. When it doesn't, focus on daytime removal and sidewalk access. <strong>The principle:</strong> increase capacity faster than enforcement ramps up. Don't enforce people into nowhere. Partner with BC Housing and nonprofits for managed alternatives outside the core. Modular supportive housing, shelter expansion, converted buildings.</p>", "budget": "$0 for the 5 PM capacity publication, which is a data feed from BC Housing and shelter operators rendered on the Measure 67 dashboard. <strong>The capacity itself is not the City's to fund.</strong> Shelter and supportive housing are BC Housing's responsibility, which is why Measure 70b exists and why Victoria carrying 89% of the region's shelter beds is a fair-share argument rather than a City budget line. The City's own homelessness response is costed at $2 to $3M per year under Measure 11."},
  {"id": "36", "pillar": "safe", "section": "Restore Order to Public Spaces", "tier": "core", "title": "Reclaim priority public spaces", "body": "<p>Focus areas for permanent visible presence:</p><ul><li><strong>Inner Harbour and waterfront</strong> — Victoria's front door. Patrols on foot and bicycle, permanent and visible, from 7 AM to midnight</li><li><strong>Centennial Square and Pandora corridor</strong> — the areas where disorder concentrates. Dedicated DPOT presence</li><li><strong>Beacon Hill Park</strong> — families, tourists, seniors must feel safe. Regular mounted or bike patrols</li></ul><p>We will systematically apply the same method to each problem area: massive visible presence → interpellation of offenders → referral of vulnerable individuals to services → sustained presence until order is restored → gradual reduction to maintenance level.</p>", "budget": "$0 net new. This measure decides where the Measure 26 team is deployed, not how large it is. Foot, bicycle and mounted patrol geography is a deployment decision inside the Measure 27 hours. Naming the three areas in advance is the accountability: residents can check whether the presence is actually there, and Measure 31 publishes it weekly."},
  {"id": "37", "pillar": "safe", "section": "Better Lighting for Better Safety", "tier": "core", "title": "Light Victoria properly — all night", "body": "<p>Instead of cutting streetlights at midnight, we will progressively dim intensity while maintaining minimum lighting everywhere, all night. LED technology makes this practical: lower energy consumption, longer lifespan, adjustable intensity on demand. We will restore warm, inviting lighting that enhances Victoria's beauty — not cold industrial fixtures but lighting that complements heritage architecture and makes streets feel safe and welcoming after dark. Commercial properties will be encouraged to keep storefront and signage lighting on at night — lit storefronts contribute to street safety and neighbourhood vitality.</p>", "budget": "LED conversion is captured under Measure 30. Incremental cost for extended hours: $150K/year in electricity (mitigated by adaptive dimming). Offset by reduced vandalism, reduced crime, and increased nighttime foot traffic supporting businesses."},
  {"id": "38", "pillar": "safe", "section": "Vision Zero: Trending Toward Zero Traffic Deaths", "tier": "core", "title": "Redesign the most dangerous intersections", "body": "<p>Protected left turns, better crosswalk lighting, traffic calming at Blanshard &amp; Hillside, Douglas Street, and other crash hotspots. Study each intersection using GIS-based traffic analysis (Measure 53) and AI consultation imagery (Measure 53b) for community review, then implement the best solution.</p>", "budget": "Delivered from existing capital lines, which the adopted 2026 plan carries at $836K for crosswalk installations and upgrades, $1.576M for traffic signal modernization, and $450K for traffic calming. This measure sets the prioritization rule, which is collision evidence first, inside that envelope. The analysis inputs are already costed under Measure 53 and Measure 53b."},
  {"id": "39", "pillar": "safe", "section": "Vision Zero: Trending Toward Zero Traffic Deaths", "tier": "core", "title": "30 km/h speed limits on residential and downtown streets", "body": "<p>With speed humps, curb bulges, and physical design that makes speeding impractical. Not just signs — physical infrastructure that forces slower driving.</p>", "budget": "Signage and the bylaw amendment are absorbed within existing transportation operations. The physical calming, which is the part that actually changes driver behaviour, comes from the existing $450K annual traffic-calming capital line and is prioritized by collision evidence. <strong>A speed limit without physical design is a sign, and signs do not slow anyone down.</strong> That is why this measure is written as infrastructure rather than as a number on a post."},
  {"id": "40", "pillar": "safe", "section": "Vision Zero: Trending Toward Zero Traffic Deaths", "tier": "core", "title": "Automated speed enforcement at every school and playground zone: nominate the sites, prepare the sites, and press for the authority", "body": "<p><strong>Currently:</strong> British Columbia's Intersection Safety Camera program has run since 1999 as a partnership between the Province, ICBC and the RCMP. It operates 140 red-light cameras province-wide, 35 of which also enforce speed. Per UBCM, the program <strong>is not operated by or delegated to municipalities</strong>, and the officers who issue the tickets are appointed as Special Provincial Constables under section 9 of the <em>Police Act</em>. <strong>A BC municipality cannot install a speed camera, cannot issue the ticket, and cannot keep the fine.</strong></p><p>Victoria council already established this. In 2023 Coun. Dave Thompson moved, seconded by Coun. Matt Dell and carried unanimously at Committee and Council, that the Province either install speed and red-light cameras at every Victoria location with more than 20 casualty crashes between 2018 and 2022, <strong>or allow BC municipalities to install them at their own cost and collect the fines.</strong> The second limb of that motion is the proof that the authority does not presently exist.</p><p><strong>ACTW:</strong> We will not promise a camera we cannot lawfully install. We will do the three things a municipality can actually do, and publish whether they worked.</p><ul><li><strong>Nominate the sites, with evidence.</strong> Submit a ranked site list to RoadSafetyBC and ICBC covering every active school zone, every active playground zone, and every controlled intersection with a documented multi-year collision history involving pedestrians or cyclists, drawn from the Measure 38 collision evidence and the Measure 20b published pedestrian collision figures. The Province selects sites from crash data. We will make Victoria the easiest municipality in BC to select</li><li><strong>Prepare the sites at City cost.</strong> Signal head placement, detection, sightlines, signage and the civil works a camera site requires are municipal right-of-way work. Where a site is nominated, the City completes the enabling work in advance so that provincial installation is never delayed by municipal readiness</li><li><strong>Advocate for the enabling authority</strong>, carrying Victoria's own unanimous 2023 resolution forward through UBCM and directly to the Ministry of Public Safety and Solicitor General, with a common regional position coordinated through the CRD (per Measure 70b)</li><li><strong>Use what we do control in the meantime</strong>: the Measure 39 physical calming, the Measure 38 intersection redesign, the Measure 20b crossing standard, and targeted VicPD school-zone enforcement at the hours that matter</li><li><strong>Published annually:</strong> sites nominated, sites accepted by the Province, enabling work completed, 85th-percentile speeds in school and playground zones before and after, and the status of the enabling-authority ask</li></ul><p><strong>On revenue, stated plainly.</strong> Automated enforcement revenue in British Columbia is provincial. The Province transfers net traffic-fine revenue to municipalities that pay for policing through a separate program, not camera by camera and not tied to the street the ticket was issued on. <strong>This framework books no revenue from this measure, because there is none for a municipality to book.</strong></p><p><strong>And on cameras, stated plainly.</strong> Measure 30 commits the City to operating no cameras of any kind. That commitment is unqualified and this measure does not carve an exception into it: an intersection safety camera is provincial equipment, operated by provincial constables, on a provincial program. Victoria nominates and prepares. Victoria does not own, operate, or view.</p><p>Zero tolerance for speeding where children are present. That is a commitment about what we build and what we press for, not a claim to a power the City does not hold.</p>", "budget": "<strong>$0 net new.</strong> Site nomination and advocacy are performed by existing transportation and legislative staff. Enabling civil works at nominated sites are delivered inside the existing Measure 38 capital lines, which the adopted 2026 plan carries at $836K for crosswalk installations, $1.576M for traffic signal modernization, and $450K for traffic calming, prioritized by collision evidence. <strong>The $400K of equipment capital and the $300–600K of annual net revenue carried in earlier versions of this measure are struck</strong>, because Victoria can neither buy the equipment nor collect the fine, and a framework that books revenue from a power it does not hold has no standing to audit anyone else's numbers. <strong>KPI:</strong> ranked site list submitted within 12 months; sites accepted by the Province; 85th-percentile speed in school and playground zones, published annually."},
  {"id": "41", "pillar": "safe", "section": "Vision Zero: Trending Toward Zero Traffic Deaths", "tier": "core", "title": "Protected bike lanes on all major routes", "body": "<p><strong>Continuing Victoria's cycling success story.</strong> The 36 km of AAA (All Ages &amp; Abilities) routes built since 2017, with 95% of residents within 500 metres of a safe route, is the strongest cycling infrastructure record of any Canadian city. We will close the remaining gaps and extend the network into the neighbourhoods that still lack it.</p><p><strong>Specifically:</strong></p><ul><li><strong>Protected (physical separation, not painted lines)</strong> on all major commuter and commercial corridors</li><li><strong>Neighbourhood connectors</strong> to close the gaps between the AAA backbone and residential streets that currently force cyclists into mixed traffic</li><li><strong>Improved bike parking</strong> at major destinations (transit hubs, civic facilities, commercial districts), including covered and secure long-term parking</li><li><strong>End-of-trip facilities</strong> required in new major commercial developments — shower, change room, secure bike storage</li><li><strong>Peer-city benchmarking</strong> as the standard for evaluation (Saanich, Esquimalt, Edmonton, Minneapolis, Chicago, Austin, Boston, Nashville, Ann Arbor) — per Coun. Dave Thompson's ongoing peer-city benchmarking work</li><li><strong>Coordination with Measure 25b accessibility</strong> — bike infrastructure must work for adaptive cycles, hand cycles, and the e-bike fleet that older residents and people with disabilities increasingly rely on</li></ul><p>Victoria has the cycling culture; we will keep the infrastructure ahead of the demand.</p>", "budget": "$4–6M over the term for AAA expansion and protected-lane retrofits. The federal Active Transportation Fund and provincial BC Active Transportation Infrastructure Grants typically cover 50–70% on successful application."},
  {"id": "42", "pillar": "safe", "section": "Vision Zero: Trending Toward Zero Traffic Deaths", "tier": "core", "title": "Safety audit for every new road project", "body": "<p>Vision Zero review built into the approval process. No new infrastructure that creates new danger.</p>", "budget": "$0. A review step inside the existing project approval process, performed by existing transportation staff. Its cost is measured in days of schedule, and it is considerably cheaper than rebuilding an intersection that was designed wrong."},
  {"id": "42b", "pillar": "safe", "section": "Vision Zero: Trending Toward Zero Traffic Deaths", "tier": "sub", "title": "Advocate for federal regulation of vehicle hood height and pedestrian-injury standards", "body": "<p><strong>Extending Coun. Dave Thompson's Vision Zero work</strong> on peer-city benchmarking (Hoboken, Minneapolis, Boston) to the federal regulatory level. Pedestrian fatality rates have risen across North America even as overall vehicle-occupant fatality rates have fallen — a divergence driven substantially by the rising hood height and front-end mass of SUVs and light trucks. This is federal motor vehicle regulatory jurisdiction (Transport Canada, Canada Motor Vehicle Safety Standards). The City does not regulate vehicles, but the City represents the constituency that pays the pedestrian cost. Council will pass a formal advocacy resolution to Transport Canada and the Federation of Canadian Municipalities calling for harmonized pedestrian-injury crash standards on the European model (Euro NCAP pedestrian protection, mandatory automated emergency braking on new light trucks and SUVs).</p>", "budget": "$0 (advocacy only)."},
  {"id": "43", "pillar": "beautiful", "section": "The Politics of Beauty", "tier": "core", "title": "Strict design standards in heritage areas", "body": "<p>Complete the update of the Downtown Core Area Plan and Old Town design guidelines. Height and design controls to protect sightlines and human-scale streetscapes. New architecture must complement, not clash. Like the great cities of Europe, Victoria's beauty comes from coherent design — a \"design code\" that ensures every new building and renovation fits harmoniously with its context. We will establish clear architectural guidelines: materials, proportions, colours, and massing that respect the character of each neighbourhood. Simple, enforceable rules that make beautiful buildings the path of least resistance.</p>", "budget": "$0 net new. Completing the Downtown Core Area Plan and the Old Town design guidelines is existing Planning and Development work already in the department's programme. <strong>Design codes reduce cost downstream:</strong> clear, enforceable rules shorten discretionary review, which is precisely the delay Measure 7 commits to cutting. Negotiating every building case by case is the expensive option, and it is the one Victoria currently uses."},
  {"id": "44", "pillar": "beautiful", "section": "The Politics of Beauty", "tier": "core", "title": "Restore Victoria's distinctive street furniture", "body": "<p>Victoria's identity rests partly on its details — lamp posts, benches, planters, bus shelters. Generic replacements erode character. We will:</p><ul><li>Establish a Victoria Heritage Street Furniture Standard — specifying designs that reflect the city's character for all new installations</li><li>As street furniture is replaced through normal lifecycle, require heritage-consistent designs</li><li>Use public-private advertising partnerships to fund bus shelter and kiosk replacements at low net cost to the City</li></ul>", "budget": "Heritage-standard benches, lamp posts, and planters: $300K/year incremental cost above standard replacements. Bus shelters and kiosks: largely offset by advertising revenue under existing models."},
  {"id": "45", "pillar": "beautiful", "section": "The Politics of Beauty", "tier": "core", "title": "Enhance key public spaces", "body": "<p>Centennial Square, Bastion Square, and the waterfront deserve investment. Better lighting, seating, landscaping, and programming (markets, events, performances). These are Victoria's living rooms — they should feel like it.</p>", "budget": "Programming and activation are costed at $300 to $500K per year under Measure 51. Capital comes from the existing Park Redevelopment ($2.25M) and Park Infrastructure Improvement ($904K) lines in the adopted 2026 plan. <strong>One honest note on sequencing:</strong> the current council pulled $2.5M out of Centennial Square revitalization to fund CSWB Phase 1, so part of this measure is restoring a budget that already existed rather than creating a new one. Any full renewal above $25M is referendum-gated under Measure 74 and becomes a Measure 45c candidate."},
  {"id": "45b", "pillar": "beautiful", "section": "The Politics of Beauty", "tier": "sub", "title": "Pedestrianization pilots — Bastion Square first, Government Street next", "body": "<p>Many of Victoria's most beloved streetscapes were not designed for high-volume car traffic. Successful European and North American cities have moved decisively to give priority to pedestrians and cyclists on signature commercial blocks — typically with measurable lifts in retail sales, foot traffic, and tourism after an initial adjustment period. Victoria has talked about this for years; we will deliver pilots with the rigour and reversibility that makes the experiment honest.</p><ul><li><strong>Bastion Square full pedestrianization</strong> — restore it as the public square it was designed to be, paired with daily programming (markets, performances, public art)</li><li><strong>Government Street (Bastion Square to View Street) seasonal pilot</strong> — weekend pedestrianization from May through September, with controlled vehicle access for deliveries and accessible drop-off. Permanence reconsidered each season based on measured foot-traffic, retail-sales, and resident-feedback data</li><li><strong>Fan Tan Alley pedestrian priority</strong> — preserve the historic character with no vehicle access except emergency</li><li><strong>Digital Twin simulation</strong> — superseded in v1.3 by GIS-based traffic analysis (Measure 53) + AI consultation imagery (Measure 53b) for the visualization step. Model traffic redistribution, delivery flow, accessibility impact, and adjacent-street effects through these tools before any permanent change</li><li><strong>Decision rule:</strong> any pilot that does not meet measurable success criteria at the end of two seasons is reversed; any pilot that meets them is made permanent through normal public process</li></ul><p>Cities consistently report initial business anxiety followed by net retail uplift after 12–24 months. We will pilot honestly — with success criteria published in advance, not after the fact.</p>", "budget": "Pilot operating cost: $200–400K/year (programming, modular bollards, accessibility access, signage). Capital for permanent conversion if confirmed: $1–2M per location. Substantially offset by retail uplift on the pilot blocks (peer cities report 10–20% commercial-activity gains 12–24 months in)."},
  {"id": "45c", "pillar": "beautiful", "section": "The Politics of Beauty", "tier": "sub", "title": "One signature public-space project — chosen by residents, approved by referendum", "body": "<p><strong>Every measure in this framework fixes something. One should also build something residents can walk through.</strong> Peer cities pair operational discipline with a single defining public-space investment: Nice converted a buried riverbed into the 20-hectare Promenade du Paillon (12 hectares opened 2013, extended in 2025); Toronto turned the space under the Gardiner Expressway into The Bentway; New York converted a disused rail line into the High Line. Victoria has the candidate sites — and, uniquely, it already has the democratic machinery (Measures 77–78) to choose one honestly instead of by council fiat.</p><p><strong>What we will do:</strong></p><ul><li><strong>Shortlist three candidate concepts in Year 1</strong>, developed with the host Nations (per Measure 1) and neighbourhood associations (per Measure 80): <strong>(a) a Pandora corridor linear park</strong> — the block-by-block conversion of Victoria's most damaged corridor into its most cared-for one, sequenced strictly after the Measure 26 and Measure 35 safety and capacity work, not instead of it; <strong>(b) a continuous Inner Harbour promenade</strong> — closing the gaps between Songhees Point, the causeway, Fisherman's Wharf, and Dallas Road into one uninterrupted waterfront walk (extends Measure 47); <strong>(c) a Centennial Square full renewal</strong> — completing the revitalization the current council defunded to backfill the CSWB budget</li><li><strong>Visualize before choosing</strong> — AI consultation imagery (Measure 53b) and GIS traffic, utility, and infrastructure analysis (Measure 53) published for all three concepts, per the 5-step process (Measure 78)</li><li><strong>The referendum decides</strong> — as a major new park development, this project falls squarely inside the $25M threshold (Measures 74 and 77). The public vote is not an obstacle to the signature project; it is what makes it legitimate. Crystal Pool proved Victorians will approve capital they can see and price</li><li><strong>Senior-government cost-share secured before the vote</strong> — a minimum one-third provincial/federal funding commitment (per Measure 70) is a precondition for putting the question on the ballot</li></ul><p>A city that only maintains is managing decline. A city that only builds is performing. This framework does both — and lets residents pick the monument.</p>", "budget": "Capital envelope $40–80M depending on concept — referendum-gated, with a ≥1/3 senior-government cost-share precondition. Design, consultation, and visualization: $1.5–2M within the existing capital plan. Operating on completion: $400–600K/year, phased into the parks budget late in the term. No effect on the tax-cap glide path (Measure 66): the capital is voter-approved borrowing on the Crystal Pool model, not operating spend."},
  {"id": "46", "pillar": "beautiful", "section": "The Politics of Beauty", "tier": "core", "title": "Protect and restore heritage buildings", "body": "<p>Incentives for adaptive reuse. Tax breaks or grants for owners who restore heritage facades. Zero tolerance for demolition by neglect in Heritage Conservation Areas. Heritage buildings are not obstacles to growth — they are the reason people want to live and visit here.</p>", "budget": "Heritage restoration incentive fund: $500K/year. Leverages private investment at 5–10x ratio."},
  {"id": "46b", "pillar": "beautiful", "section": "The Politics of Beauty", "tier": "sub", "title": "Cultural-venue preservation — protect the venues that make Victoria, Victoria", "body": "<p>The threat of losing Hermann's Jazz Club (continuously operating since 1981) and the broader pressure on independent live-music venues across the downtown core demonstrated that municipal heritage protection cannot rest on building fabric alone — it must also protect <em>use</em>. We will adopt a cultural-venue preservation tool on the precedent of Vancouver's Cultural Spaces program and Toronto's Cultural Hotspot designation:</p><ul><li><strong>Designate</strong> a limited list of cultural venues of city-wide significance (live-music venues, independent theatres, artist studios, long-standing community-arts spaces)</li><li><strong>Right-of-first-refusal</strong> for the City or a designated cultural-spaces non-profit when a designated venue's lease is terminated or property is sold</li><li><strong>Permissive tax exemption</strong> for designated cultural venues that meet programming and accessibility criteria</li><li><strong>Lease-bridge fund</strong> to help designated venues navigate landlord transitions and short-term rent shocks</li></ul><p>Cultural venues are not interchangeable with retail or office uses. Once they close, they almost never come back.</p>", "budget": "Lease-bridge fund: $300K/year. Foregone tax revenue on designated venues: $100–200K/year. Offset by the economic multiplier of preserved cultural anchors (tourism, surrounding-business foot traffic, downtown vitality)."},
  {"id": "47", "pillar": "beautiful", "section": "The Politics of Beauty", "tier": "core", "title": "Expand waterfront walkways", "body": "<p><strong>Continuing Victoria's signature public-realm asset.</strong> Victoria's waterfront is its greatest single public amenity — the Inner Harbour walkway, the David Foster Way, the Songhees and Vic West shoreline routes, and the Ogden Point breakwater are world-class assets that the City has rightly invested in. We will continue connecting and expanding the network so that residents and visitors can walk the entire coastline.</p><p><strong>What we will do:</strong></p><ul><li><strong>Close the gaps</strong> in the existing walkway network — particularly between Songhees and the Selkirk Trestle, and along the Gorge Waterway</li><li><strong>Maintain to a higher standard</strong> — surface, accessibility, lighting, seating, signage, and tactile wayfinding (per Measure 25b)</li><li><strong>Coordinate with the host Nations</strong> (Songhees and Esquimalt) on shoreline access that affects their territorial waters and reserve geographies (per Measure 1)</li><li><strong>Year-round programming</strong> — interpretive signage, public art installations, exercise stations, seasonal events</li><li><strong>Tourism and commercial integration</strong> — the waterfront is also a corridor of restaurants, hotels, and small businesses; the walkway is their front door</li></ul><p>Every metre of walkway added is an investment in tourism, quality of life, and adjacent property values.</p>", "budget": "$1–2M/year capital for gap closures and upgrades. Largely eligible for federal infrastructure and tourism program co-funding."},
  {"id": "48", "pillar": "beautiful", "section": "The Politics of Beauty", "tier": "core", "title": "Extend heritage and ornamental lighting hours", "body": "<p>Victoria's ornamental lighting on heritage buildings and the harbour should not switch off at 10 PM. Maintain heritage lighting until midnight. A city known for beauty should be beautiful after dark.</p>", "budget": "$75K/year in additional electricity costs. LED conversion minimizes this."},
  {"id": "49", "pillar": "beautiful", "section": "The Politics of Beauty", "tier": "core", "title": "Elevate parks and gardens", "body": "<p><strong>Continuing Victoria's identity as a gardens city.</strong> Victoria's parks are world-famous for a reason: Beacon Hill Park, the Inner Harbour gardens, Ross Bay, and Government House grounds are part of the city's identity and a primary tourism draw. The Parks department's mission must include the meticulous, skilled gardening that makes these spaces extraordinary — not \"naturalization\" by default.</p><p><strong>What we will do:</strong></p><ul><li><strong>Restore the Parks operating budget</strong> for skilled horticulture and grounds maintenance to a level that matches the quality of the assets</li><li><strong>Beacon Hill Park as flagship</strong> — a comprehensive 5-year restoration plan covering pathways, plantings, water features, the Children's Farm, signage, and seating</li><li><strong>Inner Harbour gardens as Victoria's front door</strong> — best-practice horticulture, year-round colour, and night lighting (per Measure 48)</li><li><strong>Neighbourhood parks</strong> — every neighbourhood gets at least one signature horticultural feature, programmed and maintained</li><li><strong>Free seedling program for homeowners</strong> — 75% of Victoria's urban forest is on private land; we partner with residents on canopy growth (per Measure 61)</li><li><strong>Royal Athletic Park and sport-oriented parks</strong> (per Measure 52) are treated as part of the same network, not as a separate category</li></ul><p>Intentional beauty, not afterthought.</p>", "budget": "$400–600K/year operating uplift over current Parks budget. Significant offset through tourism revenue (Victoria's gardens are a top citable tourist draw in Condé Nast surveys)."},
  {"id": "50", "pillar": "beautiful", "section": "Liberate Cultural, Festive, and Sporting Life", "tier": "core", "title": "Extended hours for civic cultural spaces", "body": "<p>The Royal BC Museum is provincial, but Victoria's civic cultural spaces (Crystal Garden, McPherson Theatre programming, public libraries) should offer extended evening and weekend hours. Culture should be accessible to people who work during the day. Two evenings per week open until 9 PM. Sunday hours for libraries.</p>", "budget": "$200K/year for extended staff hours (overtime, no new hires)."},
  {"id": "50b", "pillar": "beautiful", "section": "Liberate Cultural, Festive, and Sporting Life", "tier": "sub", "title": "An arts and culture funding floor", "body": "<p><strong>Currently:</strong> Victoria's cultural sector is one of the city's genuine competitive assets and the first line every fiscal-restraint council reaches for. This framework already contains real cultural commitments — venue preservation (Measure 46b), extended hours for civic cultural spaces (Measure 50), year-round outdoor activation (Measure 51), heritage and ornamental lighting (Measure 48), and a flagship event (Measure 73b). What it does not contain is the one thing arts organizations actually ask for at every forum: an assurance that the funding will not be cut to pay for the tax glide path. <strong>ACTW:</strong> The floor is published, and it is protected by the same rule as every other fiscal commitment in this framework.</p><ul><li><strong>A published arts and culture funding floor</strong>, expressed both as a per-capita figure and as a share of operating expenditure, set at the current level in the first financial plan of the term. It does not go down</li><li><strong>Protected by supermajority</strong> — reducing the floor requires a <strong>supermajority of Council (6 of 9) with a published written rationale</strong>, the same standard as the Measure 66 tax cap, the Measure 66b refund override, the Measure 66c debt rule, and the Measure 66d utility discipline</li><li><strong>Multi-year operating agreements</strong> for anchor organizations, replacing annual grant uncertainty. Three-year terms with published performance expectations, so organizations can plan, hire, and programme</li><li><strong>Space is the real subsidy</strong> — the Measure 69 real-estate inventory will identify City-owned and City-leased space suitable for rehearsal, production, studio, and performance use, offered at below-market rates on multi-year terms with priority to organizations displaced by redevelopment. This is the lowest-cost, highest-value cultural lever a municipality has</li><li><strong>Event permitting is cultural policy</strong> — festival, busking, street performance, and temporary venue permits brought under the Measure 72b simplification charter with published turnaround targets. Cost and delay in permitting is a tax on culture</li><li><strong>The Measure 65 grant review applies to arts organizations on the same three-part test as every other recipient, and on no other test.</strong> Artistic content, programming choices, and public positions are never a funding criterion, per the Charter protection stated in Measure 65</li></ul><p>Fiscal discipline that is paid for by the cultural sector is not discipline. It is a transfer.</p>", "budget": "Nil at the floor, because the floor is set at the current level. The commitment is not to increase spending; it is to remove the sector from the list of balancing items. Multi-year agreements are cost-neutral, a change in term length rather than in amount. Below-market space is forgone rent inside the Measure 69 envelope, and in most cases the space is currently vacant or underused, which is the finding Measure 69 expects. <strong>KPI:</strong> floor published and met 1 of 1 years; number of multi-year agreements in place; square footage of City space under below-market cultural tenure; event-permit turnaround against target."},
  {"id": "51", "pillar": "beautiful", "section": "Liberate Cultural, Festive, and Sporting Life", "tier": "core", "title": "Activate outdoor spaces for year-round use", "body": "<p><strong>Victoria's mild climate is a competitive advantage</strong> that the City under-uses. We will:</p><ul><li><strong>Heated outdoor patios</strong> for restaurants (electric / heat-pump, non-polluting) — streamlined permitting and a published design standard</li><li><strong>Expanded night markets</strong> in public squares — weekly during the summer, monthly during the shoulder seasons, with simplified vendor licensing</li><li><strong>Pop-up events and seasonal programming</strong> in Centennial Square, Bastion Square, the Inner Harbour walkway, and Beacon Hill Park</li><li><strong>Busking and street performance</strong> — designated zones, simple licensing, no harassment of legitimate performers (current City rules are inconsistently applied)</li><li><strong>Active-use design</strong> for new public spaces — benches that work for everyone, lighting that invites evening use, accessible WCs (per Measure 24b), and Wi-Fi (per Measure 56)</li><li><strong>Year-round Christmas / festival market</strong> at the Inner Harbour and Government Street — a permanent fixture that draws tourism and supports adjacent commerce</li></ul><p>The cities that win in the post-pandemic era are the ones that make their public spaces work. Victoria has the bones; we will activate them.</p>", "budget": "$300–500K/year for programming, permitting capacity, and operating costs. Substantially offset by event-related business-tax uplift and tourism revenue."},
  {"id": "52", "pillar": "beautiful", "section": "Liberate Cultural, Festive, and Sporting Life", "tier": "core", "title": "Sport facilities — use them fully, including Royal Athletic Park", "body": "<p>Victoria's recreational facilities are often underused during off-peak hours. We will partner with employers to offer corporate access during these windows, generating revenue and promoting employee health. Facilities should be open from 6 AM to 10 PM, with expanded weekend programming. <strong>Continuing the Royal Athletic Park commitment.</strong> Mayor Alto's 2022 platform included Royal Athletic Park enhancements as a stated priority. The 2025 CSWB Phase 1 funding pulled <strong>$1.5M from Royal Athletic Park upgrades</strong> to fund downtown-safety operations — a tradeoff that should not have been necessary, and one residents did not vote for. We will:</p><ul><li><strong>Restore the Royal Athletic Park enhancement budget</strong> reallocated in 2025, over the next two budget cycles</li><li><strong>Complete the deferred facility upgrades</strong> — seating, surface, lighting, accessibility</li><li><strong>Expand programming</strong> with the Victoria HarbourCats, School District 61 partners, and community sport organizations</li><li><strong>Position Royal Athletic Park</strong> as a regional sport-events draw, not just a local facility — events generate visitor spending that flows directly to surrounding businesses</li></ul>", "budget": "$1.5M restoration over two budget cycles to recover reallocated funds; $300K/year operating uplift for expanded programming. Partially offset by user-fee revenue from corporate, school-district, and event use."},
  {"id": "53", "pillar": "beautiful", "section": "Victoria as a Technology Leader", "tier": "core", "title": "Modernize Victoria's GIS (Geographic Information System) and underground utility data", "body": "<p><strong>Currently:</strong> Victoria's underground utility records — water, stormwater, sanitary sewer, telecom conduit — are partially digitized, inconsistently updated across departments, and not always coordinated with permit-issuing or capital-planning staff. The result: re-trenched streets, surprise utility hits during construction, repeated excavation of the same blocks within years, and significant un-budgeted repair costs. The City does not currently publish utility-coordination performance metrics. <strong>ACTW:</strong> A focused modernization of the City's geospatial data and utility records — the practical, evidence-grounded foundation any later visualization or digital-twin work would require, but a worthwhile investment on its own terms.</p><p><strong>What we will do:</strong></p><ul><li><strong>Comprehensive utility records audit and migration</strong> to a unified GIS platform — water, stormwater, sanitary sewer, telecom conduit</li><li><strong>Inter-departmental coordination protocol</strong> — every capital project, every utility work order, every permit applies against the same map. No more parallel records</li><li><strong>Permit-system integration</strong> so applicants and staff see the full subsurface picture at point of decision</li><li><strong>Construction coordination dashboard</strong> — quarterly publication of all planned excavation work to reduce re-trenching</li><li><strong>Open standards and Canadian data sovereignty</strong> — no vendor lock-in, data stored on Canadian servers, exportable in open formats</li><li><strong>Co-funding pursued</strong> through federal Infrastructure Canada modernization programs and provincial Local Government Modernization Grants</li></ul><p><strong>Why this and not a full Digital Twin (v1.3 honest reframe):</strong></p><p>The Helsinki, Singapore, and Boston digital-twin deployments cited in earlier versions of this framework served cities 7–25× Victoria's population, with project-density and grant-funding profiles Victoria does not share. No Canadian municipality of Victoria's scale (~92K residents) has successfully deployed and sustained a full city-scale digital twin. The honest assessment: the underground-utility-coordination case is real and Victoria-sized; the full-city digital-simulation case is not, at this stage. We modernize the data first. The simulation tools become viable later if and only if the data and the use case justify them — see the future-state note at the end of this section.</p>", "budget": "$400–800K capital one-time, ~$50–80K/year ongoing for data maintenance and platform licensing. Substantial co-funding eligible (50–70% typical for federal/provincial municipal-modernization grants). Direct ROI: reduced re-trenching costs (industry estimates: 15–25% reduction in utility-conflict repair costs); faster permit decisions; fewer construction surprises."},
  {"id": "53b", "pillar": "beautiful", "section": "Victoria as a Technology Leader", "tier": "sub", "title": "AI-generated public consultation imagery", "body": "<p><strong>Continuing Coun. Matt Dell's precedent</strong> from the Beacon Hill All-Weather Field reimagining (<em>CHEK News</em>, 2025). The City uses mature, low-cost AI image-generation tools to produce realistic visualizations of proposed projects for public consultation — at a fraction of the cost of conventional architectural renderings, small enough to deploy on every meaningful public-consultation project.</p><p><strong>Implementation:</strong></p><ul><li>Project teams generate 3–5 visualization options per major project for public comment</li><li>Visualizations clearly labelled as <strong>AI-generated illustrations</strong>, not engineering drawings</li><li>Always accompanied by underlying plans, dimensions, and impact data — illustrations supplement, not replace, the technical record</li><li>Cost is a fraction of conventional architectural renderings (typically $1–3K per visualization vs. $15–40K for full renderings)</li><li>Output published in the public-consultation portal (Measure 79) for every project triggering the 5-step process (Measure 78)</li></ul><p><strong>v1.3 reframe:</strong> This is now a <strong>permanent measure on its own merits</strong>, not a \"bridge\" to a Digital Twin. It captures the bulk of citizen-facing visual-impact value at a small fraction of the cost of a full simulation tool.</p>", "budget": "$30–50K/year operating across all public consultations. Within existing public-consultation budget envelope."},
  {"id": "53c", "pillar": "beautiful", "section": "Victoria as a Technology Leader", "tier": "sub", "title": "One-time LIDAR scan of downtown core", "body": "<p><strong>A one-time aerial and street-level LIDAR survey</strong> of the downtown core (Inner Harbour to Quadra, View to Yates) — approximately 2 km². LIDAR (Light Detection And Ranging) produces a high-resolution 3D point cloud of buildings, streetscapes, vegetation, and infrastructure.</p><p><strong>Why this matters as a standalone investment:</strong></p><ul><li><strong>Heritage protection:</strong> every heritage building digitally archived at high resolution — invaluable for restoration, fire-loss insurance documentation, and conservation planning</li><li><strong>Emergency management:</strong> post-disaster recovery planning has a baseline 3D record of pre-disaster downtown</li><li><strong>Planning and development:</strong> developers, architects, and the City share a single accurate baseline for proposed builds and impact analysis</li><li><strong>Public consultation:</strong> LIDAR-derived 3D models feed directly into M53b AI consultation imagery</li><li><strong>Future-state option:</strong> if a full digital-twin investment ever makes sense, LIDAR is the foundational data layer it would require — but the scan is worth doing on its own merits regardless</li></ul><p><strong>Vendor neutrality:</strong> open data formats (LAS / LAZ), published to the open data portal (Measure 56), available to local technology companies, academic researchers, and the public.</p>", "budget": "$150–250K one-time capital. Co-funding eligible through federal Heritage Canada programs and provincial Disaster Mitigation Funds. No recurring cost (scan refreshed approximately every 10 years)."},
  {"id": "53d", "pillar": "beautiful", "section": "Victoria as a Technology Leader", "tier": "sub", "title": "How the City uses its own AI — a published municipal AI standard", "body": "<p><strong>Currently:</strong> This framework commits the City to AI-assisted permit pre-screening (Measure 7), AI-generated public consultation imagery (Measure 53b), AI-assisted translation (Measure 80b), and sensor-based parking availability (Measure 24). It commits the City <strong>not</strong> to deploy behavioural AI, facial recognition, or audio surveillance on public infrastructure (Measure 30, Measure 28c). What it has not contained until now is a single rule about how the City governs the AI it does use: who may deploy it, what may be automated, what is disclosed, what is retained, and what is subject to freedom-of-information request. Victoria has no published AI policy. Neither does any comparable BC municipality, which makes this available and unclaimed. <strong>ACTW:</strong> If we are going to use these tools, we publish the rules first. This is the natural companion to the no-surveillance commitment, and it costs almost nothing.</p><ul><li><strong>A public AI register</strong> — every AI or automated decision-support system the City uses: purpose, vendor, data inputs, whether it touches personal information, and the responsible department. Published and kept current on the open data portal (Measure 56)</li><li><strong>Human-in-the-loop is mandatory, and automated adverse decisions are prohibited.</strong> No permit, licence, grant, enforcement action, hiring decision, housing allocation, or benefit determination affecting an identified person is finally decided by an automated system. AI may sort, flag, pre-screen, draft, and translate. A named human decides, and is accountable. Measure 7's permit pre-screening and Measure 10's allocation rules operate under this constraint explicitly</li><li><strong>Disclosure by default.</strong> Any public-facing image, text, or translation that is AI-generated is labelled as such. <strong>Measure 53b's consultation imagery is labelled in every instance, on the image itself</strong>, together with a plain statement that it is an illustrative visualization and not an approved design. A visualization presented without that label is a misrepresentation, and this framework will not make one</li><li><strong>Records and access to information.</strong> AI prompts, outputs, and system logs used in any decision are municipal records under the <em>Freedom of Information and Protection of Privacy Act</em>, retained under the City's records schedule, and disclosable on request. No decision-relevant AI use in unretained channels</li><li><strong>Privacy assessment before deployment</strong> — a Privacy Impact Assessment for any system touching personal information, per the BC Office of the Information and Privacy Commissioner's January 2026 <em>Public Sector Surveillance Guidelines</em>, published in summary form</li><li><strong>Accuracy and bias testing before deployment and annually after</strong>, with results published. Where a system's error rate is not measurable, it is not deployed on a decision path</li><li><strong>Data sovereignty and no vendor training</strong> — City data on Canadian servers under Canadian privacy law (per Measure 55), and no contract permits a vendor to train models on Victoria resident data</li><li><strong>Procurement standard</strong> — these conditions are contract terms, not aspirations. A vendor that cannot meet them does not win the work</li></ul><p>The City is going to use these tools either way. The only question is whether residents can see how.</p>", "budget": "<strong>40 to 60K per year</strong> for policy development, register maintenance, annual bias and accuracy testing, and Privacy Impact Assessment capacity, absorbed within the Measure 68 technology and attrition envelope. <strong>This is a cost-avoidance measure:</strong> a single privacy order, access-to-information dispute, or withdrawn automated decision costs a multiple of it. <strong>KPI:</strong> register published and current 4 of 4 quarters; 100% of AI systems on a decision path carrying a published assessment summary and a current accuracy test; zero automated adverse decisions."},
  {"id": "54", "pillar": "beautiful", "section": "Victoria as a Technology Leader", "tier": "core", "title": "Adaptive traffic signal control (Measure 19)", "body": "<p>Covered in detail under Mobility. Adaptive signals and the modernized GIS (Measure 53) are complementary: shared geospatial data supports traffic-pattern analysis, signal-timing decisions, and integrated construction coordination.</p>", "budget": "Cross-reference only, so that nothing is counted twice. Costed under Measure 19 at $6 to $9M capital over the term and $0.3M per year operating."},
  {"id": "55", "pillar": "beautiful", "section": "Victoria as a Technology Leader", "tier": "core", "title": "Favour local technology companies in city procurement", "body": "<p><strong>Victoria has one of the strongest concentrations of technology talent per capita in Canada</strong> — the cluster around the Atrium, Fort Tectoria, Vancouver Island Technology Park, and UVic spin-offs is a real economic asset that the City has not systematically leveraged.</p><p><strong>What we will do:</strong></p><ul><li><strong>Local-preference scoring</strong> in procurement for tools and services available locally — permit systems, traffic management, data platforms, civic-engagement software, accessibility tech</li><li><strong>Plain-language RFP requirements</strong> that do not favour large incumbent vendors over local startups</li><li><strong>Innovation pilot framework</strong> — small contracts ($25K–$100K) for local companies to pilot solutions to specific civic problems, with a clear path to scale-up</li><li><strong>Open data and APIs</strong> (per Measure 56) — Victoria's data should be available to local developers and entrepreneurs to build products</li><li><strong>Data sovereignty</strong> — City data stored on Canadian servers, subject to Canadian privacy law (BC FOIPPA and federal PIPEDA). No US-cloud lock-in for sensitive municipal data</li></ul><p>The best way to support a local industry is not subsidies — it is contracts. Real work, real revenue, real accountability.</p>", "budget": "Revenue-neutral. The procurement budget already exists; we are changing scoring and accessibility, not adding spending."},
  {"id": "55b", "pillar": "beautiful", "section": "Victoria as a Technology Leader", "tier": "sub", "title": "The ocean economy — Victoria's natural economic vertical", "body": "<p><strong>Every serious mid-size city picks a lane. Victoria's is the ocean, and it is already here</strong> — Ocean Networks Canada at UVic operates world-leading cabled ocean observatories; the Institute of Ocean Sciences in North Saanich is one of Canada's largest marine-science centres; CFB Esquimalt anchors the Pacific fleet and its maintenance economy; and a working harbour still builds and repairs ships minutes from downtown. Halifax showed what a deliberate municipal posture does for this sector: the COVE marine-technology campus (opened 2018 on a former Coast Guard base) turned Dartmouth's waterfront into an ocean-industry cluster. Victoria has more raw assets and no comparable posture.</p><p><strong>What we will do:</strong></p><ul><li><strong>Name it</strong> — adopt the ocean economy as Victoria's declared economic vertical in the City's economic-development materials, delivered through the Team Victoria office (Measure 73b), not a new agency</li><li><strong>Procure into it</strong> — extend Measure 55's local-preference scoring and innovation pilot framework ($25K–$100K contracts) explicitly to marine-technology applications the City itself needs: harbour water-quality sensing (per Measure 56), shoreline monitoring for sea-level adaptation (per Measure 59), and underwater infrastructure inspection</li><li><strong>Convene it</strong> — one annual ocean-economy summit co-hosted with UVic, the Greater Victoria Harbour Authority, and the host Nations (per Measure 1), whose marine economic interests in these waters long predate the city</li><li><strong>Market it once, credibly</strong> — a \"capital of the ocean economy\" claim made with the evidence behind it, not sprayed across six sectors</li></ul><p>The best economic-development strategy is the one your city would pursue even if no one was watching — because the assets are real.</p>", "budget": "$100–150K/year for convening and materials, absorbed within the Team Victoria office budget (Measure 73b). Procurement component revenue-neutral (per Measure 55)."},
  {"id": "56", "pillar": "beautiful", "section": "Victoria as a Technology Leader", "tier": "core", "title": "Open data portal and environmental sensors", "body": "<p>Expand Victoria's open data portal with real-time transit data, traffic counts, air quality readings, and parking availability. Support community-driven solutions — transit apps, bike route planners, air quality alerts — by making city data freely available in machine-readable formats. Deploy air quality sensors in key locations (downtown, near schools, waterfront) to provide real-time readings during wildfire smoke season. This costs very little and provides enormous value to residents making daily health decisions. Free public Wi-Fi in Centennial Square, the Inner Harbour, and all City facilities.</p>", "budget": "Open data portal expansion: $75K one-time. Air quality sensors (10 units): $50K setup, $15K/year maintenance. Public Wi-Fi expansion: $100K setup, $30K/year. Total: $225K setup, $45K/year ongoing."},
  {"id": "57", "pillar": "beautiful", "section": "Victoria as a Technology Leader", "tier": "core", "title": "Support EV charging infrastructure", "body": "<p>Work with BC Hydro and private operators to expand public EV charging across Victoria — at City parkades, community centres, and new developments. Require EV-ready wiring in all new residential and commercial construction (already supported by BC Building Code). This is not ideology — it is infrastructure for the vehicles that are already being sold.</p>", "budget": "$0 direct City cost for private-operator installations. Requirement for new construction: already in provincial code. City parkade charger installations: $200K over the term (recoverable through usage fees)."},
  {"id": "58", "pillar": "beautiful", "section": "Climate Resilience — Practical, Not Ideological", "tier": "core", "title": "Reaffirm and pursue Victoria's climate targets", "body": "<p><strong>Continuing Victoria's Climate Leadership Plan.</strong> The 2019 climate emergency declaration and the subsequent Climate Leadership Plan set the right targets; the gap is delivery and reporting. We will continue the framework and close the delivery gap.</p><ul><li><strong>50% community GHG reduction by 2030</strong> (vs. 2007 levels) — requiring 19 more percentage points from the 31% already achieved</li><li>100% renewable energy by 2050</li><li>Carbon-neutral by mid-century</li></ul><p><strong>Why this is a cost measure, not a values measure.</strong> Every tonne not emitted is matched by infrastructure Victoria does not have to build twice: stormwater sized for storms that arrive anyway, road surfaces that fail early under heat, emergency response mobilized for events that are now annual. The CRD's Regional Water Supply Master Plan alone contemplates $2 billion in capital over 30 years. Adaptation spending avoided is the largest single line in Victoria's long-run capital picture — and it is invisible in any budget that reports only what was spent. The City alone cannot hit these targets — provincial and federal action is essential. But Victoria can move faster than the minimum, and we will track and <strong>publish progress annually</strong>, including actual uptake numbers for the Climate Friendly Homes program, which the current council has <strong>not published</strong>.</p>", "budget": "$0 in this measure. It restates targets Victoria has already adopted. Delivery is costed under Measures 59, 60, 61, 62, 64 and 58b, and annual progress publication is absorbed within Measure 67. <strong>A target with no published progress number is not a commitment, it is a press release</strong>, and closing that gap is the only thing this measure actually adds."},
  {"id": "58b", "pillar": "beautiful", "section": "Climate Resilience — Practical, Not Ideological", "tier": "sub", "title": "District energy — heat as infrastructure, financed as a utility", "body": "<p><strong>Building heat is the named gap in Victoria's climate math.</strong> Natural-gas heating is the largest remaining emissions share (per the section diagnostic above), and no realistic retrofit program (Measure 60) closes it building by building alone. The proven municipal instrument is district energy: shared low-carbon heat delivered as a utility, paid for by the ratepayers who receive it, at rates benchmarked against gas. British Columbia already runs this playbook — Vancouver's Southeast False Creek Neighbourhood Energy Utility recovers heat from sewage; the City of North Vancouver's Lonsdale Energy Corp has operated a municipal district-energy utility since 2004; Richmond's Alexandra District Energy Utility runs on geo-exchange; and Victoria's own Dockside Green has operated a neighbourhood energy system for years. This is not experimental anywhere except at Victoria City Hall.</p><p><strong>What we will do:</strong></p><ul><li><strong>Feasibility first, honestly</strong> — commission a district-energy feasibility study for the downtown core and major redevelopment areas, screening sewer heat recovery, ocean and ground-source exchange, and waste-heat sources; cost-shared through the Federation of Canadian Municipalities' Green Municipal Fund, which exists precisely for studies like this</li><li><strong>Utility model or nothing</strong> — if the business case passes, the system is established as a <strong>ring-fenced, rate-payer-funded municipal utility</strong> (joining the Measure 66b exclusion list), financed on its own revenue, with published rates. If the business case fails, we publish the study and stop — no vanity infrastructure</li><li><strong>Connect through growth</strong> — new major developments in the service area connect at time of construction, as Lonsdale and Southeast False Creek require, so the network grows with the city instead of by retrofit</li><li><strong>Count it</strong> — projected and actual emissions displaced reported annually against the Measure 58 targets on the quarterly dashboard (Measure 67)</li></ul><p>This is the difference between a climate target and a climate instrument.</p>", "budget": "Feasibility study $250–400K one-time, with a target of ≥50% Green Municipal Fund cost-share. Build-out, if approved: utility-financed, ring-fenced per Measure 66b, zero property-tax impact, no effect on the glide path (Measure 66)."},
  {"id": "59", "pillar": "beautiful", "section": "Climate Resilience — Practical, Not Ideological", "tier": "core", "title": "Upgrade aging stormwater infrastructure", "body": "<p>Replace the oldest systems first. Incorporate green infrastructure: permeable surfaces, rain gardens, urban wetlands. Prepare coastal areas for sea-level rise. Victoria's stormwater system includes pipes over 100 years old — these are ticking time bombs during heavy rain events.</p>", "budget": "$5–8M/year in capital spending (partially budgeted). Green infrastructure components reduce long-term maintenance costs. Seek federal/provincial infrastructure grants to offset."},
  {"id": "60", "pillar": "beautiful", "section": "Climate Resilience — Practical, Not Ideological", "tier": "core", "title": "Expand Climate Friendly Homes program", "body": "<p><strong>Continuing and expanding a program that works.</strong> The Climate Friendly Homes retrofit program is one of the current administration's strongest climate plays — the principal weakness is that the City has not published uptake numbers, so neither the program nor its critics can judge how well it is working. We will continue and expand it, with full transparency.</p><ul><li><strong>More rebates</strong> for insulation, heat pumps, and solar panels</li><li><strong>Help homeowners cut emissions and energy bills</strong> simultaneously</li><li><strong>Create green economy jobs</strong> in retrofitting and clean tech</li><li><strong>Publish annual uptake numbers</strong> (homes served, retrofit type, dollars deployed, estimated GHG reduction) on the quarterly performance dashboard (Measure 67)</li></ul><p>A homeowner who cuts $200/month off an energy bill does not need to be persuaded of anything — they need a program that works and an application that takes twenty minutes. The public return is the same either way: lower household operating costs, reduced peak load on infrastructure the City and BC Hydro would otherwise have to expand, and housing stock that survives the next heat event without an emergency response (per Measure 64).</p>", "budget": "$0 net new from the tax levy. Climate Friendly Homes operates inside the City's existing Climate Action budget, which the adopted 2026 plan carries at $2.39M in expenditure against $1.45M in offsetting grant revenue. This measure commits to continuing the programme and publishing uptake, not to enlarging it from property tax. <strong>Any rebate expansion is funded from the Local Government Climate Action Program and Green Municipal Fund revenue that already offsets most of this line, and it is reported against measured uptake before any tax-funded increase is proposed.</strong> <strong>KPI:</strong> homes served, retrofit type, dollars deployed and estimated GHG reduction, published annually."},
  {"id": "61", "pillar": "beautiful", "section": "Climate Resilience — Practical, Not Ideological", "tier": "core", "title": "Plant 5,000 new trees by 2030", "body": "<p><strong>Continuing and expanding Mayor Alto's 2022 parks-acquisition and urban-forest commitments.</strong> Climate-resilient species on streets, in parks, and through community programs. Grow the urban canopy beyond its current level of roughly 30%. <strong>And put a number on it: a published canopy target of 35% by 2035</strong>, measured on a consistent, repeatable methodology and reported annually. Victoria is a Tree City of the World with <strong>no adopted canopy target</strong>, which means the canopy can decline for a decade while the tree-planting count rises. <strong>A planting count measures effort; a canopy percentage measures result.</strong> Where the two diverge, the canopy number governs, and the planting programme is what changes. Shade, carbon sequestration, stormwater management, and beauty — all from one investment. Continue and expand the partnership with community groups and schools for neighbourhood planting events. Offer free seedlings to homeowners — 75% of Victoria's urban forest is on private land, so the canopy goal cannot be met by City-owned streets alone. Coordinate with the Songhees and Esquimalt Nations on tree planting in culturally-significant areas (per Measure 1).</p>", "budget": "$1.25M over the term, roughly $310K per year, shown in the Savings &amp; Revenue Analysis Part D. The existing Urban Forest Improvement capital line ($405K in the adopted 2026 plan) carries the street-tree share. <strong>The free seedling programme is both the cheap half and the decisive half:</strong> 75% of Victoria's canopy sits on private land, so the target cannot be met from City boulevards at any price. <strong>KPI:</strong> trees planted by year and neighbourhood, seedlings distributed, and canopy measured against the roughly 30% baseline."},
  {"id": "62", "pillar": "beautiful", "section": "Climate Resilience — Practical, Not Ideological", "tier": "core", "title": "60% of trips by transit, walking, or cycling by 2030", "body": "<p>Accelerating the Official Community Plan's 2041 target by 11 years. <strong>The fiscal case:</strong> road and parking capacity is the most expensive infrastructure a city builds per person moved — and Victoria has almost no room to widen anything. Every trip shifted to transit, walking, or cycling is capacity the City does not have to fund, build, or maintain. A mode-share target is a capital-avoidance target. Congestion relief, cleaner air, and better public health follow, but the budget reason comes first: this is the cheapest way to move a growing population through a street network that is not getting any larger. See the Mobility measures (M19–M25b) for the delivery mechanisms.</p>", "budget": "$0 in this measure. It is an outcome target, and specifically a capital-avoidance target. Road and parking capacity is the most expensive infrastructure a city builds per person moved, and Victoria has almost no room to widen anything, so every trip shifted to transit, walking or cycling is capacity the City never has to fund, build or maintain. The delivery cost sits in Measures 19 through 25b."},
  {"id": "63", "pillar": "beautiful", "section": "Climate Resilience — Practical, Not Ideological", "tier": "core", "title": "Protect ecosystems and biodiversity", "body": "<p>Maintain 2.7+ hectares of parkland per 1,000 residents as population grows. Protect Garry Oak ecosystems and rare habitats. Restore shoreline habitats. Maintain 36% of parkland in natural state for biodiversity. Green space preservation doubles as climate action.</p>", "budget": "$0 net new. Delivered from the existing Natural Asset Restoration ($138K) and Park Infrastructure Improvement ($904K) capital lines in the adopted 2026 plan. The 2.7 hectares per 1,000 residents standard is a constraint on land-use decisions rather than a spending line: it costs nothing to hold, and it is expensive beyond recovery once broken."},
  {"id": "64", "pillar": "beautiful", "section": "Climate Resilience — Practical, Not Ideological", "tier": "core", "title": "Emergency preparedness for extreme weather — including a maximum-temperature rental bylaw", "body": "<p>Heatwave cooling centres in every neighbourhood, air quality advisory protocols for wildfire smoke, flood response plans for coastal and low-lying areas. Protect vulnerable residents first — seniors, people with respiratory conditions, people without air conditioning. <strong>Maximum-temperature rental bylaw — a mass-casualty prevention measure.</strong> In the 2021 heat dome, <strong>619 British Columbians died of heat</strong>. The BC Coroners Service Death Review Panel report — <em>Extreme Heat and Human Mortality: A Review of Heat-Related Deaths in B.C. in Summer 2021</em> (released June 7, 2022) — found they did not die outdoors: <strong>98% died indoors</strong>, <strong>67% were aged 70 or older</strong>, and <strong>56% lived alone</strong>. Sustained indoor heat above <strong>26°C</strong> is the danger zone the review identified — the threshold the New Westminster bylaw adopts. These people died in their own homes, mostly old, mostly alone. This is not a climate measure. It is the same category of rule as a smoke-detector requirement or a handrail on a stairwell: a minimum habitability standard against a known, documented, repeatable cause of death. Following the New Westminster precedent (adopted April 2026) and the Dell/Caradonna/Thompson motion before Victoria council (May 2026), we will require landlords to maintain at least one room of every rental unit at no more than 26°C during declared heat-warning periods. Implementation:</p><ul><li>Tied to the BC Building Code and the Standards of Maintenance Bylaw, not as a new standalone instrument</li><li>Reasonable transition window (24–36 months) for existing stock</li><li>Compliance via portable cooling, heat pumps, or built-in mechanical cooling — landlord's choice</li><li>Council will also formally advocate to the Province for enabling legislation that overrides strata bylaws that currently prohibit window or portable AC units, where unit-specific health needs require them</li></ul>", "budget": "Emergency preparedness enhancements: $300K/year. Cooling centre operations during heat events: $100K/year. Bylaw enforcement during heat events: $150K/year incremental, mostly through Phase A DPOT mobilization. Small costs that save lives. On current projections the 2021 event was not a hundred-year anomaly; a bylaw that prevents a single death has already outperformed its cost."},
  {"id": "64b", "pillar": "beautiful", "section": "Climate Resilience — Practical, Not Ideological", "tier": "sub", "title": "Seismic and coastal resilience — the hazard Victoria actually faces", "body": "<p><strong>Currently:</strong> Victoria's emergency planning is oriented to weather. Its largest exposure is geophysical. The city sits in the highest seismic-hazard zone in Canada, and the BC Building Code 2024 seismic provisions, in force March 10, 2025, identified the <strong>Capital Regional District explicitly as a high-risk area</strong> requiring stronger design. The Code governs new construction, alterations, and repairs. It imposes <strong>no obligation on any owner to upgrade an existing building</strong>, and Victoria has never published an inventory of its own vulnerable stock. <strong>ACTW:</strong> Treat earthquake and coastal inundation as the resilience file they are, and be honest about which parts the City controls.</p><ul><li><strong>Inventory first.</strong> A published seismic-vulnerability inventory of City-owned buildings, and of pre-1975 unreinforced-masonry and soft-storey private stock in the downtown core, built from the Measure 53c LIDAR baseline and Measure 53 GIS layers rather than a new survey contract</li><li><strong>Fix our own buildings.</strong> A costed, sequenced retrofit program for City-owned facilities, prioritized by occupancy and post-disaster function, reported against schedule on the quarterly dashboard (Measure 67)</li><li><strong>Coastal adaptation delivered through Measure 59, not alongside it.</strong> Measure 59 already commits to preparing coastal areas for sea-level rise; this measure supplies the missing inputs — king-tide and sea-level-rise exposure mapping for low-lying shoreline, and adaptation standards applied when shoreline infrastructure reaches lifecycle replacement. Measure 64's flood <em>response</em> planning is unchanged; this is <em>adaptation</em></li><li><strong>Voluntary on private stock, and we say so.</strong> Owner information, a published retrofit-cost benchmark, and permit-process priority for voluntary seismic upgrades. Where genuine hazard exists, the existing remedial-action authority under section 72 of the <em>Community Charter</em> already applies</li><li><strong>Advocate for the authority we lack.</strong> Under the <em>Building Act</em>, BC municipalities are restricted from setting technical building requirements that diverge from the BC Building Code. Vancouver could mandate unreinforced-masonry retrofits because it has its own building bylaw under the <em>Vancouver Charter</em>. Victoria cannot. We will advocate through UBCM for enabling authority or a provincial retrofit program</li></ul><p><strong>We will not promise a mandatory private retrofit bylaw.</strong> It is outside municipal authority in British Columbia. Any candidate who promises one has not read the <em>Building Act</em>.</p>", "budget": "Inventory and vulnerability mapping $150–250K one-time, substantially reduced if sequenced with the Measure 53c LIDAR scan. Coastal exposure mapping $80–120K one-time. <strong>The City-owned retrofit program is deliberately not costed here.</strong> An indicative order of magnitude is $2–5M of capital over the term, but that figure is a placeholder and is <em>excluded from the Balance Sheet and from the Savings &amp; Revenue Analysis</em> until the inventory produces a real number. Publishing a retrofit range we cannot source would violate this framework's own costing discipline. No private-sector cost, because there is no private mandate. <strong>KPI:</strong> inventory published within 18 months; share of City-owned post-disaster-function buildings assessed, target 100% by end of term."},
  {"id": "65", "pillar": "managed", "section": "Spend Less, Deliver More", "tier": "core", "title": "Zero-based budgeting review of all 200+ city programs", "body": "<p>Every program must justify its existence from scratch. Not \"last year's budget plus 3%\" — every dollar must be re-earned. We will examine every line item the way an entrepreneur examines expenses: Does this program deliver measurable results? What is the cost per beneficiary? Is there a more efficient way to achieve the same outcome? If a program cannot demonstrate its value, it gets cut or restructured.</p><p><strong>Specific targets:</strong></p><ul><li><strong>Line-by-line review of every grant and subsidy over $50,000/year</strong>, against a published three-part test applied identically to every recipient:</li><ul><li><strong>Jurisdiction — is this the City's job?</strong> Does the activity fall within municipal responsibility, or is it a provincial or federal mandate the City has absorbed by default? Where it is the latter, the grant is a candidate for transfer to the responsible government under Measure 70b, not simply for cutting</li><li><strong>Outcomes — is it delivering?</strong> Documented utilization, cost per beneficiary, and measured results against the grant's own stated objectives. Not activity, not attendance, not reports produced</li><li><strong>Duplication — is someone already funding this?</strong> Where a provincially or federally funded program covers the same service for the same population, the municipal grant is redundant and the City's role is referral, not parallel funding</li></ul><li><strong>This is not a viewpoint test, and it will not become one.</strong> No grant will be reduced, denied, or eliminated because of a recipient's advocacy positions, public criticism of the City, litigation against any government, endorsement activity, or political speech — all protected under section 2 of the Canadian Charter of Rights and Freedoms and outside the scope of this review. Any recipient may test a decision against the published criteria through a documented appeal</li><li><strong>Published:</strong> every reviewed grant, its assessment against each of the three tests, the decision, and the reasons — recipients see the standard in advance and see how they were assessed</li><li>Identify and restructure symbolic programs that produce reports, strategies, and consultations but no measurable change in residents' lives</li></ul><p><strong>Peer city precedent:</strong> Calgary's <strong>SAVE program</strong> (rotating Zero-Based Reviews, 2012–2019) <strong>targeted $74 million in operational savings by 2022</strong> (<em>City of Calgary newsroom, February 2020</em>). At Calgary Council on March 31, 2026, KPMG's Chris Sainsbury reported that SAVE <strong>had found $60 million in operational cash to that date</strong> (<em>LiveWire Calgary, March 31, 2026</em>). Greater Sudbury's Auditor General recommended incorporating ZBB techniques into value-for-money audits as a pragmatic compromise (<em>Greater Sudbury AG Report, 2023</em>). No comparable Canadian city uses formal ZBB at this scale — Victoria would be a pioneer in BC. Applied to Victoria's $384M operating budget, even modest 2–3% savings per reviewed area could yield $2–3M annually. We will review 3–4 service areas per budget cycle on a rotating basis.</p>", "budget": "Target: $3–6M/year in savings from eliminated or restructured programs by end of term (a conservative fraction of Calgary's documented operational cash recovery)."},
  {"id": "66", "pillar": "managed", "section": "Spend Less, Deliver More", "tier": "core", "title": "Moderate and predictable tax increases — a glide path", "body": "<p>Tie property tax increases to a published formula: <strong>CPI + population growth + a documented efficiency-gain adjustment, with a target of inflation + growth (≈3.5%) once the savings measures in this framework are fully realized.</strong></p><p><strong>What the cap applies to, decided and stated.<strong> The cap is on the </strong>residential property tax rate<strong>, not on total tax revenue. Those are different numbers and in 2026 they were far apart. Per the City's own budget page, council raised the revenue it needed from property taxes by </strong>7.28%<strong> overall, then </strong>distributed that increase at 9.34% to residential properties and 4.78% to business properties<strong>. A cap written on the total would have let a council deliver a 9% bill to homeowners and describe it as 6.5%. </strong>We are not going to cap the number residents see and stay silent on the number they pay.</strong></p><p><strong>On the tax-class ratio.</strong> We will not move the business-to-residential ratio in either direction in order to hit a cap. Any change to that ratio is a <strong>separate decision, voted on its own, with a published reason and a stated dollar effect on both a median home and a median business.</strong> Relief for one class has to be paid for with savings, not with a transfer from the other. The current council is moving that ratio from 3.67:1 toward 3:1 by 2030, which is a real policy choice with real winners and losers; it should be argued on its merits and not delivered as a side effect of a headline number. <strong>On assessments, plainly.</strong> The cap governs the rate the City sets. An individual bill also moves with BC Assessment's valuation of that specific property, which the City does not control. <strong>A homeowner whose assessment rises faster than the city average will pay more than the cap; one whose assessment rises slower will pay less.</strong> We state this at the outset rather than being accused of it in year one. <strong>What gets published, every year.</strong> Both numbers side by side: the total levy increase and the residential rate increase, with the dollar change on a median assessed home. Measure 66d then adds water, sewer, solid waste, and stormwater on top, so the full picture sits in one place instead of three.</p><p><strong>Honest staging:</strong></p><ul><li><strong>Year 1:</strong> Residential rate increase capped at 6.5%. <strong>Measured against the 9.34% residential increase council actually levied in 2026, not against the 7.28% aggregate and not against the 13.3% opening draft.</strong> This is the comparison that matters, and it is the harder one to hit: the aggregate benchmark would have made 6.5% a reduction of three quarters of a point, while the residential benchmark makes it a reduction of nearly three points. It is also a lower number delivered <strong>without</strong> the cut $2M debt-reduction payment, the $2.8M parking-reserve deferral, or the capital slippage the council used to reach 7.28%</li><li><strong>Year 2:</strong> Residential rate increase capped at 5%</li><li><strong>Year 3+:</strong> Residential rate increase capped at CPI + population growth (≈3.5%) once managed competition, ZBB, and administrative attrition savings are realized</li><li>Any increase above the published cap requires a supermajority of Council, meaning <strong>6 of the 9 members</strong> (the mayor plus 8 councillors), together with a public explanation on the record. The same 6-of-9 standard governs the Measure 66b refund override, the Measure 66c debt rule, the Measure 66d utility discipline, and the Measure 50b arts funding floor, so that every fiscal rule in this framework is unlocked the same way and none of them can be moved quietly</li></ul><p><strong>The starting point, read from the plan itself rather than from the argument about it.</strong> At the May 7, 2026 final budget vote Coun. Marg Gardiner stated that the adopted five-year plan's <strong>2027 estimate is roughly double the 2026 increase</strong> and called deferring expenditures and debt payments into future years an election ploy. Coun. Matt Dell disputed that it will land there: <em>\"to suggest it's going to be 14 per cent next year, we all know better than that,\"</em> arguing the next council will do the same trimming work from the same \"cost of everything\" starting point (<em>CHEK News, March 2026</em>). So we read the adopted 2026–2030 Financial Plan instead of repeating either characterization. <strong>It contains no 2027 tax-increase percentage.</strong> The plan publishes five-year departmental forecasts, not an out-year tax rate, which means neither the \"roughly double\" nor the \"we all know better than that\" was quoting a published figure. Here is what the plan does show for 2027:</p><ul><li>The <strong>$2M annual debt-reduction contribution, cut to zero in 2026, resumes in 2027</strong> and in every year through 2030</li><li><strong>Debt servicing rises from $9.9M to $13.0M, up 32% in a single year</strong> (repayments $5.26M to $6.96M, interest $4.60M to $6.06M), and continues to roughly $28.2M by 2030 as the Crystal Pool borrowing draws down</li><li>The <strong>transfer to capital rises $5.0M</strong>, from $20.8M to $25.8M, and by a further $5M in each year after that</li><li><strong>Parking Services expenditure jumps 33%</strong>, from $9.3M to $12.3M, cutting the net parking contribution to the budget by about $3.7M. The 2026 figure was held down; 2027 is where it comes back</li><li>The <strong>Corporate envelope grows 22.8%</strong> overall, from $57.5M to $70.6M, almost entirely on those items</li></ul><p>Those four lines alone represent roughly <strong>$13.8M of new pressure against a 2026 property tax base of $209.1M, which is about 6.5 percentage points before a single wage settlement, contract escalation, or police requisition increase is counted.</strong> We are not going to present that as a forecast, because it is not one, and the Housing Accelerator line that also rises in 2027 is grant-funded and offset, so we have excluded it. We state the arithmetic because it is the real starting condition for Year 1 of the next council, and because it shows what the 7.28% of 2026 was purchased with. <strong>Year 1 is not a small ask, and we would rather publish the arithmetic than borrow a number from either side of a council argument.</strong></p><p><strong>One conditional tightening.<strong> Of Victoria's 7.28 points of 2026 aggregate increase, </strong>5.06 points were policing<strong> — a cost governed by the Victoria and Esquimalt Police Board under the <em>Police Act</em>, which the mayor chairs but does not command. Where that cost line can be regionalized or provincially cost-shared (Measure 29b), the Year 1 cap tightens from 6.5% to inflation plus growth. We state it as a condition rather than a promise, because a Year 1 freeze would require a policing decision that is not council's to make. </strong>We will not promise a freeze we cannot deliver.</strong></p><p>This is the honest answer. We do not promise day-one delivery of full savings; we promise a credible glide path, measured in the unit residents are actually billed in, with quarterly reporting on whether the savings are tracking.</p>", "budget": "$0 to administer. The cap is a rule, not a programme, and publishing both the aggregate and residential figures with the dollar change on a median home is absorbed within Measure 67. <strong>What this measure costs is the discipline of actually delivering the rest of the framework.</strong> The arithmetic is set out in full in the Savings &amp; Revenue Analysis: $8.2 to $14M per year in operating savings and $9.5 to $18M in new revenue and avoided costs, against $12.4 to $16.6M in new recurring cost and $0.94 to $1.44M in capital debt service. Net headroom is <strong>$4.3 to $14.0M per year on central assumptions and about −$0.3M on pessimistic ones.</strong> <strong>On the pessimistic case this cap is the first thing that breaks, and Measure 67 will show it breaking in the quarter it happens rather than in a post-mortem four years later.</strong>"},
  {"id": "66b", "pillar": "managed", "section": "Spend Less, Deliver More", "tier": "sub", "title": "Return over-collection to taxpayers — don't sweep it into reserves", "body": "<p><strong>Currently:</strong> When Victoria's actual results come in better than budget, the surplus is absorbed — into reserves, in-year additions, or a quietly reduced borrowing requirement the following year. Residents who were taxed for a service level the City did not need are never told, and never repaid. The reverse operation is well documented: the 2025 CSWB Phase 1 was funded by drawing $2.5M from Centennial Square revitalization, $4M from the Financial Stability Reserve, and $1.5M from Royal Athletic Park upgrades (<em>Victoria Buzz</em>). Reserves are treated as a discretionary pool in both directions, with no rule governing either. <strong>ACTW:</strong> If we collect more than we needed, we give it back.</p><ul><li><strong>The rule:</strong> where audited year-end operating results exceed the approved operating budget by more than <strong>1.5% of operating expenditure</strong>, the excess above that threshold is returned to taxpayers as a <strong>credit line on the following year's property tax notice</strong>, implemented through the annual tax rate bylaw</li><li><strong>The 1.5% band stays with the City</strong> as legitimate forecasting contingency — this is a refund of genuine over-collection, not a prohibition on prudent variance</li><li><strong>Excluded from the calculation:</strong> statutory and restricted reserves; development cost charges and amenity cost charges; water, sewer, stormwater, and — if established under Measure 58b — district-energy utility results (rate-payer funded and ring-fenced); conditional senior-government grants; and one-time real-estate disposition proceeds, which go to debt reduction under Measure 69</li><li><strong>Override:</strong> Council may retain the excess only by <strong>supermajority (6 of 9)</strong> with a published written rationale naming the specific purpose — the same standard as the tax-cap override in Measure 66</li><li><strong>Published:</strong> the over-collection calculation is published in full with the audited financial statements and reported on the quarterly dashboard (Measure 67), whether or not a refund is triggered that year</li></ul><p>This is the mirror image of the tax cap. Measure 66 limits what we can take; Measure 66b returns what we took and did not need. A council that can raid a reserve without a rule can also refund a surplus without a rule — we will do neither by discretion.</p>", "budget": "Neutral to positive for taxpayers, cost-neutral to the City. Administration of the calculation and credit line: under $25K/year, absorbed within existing finance operations. In a year with no qualifying over-collection, the measure costs nothing and the calculation is published anyway. Mechanism to be confirmed with BC municipal counsel against the Community Charter's annual tax rate bylaw and surplus provisions — the rate-offset route is drafted here because it is the clean one; a direct cheque is not."},
  {"id": "66c", "pillar": "managed", "section": "Spend Less, Deliver More", "tier": "sub", "title": "A debt rule — stop borrowing against the next council", "body": "<p><strong>Currently:</strong> Victoria has approved <strong>$168.9M</strong> in Crystal Pool borrowing over a 20-year term, with a staff-recommended <strong>$63M</strong> in further infrastructure borrowing behind it, and debt servicing is already named a main cost driver for 2026. To hold the 2026 increase at 7.28%, council cut a <strong>$2M debt-reduction payment</strong> and a $2.8M parking-reserve contribution. Mayor Alto's own assessment of that approach was that it is not a solution in the long term. The City does not publish total debt outstanding or debt-to-revenue in any accessible format.</p><p><strong>ACTW:<strong> The third fiscal rule, alongside the tax cap and the over-collection refund. Measure 66 limits what we take. Measure 66b returns what we took and did not need. </strong>Measure 66c stops us charging the difference to the next council.</strong></p><ul><li><strong>Publish first.</strong> Total debt outstanding, annual debt service, debt service as a share of operating expenditure, and debt per household — on the quarterly dashboard (Measure 67), from the first quarter of the term</li><li><strong>The rule:</strong> the scheduled debt-reduction contribution in the financial plan is <strong>not available as a balancing item.</strong> Reducing or deferring it requires a supermajority of Council (6 of 9) with a published written rationale — the same standard as the Measure 66 tax cap and the Measure 66b refund override</li><li><strong>A published ceiling:</strong> debt service will not exceed a stated share of operating expenditure without the same supermajority and published rationale. The opening ceiling is set in the first financial plan of the term against the actual figure, because setting it before that figure is published would be guesswork</li><li><strong>Real-estate proceeds, correctly stated.</strong> Section 188(2)(e) of the <em>Community Charter</em> requires proceeds from the sale of land and improvements, other than tax-sale proceeds, to be placed in a reserve fund for paying any debt remaining <strong>in relation to that property</strong> and for acquiring capital assets. Measure 69's proceeds therefore retire property-related debt and fund capital; they cannot be swept to general debt reduction, and this framework describes them accurately rather than conveniently</li></ul><p><strong>No new borrowing headroom is created by this measure.</strong> It is a constraint, not a plan. It does not forbid a deferral; it forces the deferral to be voted in public with a reason attached — which is exactly what did not happen in May 2026.</p>", "budget": "$0 direct. Reporting absorbed within Measure 67. The fiscal effect is to protect a payment already in the financial plan from being used as a shock absorber, which is a discipline rather than a cost. <strong>KPI:</strong> debt metrics published 4 of 4 quarters; scheduled debt-reduction contribution delivered in full, or a published supermajority rationale on record."},
  {"id": "66d", "pillar": "managed", "section": "Spend Less, Deliver More", "tier": "sub", "title": "The Household Bill — one number, published every year", "body": "<p><strong>Currently:</strong> Victoria's public conversation about affordability is conducted entirely in property tax percentages. That number is not what a household pays. On top of it sit the water bill, the sewer levy, the solid-waste charge, and a stormwater utility fee of <strong>218.42 dollars per property per year</strong>. The fastest-growing part of that bill is the part nobody campaigns on. The CRD's five-year forecast for regional water rates is <strong>7.6% in 2026, 9.4% in 2027, 10.9% in 2028, 12.3% in 2029, and 12.6% in 2030</strong> (<em>Times Colonist, November 2025</em>), which compounds to roughly <strong>65% over five years</strong>, with more than half of the underlying capital program attributable to the region's first water filtration plant. In February 2026 the CRD board endorsed a water development cost charge covering about <strong>35%</strong> of a nearly <strong>2 billion dollar</strong> thirty-year program, effective April 2027; the remaining <strong>65% comes from user fees and grants</strong> (<em>Times Colonist, February 2026</em>). None of that appears in a property tax percentage. <strong>This framework had a gap of its own, and this measure closes it.</strong> Measure 66b correctly excludes water, sewer, stormwater, and district-energy results from the over-collection refund, because those are ring-fenced rate-payer funds. The consequence was that the three fiscal rules in this framework — the tax cap, the refund, and the debt rule — gave residents no protection at all on the fastest-rising line of their municipal bill. A tax-only glide path is an incomplete promise, and we would rather say so than be told so. <strong>ACTW:</strong> One number, published every year, covering everything the City and the CRD bill a Victoria household.</p><ul><li><strong>The Household Bill</strong> — a single published figure for a median assessed Victoria home: property taxes plus water, sewer, solid waste, and stormwater. Published as a dollar amount, a year-over-year change, and a five-year forward trajectory, alongside the same figures for a median condominium and a median purpose-built rental unit</li><li><strong>Published with the tax cap, not separately</strong> — the Household Bill appears in the annual financial plan and on the quarterly dashboard (Measure 67) beside the Measure 66 glide path, so the visible number and the total number are never reported apart again. <strong>Measure 66 caps the residential rate; this measure reports everything on top of it</strong></li><li><strong>Discipline on the City-controlled portion</strong> — any increase above CPI plus population growth in a utility fee the City sets itself (stormwater, solid waste, and municipal water and sewer distribution) requires a <strong>supermajority of Council (6 of 9) with a published written rationale</strong>, the same standard as the Measure 66 tax cap, the Measure 66b refund override, and the Measure 66c debt rule</li><li><strong>Honesty on the portion we do not control</strong> — CRD wholesale water and regional wastewater costs are set at the regional board, not at Victoria council. <strong>We will not cap what we cannot set.</strong> We will report it, forecast it, and act on it through Measure 70c</li><li><strong>A five-year forward view, updated annually</strong>, so a household can see the trajectory rather than one year at a time</li></ul><p>We are not going to cap the number residents see and stay silent on the number they pay.</p>", "budget": "No net new cost. The calculation is assembled from figures the City and the CRD already produce; publication is absorbed within Measure 67 and the annual financial-plan cycle. Roughly 0.1 FTE of finance staff time, absorbed within the Measure 68 attrition envelope. <strong>KPI:</strong> Household Bill published 1 of 1 years with the five-year forward view; every City-controlled utility increase above CPI plus growth carrying a published supermajority rationale on the record."},
  {"id": "67", "pillar": "managed", "section": "Spend Less, Deliver More", "tier": "core", "title": "Quarterly performance dashboard", "body": "<p><strong>Currently:</strong> Victoria publishes no quarterly KPI dashboard. Salary and benefits as a share of operating budget are not reported in an accessible format. Total municipal debt outstanding and debt-to-revenue ratios are buried in technical financial plans. The result: voters cannot hold elected officials accountable between elections.</p><p><strong>ACTW:<strong> Permit timelines by category, pothole report-to-fix times, 311 response rates, crime statistics, housing approvals, budget variance, salary share of operating budget, Climate Friendly Homes uptake, the over-collection calculation (Measure 66b), </strong>the full debt set required by Measure 66c<strong> (debt outstanding, annual debt service, debt service as a share of operating expenditure, debt per household), </strong>the quarterly enforcement record (Measure 31b)<strong>, </strong>the camera-registry performance set (Measure 28c)<strong>, </strong>the Conference Centre targets and net cost (Measure 73c)<strong>, </strong>City-owned seismic assessment progress (Measure 64b)<strong>, the homelessness dollars-to-outcomes set (Measure 11), </strong>the Household Bill and its five-year forward view (Measure 66d)<strong>, </strong>the CRD decision and voting record for Victoria's regional representatives (Measure 70c)<strong>, </strong>the record of Transit Commission decisions affecting Victoria (Measure 23b)<strong>, </strong>the walking set — sidewalk-gap kilometres closed, crossing-gap list, and obstruction response time (Measure 20b)<strong>, </strong>the cycling set — kilometres delivered and coverage percentage (Measure 20)<strong>, </strong>the public AI register and assessment status (Measure 53d)<strong>, </strong>the arts and culture funding floor against actual (Measure 50b)<strong>, and the 12 commitments scorecard. </strong>Published online every quarter. Explained in plain language. No hiding.</strong></p><p><strong>Public-realm condition, reported every quarter.</strong> The cleanliness measures in this framework commit to standards, and a standard without a published number is a slogan:</p><ul><li><strong>Graffiti:</strong> share removed within 48 hours against the 90% standard (Measure 14), and median report-to-removal time</li><li><strong>Street and sidewalk condition:</strong> sampled cleanliness score by downtown block and neighbourhood commercial corridor, on a published, repeatable scoring method</li><li><strong>Bin overflow:</strong> median report-to-service time on public waste bins (Measure 16 QR reporting)</li><li><strong>Sharps:</strong> needles collected and hotspot map (shared with the weekly DPOT dashboard, Measure 31)</li><li><strong>Washrooms:</strong> share of the public washroom network in service, and mean out-of-service duration (Measure 24b)</li></ul><p>This is the core of democratic accountability. If you can see the numbers every quarter, you can hold elected officials accountable every quarter. Not once every four years at election time, but continuously. Coun. Marg Gardiner's existing monthly fiscal newsletter is the closest current-council precedent — ACTW formalizes the practice as a city-wide service standard.</p>", "budget": "<strong>$120 to $180K per year</strong> for the platform, the data pipelines, and the analyst time to maintain more than twenty published series on a quarterly cadence, absorbed within the Measure 68 technology and attrition envelope. This measure is costed explicitly rather than left implicit, because it is the envelope that absorbs the reporting obligations of Measures 23b, 28c, 31b, 66b, 66c, 66d, 70c, 82, 82b and 53d. The Savings &amp; Revenue Analysis Part C1 shows everything charged to it and what share of the Measure 68 saving that consumes. <strong>The data already exists in City systems. What costs money is publication and maintenance, not collection.</strong> <strong>KPI:</strong> dashboard published within 30 days of each quarter end, 4 of 4 quarters, with every committed series present and none quietly dropped."},
  {"id": "68", "pillar": "managed", "section": "Spend Less, Deliver More", "tier": "core", "title": "Reduce administrative overhead through technology and attrition", "body": "<p>Streamline internal processes before asking taxpayers for more. Every form a resident fills out, every process that requires visiting City Hall in person, every paper-based workflow — digitize it. <strong>Non-replacement of departing administrative staff:</strong> As staff retire, resign, or move on, we will not automatically replace every position. Each vacancy will be assessed: can technology handle this? Can the work be redistributed? Is the position still necessary given digital tools? Target: reduce administrative FTEs by 12–15% over the term through attrition alone, where vacancies allow. <strong>No layoffs.</strong> Natural departures only.</p>", "budget": "12–15% reduction in administrative overhead through attrition: $2.4–4.5M/year by end of term. Technology investments: $500K/year. Net savings: $1.9–4M/year."},
  {"id": "69", "pillar": "managed", "section": "Spend Less, Deliver More", "tier": "core", "title": "Rationalize the City's real estate holdings", "body": "<p>Conduct a full inventory and utilization audit of all city-owned properties. Sell or lease properties that do not serve essential public functions. When selling, require buyers to meet community benefit criteria (housing, employment, public access) where appropriate. <strong>Where the proceeds go, stated correctly.</strong> Section 188(2)(e) of the <em>Community Charter</em> requires that proceeds from the sale of land and improvements, other than tax-sale proceeds, be placed in a reserve fund for paying any debt remaining <strong>in relation to that property</strong> and for acquiring land, improvements, and other capital assets. Proceeds therefore retire property-related debt and fund capital — they are not available as general debt reduction or as operating revenue. Earlier versions of this measure described them loosely; Measure 66c governs the distinction.</p>", "budget": "Depends on findings of the audit. Conservative estimate: $5–10M in one-time proceeds from sales over the term."},
  {"id": "70", "pillar": "managed", "section": "Spend Less, Deliver More", "tier": "core", "title": "Seek provincial and federal partnerships for capital projects", "body": "<p>The City shouldn't build alone what senior governments should co-fund. Active advocacy for infrastructure dollars. Maintain low debt ratios. Every federal or provincial dollar attracted is a dollar not taken from property taxes.</p>", "budget": "$0. Advocacy and grant-application work is performed by existing staff. <strong>This framework budgets against no grant it has not received</strong>, per Part G of the Savings &amp; Revenue Analysis, which means a successful application improves the picture rather than being required to hold it up. That is the opposite of the current practice of booking optimistic senior-government revenue and then absorbing the shortfall."},
  {"id": "70b", "pillar": "managed", "section": "Spend Less, Deliver More", "tier": "sub", "title": "Confront provincial downloading — public ledger, formal advocacy, and a published refusal threshold", "body": "<p>Successive provincial governments — across parties — have offloaded responsibilities onto municipalities (mental health, addictions, social housing operations, decriminalization compliance, encampment management) without commensurate funding transfer. Council members across the political spectrum have flagged this: Mayor Alto (downloading as a driver of the 2026 tax hike), Coun. Hammond (the structural mismatch between local revenue tools and downloaded mandates), Coun. Kim (the broken municipal taxation framework itself). It is one of the few points of cross-bloc agreement on council. We will operationalize that agreement:</p><ul><li><strong>Quarterly downloading ledger</strong> — a published list of every provincial or federal mandate that the City delivers without dedicated funding, with estimated annual cost per file</li><li><strong>Formal advocacy resolutions</strong> twice per year to UBCM and FCM, calling for either funding transfer or mandate return — file by file, not generic motions</li><li><strong>Published refusal threshold</strong> — services the City will not assume additional responsibility for without dedicated, indexed funding. Examples: net new supportive-housing operations, net new addictions services. The point is not to abandon vulnerable residents — it is to refuse to be the funding pressure-valve for senior-government underinvestment</li><li><strong>Coordinate with Esquimalt, Saanich, Oak Bay</strong> through CRD to present a unified regional position</li></ul>", "budget": "$0 direct cost. Indirect benefit is that every successful funding transfer or mandate return is direct property-tax relief, on the order of hundreds of thousands to millions per file."},
  {"id": "70c", "pillar": "managed", "section": "Spend Less, Deliver More", "tier": "sub", "title": "The regional bill — a published position and a reporting duty for Victoria's CRD representatives", "body": "<p><strong>Currently:</strong> A significant share of what a Victoria household pays for municipal services is decided at a board that Victoria does not control and does not report on. Victoria's ballot includes <strong>three CRD Director positions</strong>, voted on by residents from among council candidates, with the appointments confirmed at the start of the term; the Mayor also sits as a director, and the CRD allocates directors and votes to each local government on a population formula. Those representatives vote at the region on a nearly <strong>2 billion dollar</strong> water capital program and a comparable wastewater program. There is no published mandate, no published voting record, and no reporting duty back to the council and residents they represent. Measure 70b holds senior governments to account for what they download onto Victoria. Nothing in this framework held the region to account for what it bills to Victoria. <strong>The specific file.</strong> The Goldstream Water Filtration Plant is costed at <strong>1.07 billion dollars</strong> for completion in <strong>2037</strong> (<em>CRD Regional Water Supply Master Plan project sheets</em>), and it is the largest single driver of the rate trajectory in Measure 66d. <strong>The case for it is real and on the record:</strong> rising source-water temperature, algal-bloom risk, wildfire exposure, and the eventual integration of the Leech and Goldstream sources, reviewed by Stantec and supported by Island Health (<em>Times Colonist, January 2024</em>). <strong>The case against the current plan is also real and on the record:</strong> the Greater Victoria Water Supply System is <strong>currently exempted from filtration requirements</strong> under BC's <em>Drinking Water Treatment Objectives for Surface Water Supplies</em>, and Island Health's own medical health officer told regional water commissioners in March 2024 that there was <strong>no urgent need for additional filtration capacity at Sooke at that time</strong> (<em>Capital Daily, March 2024</em>). An engineering review commissioned by the Urban Development Institute Capital Region concluded that the master plan <strong>did not demonstrate a compelling scientific rationale</strong> for the plant, that its implementation date was not supported by the data presented, and that the plant would drive roughly <strong>half of a planned 500% increase in costs to water customers</strong> (<em>Times Colonist, January 2024</em>). <strong>ACTW takes no position on whether the plant should be built.</strong> We take a position on the standard of evidence and public reporting required before a billion-dollar regional commitment is locked in, which is precisely the standard Measure 74 and Measure 78 apply to Victoria's own capital. A project that survives that test is stronger for having passed it.</p><ul><li><strong>A published annual City position on regional cost</strong>, adopted by Council in open session before the regional budget cycle, stating Victoria's position on rate trajectory, capital sequencing, and cost allocation (extends Measure 79c)</li><li><strong>A published record of CRD decisions and Victoria representatives' votes</strong> on the quarterly dashboard (Measure 67), so residents can see how the bill they receive was decided. <strong>This is a position and a reporting duty, not a direction to vote</strong> — a director's vote is the director's own, and we will not describe it as more than it is</li><li><strong>The five-step process, applied regionally</strong> — Victoria will advocate at the CRD board for <strong>staged approval</strong> of the filtration plant rather than program-level commitment: a published business case, a published independent alternatives analysis (including watershed fuel management, staged capacity, and deferral triggers tied to measured turbidity), and a rate-impact statement in household dollars, before design procurement proceeds</li><li><strong>A rate-impact statement as a standing requirement</strong> on every regional capital decision above 25 million dollars, expressed in dollars per household per year rather than in percentages — the regional analogue of Measure 74</li><li><strong>Coordinate with Saanich, Oak Bay, and Esquimalt</strong> on a common position on regional cost discipline, parallel to the regional coordination in Measure 70b</li><li><strong>Feed the result into Measure 66d</strong>, so the regional share of the Household Bill is forecast rather than discovered</li></ul><p><strong>Ask the candidates, not just the council.</strong> Three CRD Director positions are on the October 17 ballot and no candidate for them has published a position on the rate trajectory. That is the accountability gap this measure exists to close.</p>", "budget": "No direct cost. The published position is absorbed within Measure 79c; the decision and voting record within Measure 67. The independent alternatives analysis is a CRD cost, cost-shared across the region, and is the kind of expenditure that pays for itself many times over against a 1.07 billion dollar commitment. <strong>KPI:</strong> City position published 1 of 1 years before the regional budget cycle; CRD decision and voting record published 4 of 4 quarters."},
  {"id": "71", "pillar": "managed", "section": "Grow the Tax Base, Don't Just Tax More", "tier": "core", "title": "Cut downtown storefront vacancy from 11% to 5%", "body": "<p>Economic development initiatives, tax incentives for occupying vacant spaces, streamlined tenant improvement permits, animated downtown programming (night markets, pop-ups, public events). <em>This measure addresses commercial storefront vacancy. The related but separate problem of residential short-term rental conversion is handled under Measure 9b.</em> <strong>On vacant-storefront taxation:</strong> Imposing a property tax surcharge on long-vacant commercial properties typically requires <strong>provincial enabling legislation</strong> — Vancouver's Empty Homes Tax sits within a specific provincial framework (Vacancy Tax / Speculation and Vacancy Tax). The City will:</p><ul><li><strong>Advocate to the Province</strong> for enabling legislation that would allow municipalities to surcharge persistent commercial vacancies, on the BC residential model</li><li><strong>Use existing municipal levers immediately:</strong> vacant property licensing requirements, façade-improvement-or-lease conditions on business licence renewals, pop-up tenancy facilitation programs, and targeted business attraction grants for filling priority storefronts</li><li><strong>Publish a quarterly downtown vacancy report</strong> by block and by sector — transparency itself creates pressure on owners to lease at market rates</li></ul><p><strong>Protect the land the economy actually runs on.</strong> Victoria's remaining light-industrial and marine-industrial land in Rock Bay, Vic West, and along the working harbour is finite, unreplaceable, and under continuous pressure for residential conversion. Once it converts it does not come back, and the trades, marine services, ship repair, food production, logistics, and creative-production businesses that use it relocate to the Westshore or leave the region. Those are the jobs that let people live here without a downtown office.</p><ul><li><strong>No net loss of employment-designated land</strong> over the term without a published replacement plan identifying where the capacity goes</li><li><strong>A published employment lands inventory</strong> with capacity, tenure, and utilization, built from the Measure 53 GIS layers</li><li><strong>Marine-industrial land treated as a distinct category</strong> with its own protection, because waterfront industrial capacity cannot be relocated inland at any price (per Measure 55b)</li><li><strong>This is stated as a tension, not hidden.</strong> Measure 6 commits to 12,000 homes and this commits to holding employment land. Both are real, and the resolution is that residential capacity comes from the corridors and the missing middle, not from the last of the industrial land</li></ul>", "budget": "Business attraction and pop-up facilitation: $300K/year. New business tax revenue from occupied spaces: $500K–1M/year. Plus the economic multiplier of dozens of new businesses and hundreds of jobs."},
  {"id": "72", "pillar": "managed", "section": "Grow the Tax Base, Don't Just Tax More", "tier": "core", "title": "Support small business — reduce red tape, treat operators with respect", "body": "<p><strong>The problem:</strong> Small businesses create the majority of Victoria's private-sector jobs, but they are the businesses least able to absorb regulatory friction — permit delays, complex licensing, inconsistent enforcement, and a slow City Hall that does not value their time.</p><p><strong>What we will do:</strong></p><ul><li><strong>Business licence processing: 5 business days, maximum.</strong> Not 5 weeks. Most licences are renewals or low-risk new applications that need a documented turnaround</li><li><strong>Tenant-improvement permits</strong> for commercial fit-outs: published 6-week target (aligned with Measure 7 simple-permit benchmark)</li><li><strong>Designated downtown economic coordinator</strong> — single point of contact for storefront operators, with authority to escalate stalled files</li><li><strong>Proactive recruitment for vacant storefronts</strong> (per Measure 71) — the City should be calling promising retailers and helping them open</li><li><strong>\"Welcome / thank you\" small-business program</strong> — continuing the Alto 2022 plank, never delivered. A brief in-person visit from a Council member or senior staff to new and long-tenured businesses, with a focused conversation about what the City can fix</li><li><strong>Tax relief for community-serving non-profits and small businesses</strong> — continuing the Alto 2022 plank under section 224 of the Community Charter. Published criteria, transparent decisions, no political favouritism</li></ul><p>Treat small business operators the way the City treats its largest taxpayers — as customers, not applicants.</p>", "budget": "$200K/year for the downtown economic coordinator and outreach program. Largely offset by faster licence revenue, new business openings, and reduced storefront vacancy (Measure 71)."},
  {"id": "72b", "pillar": "managed", "section": "Grow the Tax Base, Don't Just Tax More", "tier": "sub", "title": "A simplification charter — every new rule earns its place, every old rule gets reviewed", "body": "<p><strong>Currently:</strong> Victoria's bylaw corpus accumulates. Nothing in the City's process requires anyone to ask whether a rule adopted in 1994 still serves a purpose, what it costs the people who comply with it, or whether a new rule duplicates one already on the books. Measure 72 commits to faster licences and permits. This measure addresses the <em>volume of rules</em> those processes administer. <strong>ACTW:</strong> A council-adopted simplification charter, with four operating rules.</p><ul><li><strong>Sunset by default.</strong> Every new regulatory bylaw carries a review date not more than 5 years out. At the review the bylaw is renewed, amended, or lapses, and the decision is published with the compliance data behind it</li><li><strong>A rolling repeal review.</strong> Two bylaw families per year, reviewed against the same published three-part test the Measure 65 grant review already applies — <strong>jurisdiction</strong> (is this the City's job), <strong>outcomes</strong> (is it delivering), <strong>duplication</strong> (is someone already doing this). Recommendations published in full, including the ones council rejects</li><li><strong>Compliance-cost statement.</strong> Any new regulatory bylaw comes to council with a one-page estimate of what compliance costs the people subject to it: dollars, hours, and forms. Small operators are not a rounding error</li><li><strong>Small-commerce charter.</strong> A published statement of what a Victoria business can expect from the City — a named contact, a published turnaround, one file number, plain-language correspondence, and no requirement to submit the same information twice. This gives the Measure 72 \"welcome / thank you\" commitment a service standard attached to it, rather than replacing it</li></ul><p>Nothing lapses silently. Every review publishes its data and every decision is a recorded council vote, which is more scrutiny than most of these bylaws have had since they passed. This is deliberately unglamorous. Bureaucratic accumulation is a tax paid in time by the people least able to absorb it, and nobody has ever campaigned on repealing a bylaw no one remembers passing.</p>", "budget": "$80–120K/year for the review capacity — roughly 0.75 FTE of policy and legislative-drafting time, <strong>absorbed within the Measure 68 attrition envelope rather than added to it.</strong> Compliance-cost statements are prepared by the sponsoring department at marginal cost. Partially offset by reduced administrative handling on repealed and consolidated bylaws, unquantified. <strong>KPI:</strong> 2 bylaw families reviewed per year; 100% of new regulatory bylaws carrying a review date and a compliance-cost statement."},
  {"id": "73", "pillar": "managed", "section": "Grow the Tax Base, Don't Just Tax More", "tier": "core", "title": "Promote tourism recovery", "body": "<p><strong>Continuing the post-pandemic momentum.</strong> Victoria's tourism numbers are back: ferry traffic up 2%, cruise ships increasing, hotel occupancy near pre-pandemic levels, Condé Nast Traveller \"best small city\" for the third time in 2025. Tourism employs roughly 22,000 people across the Capital Region and underwrites a substantial share of Victoria's small-business ecosystem.</p><p><strong>What we will do:</strong></p><ul><li><strong>Better wayfinding</strong> — Victoria's directional signage is inconsistent and dated; visitors get lost between obvious destinations. A unified wayfinding system tied to the Heritage Street Furniture Standard (Measure 44)</li><li><strong>Extended business hours</strong> in commercial areas — too many Victoria businesses close at 5 or 6 PM in summer, when foot traffic is peaking</li><li><strong>Waterfront activation</strong> (Measure 47) and outdoor programming (Measure 51) as tourism infrastructure</li><li><strong>Cruise-ship coordination</strong> with the Greater Victoria Harbour Authority on visitor flow, with downtown businesses on logistics, and on Pier 21 / James Bay neighbourhood impact</li><li><strong>Marketing partnership</strong> with Destination Greater Victoria — Victoria should be marketed nationally and internationally as Canada's most liveable small city, because it is, or will be</li><li><strong>Indigenous tourism partnership</strong> with the Songhees and Esquimalt Nations (per Measure 1) on shared cultural-tourism products that direct revenue to the Nations</li></ul><p>Tourism is not separate from the rest of the city — a clean, safe, beautiful, well-managed Victoria is the best tourism strategy that exists.</p>", "budget": "$300K/year incremental marketing partnership and wayfinding maintenance. Substantially offset by visitor spending (estimated $1.5B+/year regionally pre-pandemic, recovering)."},
  {"id": "73c", "pillar": "managed", "section": "Grow the Tax Base, Don't Just Tax More", "tier": "sub", "title": "The Conference Centre's own numbers — a published target, a published net cost", "body": "<p><strong>Currently:</strong> The Victoria Conference Centre is <strong>owned and operated by the City</strong> and is the second-largest facility of its kind in British Columbia, with a stated mandate to generate economic benefit for the City. In 2024 it generated <strong>94,200 delegate days</strong> (up 12% over 2023), <strong>25,300 room nights</strong> (up 10%), and <strong>$31.1M in business sales</strong> supporting more than 10,000 jobs (<em>Business Events Victoria / Destination Greater Victoria, January 2025</em>). Sales and marketing is <strong>already contracted</strong> to Business Events Victoria, a division of Destination Greater Victoria. So what is missing is not an operator, and not a promoter. It is the asset's own target and the asset's own bottom line. <strong>ACTW:</strong> Measure 73b makes Team Victoria accountable for downtown vacancy and uses the VCC as its principal off-season instrument. This measure makes the instrument itself accountable.</p><ul><li><strong>A published annual target</strong> for delegate days, room nights, and business sales, set in the financial plan and reported on the quarterly dashboard (Measure 67) against prior year and against target — the VCC's own numbers, distinct from the Team Victoria vacancy mandate they support</li><li><strong>Published net cost to the taxpayer.</strong> What the VCC costs the operating budget, net of revenue, stated plainly each year. An asset carrying a $31.1M economic-impact claim should be able to show its own bottom line, and today it does not</li><li><strong>Governance reviewed, not presumed.</strong> Whether an arms-length operating entity would outperform the current in-house-plus-contract model is a question for evidence, not assertion. A one-time review reports to council in Year 2 with a recommendation either way</li></ul><p><em>Scope boundary: the single events calendar and the flagship-event commitment live in Measure 73b; shoulder-season programming is delivered through Measures 47 and 51. This measure adds no programming — only the target, the net cost, and the governance question.</em> <strong>On the corporation question.</strong> Section 185 of the <em>Community Charter</em> permits a municipality to incorporate a corporation only <strong>with the approval of the Inspector of Municipalities</strong>, and a society is expressly excluded from that requirement — so both a lighter and a heavier vehicle exist. Neither is worth pursuing before the Year-2 review establishes that the current arrangement underperforms. Section 175(2) additionally requires <strong>approval of the electors</strong> for most agreements running beyond 5 years, which is a real constraint on any long-form delegation and a reason not to promise one casually.</p>", "budget": "$30–50K one-time for the Year-2 governance review. Target-setting and reporting are absorbed within existing VCC management and Measure 67 dashboard operations. <strong>No new corporation, no new staff, and no Inspector application in this measure.</strong> Revenue upside is real but not banked here, consistent with this framework's practice of not budgeting against growth it does not control. <strong>KPI:</strong> VCC target published in the financial plan and reported quarterly; net cost to the operating budget published annually."},
  {"id": "73b", "pillar": "managed", "section": "Grow the Tax Base, Don't Just Tax More", "tier": "sub", "title": "Team Victoria — one attractiveness office, one number, one flagship event", "body": "<p><strong>Victoria's economic-development effort is scattered across marketing lines, memberships, and goodwill — and no one owns a number.</strong> Cities that reversed downtown decline consolidated the effort into a single small office with a published quantitative mandate and a mayor personally accountable for it.</p><p><strong>What we will do:</strong></p><ul><li><strong>One office</strong> — a small Team Victoria economic-attractiveness office (2–3 FTE), chaired by the mayor, consolidating the City's existing marketing partnership (Measure 73), storefront recruitment (Measure 71), red-tape work with operators (Measure 72), and the ocean-economy vertical (Measure 55b) into one accountable unit — working alongside Destination Greater Victoria and the Greater Victoria Harbour Authority, not duplicating them</li><li><strong>One number</strong> — the office's published mandate is Measure 71's target: downtown storefront vacancy from 11% to 5%, reported quarterly on the Measure 67 dashboard, with conferences, delegate days, and off-season occupancy as supporting indicators. The city-owned Victoria Conference Centre (94,200 delegate days, 25,300 room nights, and $31.1M in business sales in 2024) is the office's principal off-season instrument, with its own target and net cost published under Measure 73c</li><li><strong>One flagship event</strong> — develop one recurring international event that belongs to Victoria the way the Jazz Festival belongs to Montreal: a Pacific ocean-economy summit (per Measure 55b), a signature maritime festival on the Inner Harbour, or an Indigenous cultural-tourism flagship co-created with the Songhees and Esquimalt Nations (per Measures 1 and 73). One event, chosen for durability — not a calendar of one-offs</li><li><strong>Accountable like every other program</strong> — every dollar and every claimed outcome published; if storefront vacancy is not measurably falling by Year 2, the office is restructured under zero-based budgeting (Measure 65) like anything else</li><li><strong>Anchor institutions as economic infrastructure</strong> — a standing annual table with <strong>UVic, Camosun, and Royal Roads</strong> on student housing in Victoria proper, co-op and graduate employment placement, campus-adjacent transit priority (per Measure 23b), and research commercialization (connecting Measure 13c, Measure 55, and Measure 55b). Post-secondary education is one of Victoria's largest economic sectors and the City has no standing relationship with it</li><li><strong>A published shoulder-season target</strong> — visitor nights and downtown foot traffic for <strong>November through March</strong>, reported annually. Victoria's tourism problem is not volume, it is distribution: the summer is full and the winter is empty, and the winter is when downtown businesses fail. The flagship event above, the Measure 51 year-round outdoor activation, the Measure 50 extended cultural hours, and the Measure 73c Conference Centre targets are all sequenced against the shoulder season rather than the peak</li><li><strong>A published sector view</strong> — the annual attractiveness report covers the ocean economy (per Measure 55b), technology, post-secondary, public sector, marine and trades, and tourism, with employment and business-count figures for each, so that \"economic development\" stops meaning \"downtown retail vacancy\"</li></ul><p>Attractiveness is not a brochure. It is a number, a name, and someone accountable for both.</p>", "budget": "$350–450K/year incremental above the existing Measure 73 marketing line (total office cost ~$650–750K/year), funded from zero-based-budgeting savings (Measure 65) within the existing Savings &amp; Revenue headroom. Flagship-event seed funding: $250K one-time, with published cost-recovery targets from year two."},
  {"id": "73d", "pillar": "managed", "section": "Grow the Tax Base, Don't Just Tax More", "tier": "sub", "title": "A published Strategic Economic Plan", "body": "<p><strong>Currently:<strong> Victoria has economic-development <em>activity</em> and no economic-development <em>plan</em>. Measure 71 sets a storefront-vacancy target, Measures 72 and 72b reduce friction for operators, Measure 73 handles tourism, Measures 55 and 55b handle procurement and the ocean vertical, and Measure 73b consolidates the effort into the Team Victoria office. What no document states is which sectors Victoria is trying to grow, what quality of employment it is trying to attract, and what it will decline. </strong>In the absence of a plan, economic development defaults to whatever arrives.</strong></p><p><strong>ACTW:</strong> One plan, published, with numbers in it.</p><ul><li><strong>A Strategic Economic Plan adopted by Council in the first year of the term</strong>, produced by the Measure 73b Team Victoria office, covering the ocean economy (per Measure 55b), technology, post-secondary, public sector, marine and trades, tourism, and the creative sector</li><li><strong>Employment quality, not just employment count.</strong> The plan reports <strong>median wage and full-time share by sector</strong>, not only business counts, because a city can add jobs and still lose the ability to live in it. This is the number that decides whether Victoria's young adults stay (per Measure 13c)</li><li><strong>Employment land tied to the plan</strong>, not filed beside it: the Measure 71 industrial and marine-industrial inventory is a direct input, so sector ambition and land capacity are decided together rather than in separate rooms</li><li><strong>Anchor institutions inside the plan</strong> through the Measure 73b standing table with UVic, Camosun, and Royal Roads</li><li><strong>A stated declination.</strong> The plan names the sectors Victoria will <strong>not</strong> chase. A document that pursues everything is a list, not a strategy, and the discipline of saying no is the whole value of writing it down</li><li><strong>Reviewed annually against its own indicators</strong> on the Measure 67 dashboard, and rebuilt once per term rather than continuously</li></ul><p>A plan that cannot be measured is a brochure, and Measure 73b already exists to own the number.</p>", "budget": "<strong>nil.</strong> The plan is a deliverable of the Team Victoria office already costed at 350 to 450K per year incremental under Measure 73b, and the sector data is assembled from Statistics Canada, BC Stats, and CRD sources the City already accesses. <strong>This measure adds an output, not an office.</strong> <strong>KPI:</strong> plan adopted within 12 months; annual review published 1 of 1 years; median wage and full-time share reported by sector."},
  {"id": "74", "pillar": "managed", "section": "Grow the Tax Base, Don't Just Tax More", "tier": "core", "title": "Major new capital projects require voter approval", "body": "<p>Following the Crystal Pool referendum model and within the BC Local Government Act / Community Charter framework. <strong>Any new (non-lifecycle) capital project exceeding $25 million</strong> goes to the public via Assent Voting or the Alternative Approval Process, as the statutory framework permits. <strong>The Crystal Pool replacement continues as voted.</strong> In February 2025, 58.7% of Victoria voters approved $168.9M in borrowing for the Crystal Pool replacement under a referendum process. That decision stands. Lifecycle replacement of existing infrastructure proceeds; the Crystal Pool referendum is the exact precedent ACTW Measure 77 and Measure 78 are designed to make standard practice. <strong>What is included in the $25M threshold:</strong> new community centres, new arenas, new pools (the Crystal Pool replacement was already approved through this mechanism), new civic buildings, major new park developments, significant scope-changing renovations. <strong>What is not included:</strong> lifecycle replacement of existing infrastructure (stormwater pipes, road resurfacing, water/sewer renewal, bridge rehabilitation, statutory infrastructure obligations). Lifecycle work is the City's basic statutory and operational duty; subjecting it to referendum would block essential maintenance. When the City spends big on <strong>new</strong> capital, residents decide. Not consultants. Not councillors alone. You.</p>", "budget": "Assent voting costs roughly $150 to $250K per question run on its own, and close to nothing when run alongside a general local election, which is why questions will be timed to general elections wherever the project schedule allows. <strong>This is a real cost and it buys a real mandate.</strong> Against the $25M threshold that triggers it, the vote costs under 1% of the decision it authorizes. The Crystal Pool referendum is the precedent, and it cost less than the first month of interest on the borrowing it approved."},
  {"id": "75", "pillar": "managed", "section": "Lower the Cost of Living — Specific Measures", "tier": "core", "title": "First-hour free parking", "body": "<p>See Measure 24. Direct savings for every resident who drives downtown.</p>", "budget": "Cross-reference only. Costed under Measure 24 at $1.5 to $2.5M per year in forgone meter revenue. That is the single largest discretionary cost in this framework, and it is stated plainly here rather than buried in a mobility subsection."},
  {"id": "76", "pillar": "managed", "section": "Lower the Cost of Living — Specific Measures", "tier": "core", "title": "Reduce permit fees for homeowners doing small renovations", "body": "<p><strong>The problem:</strong> Garden suites, accessibility modifications, energy retrofits, and small additions get caught in the same fee structure as multi-unit developments. The result: homeowners are deterred from doing the work, or do it without a permit — neither of which serves the City.</p><p><strong>What we will do:</strong></p><ul><li><strong>Reduced or waived fees</strong> for projects under $50K that:</li><ul><li>Add housing (secondary suite, garden suite, lock-off unit, in-law suite)</li><li>Improve accessibility (per Measure 25b — ramps, grab bars, accessible bathrooms, widened doors)</li><li>Improve energy efficiency (insulation, heat pumps, solar, electrical upgrades for EV charging)</li><li>Restore heritage features</li></ul><li><strong>Published one-day-turnaround target</strong> for these simple categories (per Measure 7 simple-permit benchmark)</li><li><strong>Pre-approved design library</strong> — common garden-suite, secondary-suite, and accessibility-retrofit designs pre-screened for compliance, available to homeowners free of charge</li><li><strong>Online permit application</strong> for these categories (per Measure 7) — no need to come to City Hall</li></ul><p>Faster, cheaper, easier permits for the projects we actually want more of.</p>", "budget": "$100–150K/year in foregone permit-fee revenue. Substantially offset by faster property-value uplift (and corresponding property-tax base growth) plus reduced under-permitting (which costs more to clean up after)."},
  {"id": "77", "pillar": "democratic", "section": "Direct Democracy and Transparency", "tier": "core", "title": "Referendums for new capital projects over $25 million", "body": "<p>Not just consultations where input gets filed away. <strong>Binding votes</strong>, within the BC Local Government Act and Community Charter framework (Assent Voting or Alternative Approval Process). The Dowler Place controversy proved why this matters. A CHEK News FOI revealed the mayor's confidential draft plan to relocate the Pandora encampment was far broader than publicly disclosed. Mayor Alto admitted council skipped community engagement because \"we knew what the comments would be\" (<em>CHEK News</em>). She later apologized (<em>Capital Daily</em>), but the episode — combined with firefighter Josh Montgomery's one-day suspension for criticizing the plan, which prompted Premier Eby to demand an apology and a <a href=\"http://Change.org\">Change.org</a> petition calling for Alto's resignation — cemented a perception of closed-door governance. This cannot happen again. Referendums for new capital, the 5-step process, and the quarterly dashboards are the antidote.</p>", "budget": "Same basis as Measure 74: roughly $150 to $250K per standalone question, close to nothing alongside a general election. At Victoria's scale two or three projects per term cross the $25M threshold, so this is not a permanent referendum machine. It is two or three votes in four years, on the decisions that will outlast the council making them."},
  {"id": "78", "pillar": "democratic", "section": "Direct Democracy and Transparency", "tier": "core", "title": "The 5-step process for every major public project", "body": "<p><strong>Currently:</strong> The Dowler Place file is the cleanest illustration of what happens without a required process. Mayor Alto's confidential draft motion to relocate the Pandora encampment was disclosed via CHEK News FOI in June 2025; the mayor stated publicly that early consultation was skipped because <em>\"we knew what the comments would be from the public.\"</em> She apologized for a \"rocky\" rollout, but the underlying problem was structural — there was no required process to follow, so the process was skipped.</p><p><strong>ACTW: every major public project goes through five steps, in this order, no exceptions:</strong></p><ol><li><strong>Local consultation.</strong> Problems, pain points, what needs to improve</li><li><strong>Expert project design</strong> — engineers, planners, affected residents</li><li><strong>Public visualization and impact analysis</strong> — AI-generated imagery (Measure 53b) for visual impact preview; GIS-based traffic, utility, and infrastructure analysis (Measure 53). Publish the analyses showing traffic, noise, visual impact, effects on adjacent streets and businesses. Let residents see the future before they decide</li><li><strong>Referendum if a new capital project over $25M</strong> — binding public vote under statutory process (Measure 77)</li><li><strong>Quarterly public progress reports</strong> during construction — on time, on budget, or explain why not</li></ol><p>The Crystal Pool replacement (Feb 2025, 58.7% Yes, $168.9M borrowing) is the proof of concept. <strong>We will continue it as voted, and we will require the same process for every new capital project over $25M.</strong></p>", "budget": ""},
  {"id": "78b", "pillar": "democratic", "section": "Direct Democracy and Transparency", "tier": "sub", "title": "The material change rule — no substantive change after the hearing without renotification", "body": "<p><strong>Currently:<strong> Measure 78 governs major <em>public</em> projects. Private development applications run on a separate track, and that track has a defect. A rezoning or development permit can be materially amended </strong>after the public hearing has closed and before the bylaw is adopted<strong>: height or density increased, an affordable-housing commitment reduced, a heritage-retention condition removed, a public amenity dropped. The residents who spoke to the application, and the councillors who weighed their submissions, are then responding to a proposal that is no longer the proposal. </strong>Nothing requires anyone to tell them.</strong></p><p><strong>ACTW:</strong> If the deal changes, the record reopens.</p><ul><li><strong>A defined material-change threshold:</strong> any post-hearing amendment that increases height, density, or permitted use by more than <strong>10%</strong>, or that removes or reduces a community amenity contribution, an affordability condition, a heritage-retention commitment, or a public-access commitment</li><li><strong>The consequence:</strong> the file pauses, staff report publicly on what changed and why, and affected parties are renotified before any vote proceeds. Not a fresh hearing in every case, but <strong>never a silent change</strong></li><li><strong>A published register of material changes</strong> by application, on the Measure 67 dashboard, so the frequency of the practice becomes visible for the first time. Nobody currently knows how often this happens, which is itself the problem</li><li><strong>Applies symmetrically.</strong> A change that <em>increases</em> public benefit is disclosed on the same terms as one that reduces it. The rule is about the completeness of the record, not the direction of the change</li><li><strong>Paired with pro-forma disclosure:</strong> where an applicant seeks relaxation of an affordability or amenity condition on viability grounds, the claim is supported by an <strong>independent pro-forma review at the applicant's cost</strong> before Council considers it. An unverified hardship claim is an assertion, not evidence</li><li><strong>Legal boundary, stated honestly:</strong> the <em>Local Government Act</em> governs public-hearing procedure and what constitutes a change requiring a further hearing. This measure sets a <strong>municipal disclosure and renotification standard above the statutory minimum</strong> and does not purport to alter the statute</li></ul><p>Measure 78 exists because the Dowler Place file showed what happens with no required process. This is the same principle applied to the applications that arrive every month rather than the projects that arrive twice a term.</p>", "budget": "approximately zero. A procedural rule inside the existing development-application process, administered by existing Planning staff, <strong>costing schedule days rather than dollars.</strong> Renotification is an existing statutory cost on a small number of files, and the register is absorbed within Measure 67. <strong>KPI:</strong> register published 4 of 4 quarters; share of material changes renotified, target 100%; <strong>median added schedule days per affected file, published so the cost of the rule is visible alongside its benefit.</strong>"},
  {"id": "79", "pillar": "democratic", "section": "Direct Democracy and Transparency", "tier": "core", "title": "Close the feedback loop", "body": "<p>Every public consultation must report back: here's what you said, here's what we decided, here's why. Transparency isn't a value statement — it's a service standard. Too many consultations in Victoria end with a report that gathers dust. We will publish a response to every consultation within 60 days. <strong>And on any plan or policy, the draft comes back before adoption.</strong> The 2025 Official Community Plan process is the case study: consultation ran, submissions were made, and <strong>no draft plan was published for the public to confirm that what they said had been heard</strong> before Council adopted it. That removed the one step that makes a consultation verifiable rather than merely completed. For every plan, policy, or strategy that goes through public consultation, the City will publish two things: <strong>the draft</strong>, and a <strong>what-we-heard-and-what-we-did reconciliation</strong> stating each substantive theme raised, what changed in response, and where nothing changed, why. Both published a minimum of <strong>30 days before the adoption vote</strong>, so the reconciliation can itself be corrected by the people it claims to summarize. A consultation nobody can audit is a consultation nobody should trust.</p>", "budget": "$0 net new. A published 60-day response is a discipline applied to the existing Communications and Engagement budget, which the adopted 2026 plan carries at $2.89M, not an addition to it. The City already runs the consultations and already writes the reports. What is missing is the paragraph at the end saying what was decided and why, and that costs nothing but nerve."},
  {"id": "79b", "pillar": "democratic", "section": "Direct Democracy and Transparency", "tier": "sub", "title": "Implement an Integrity Commissioner and the MNP governance report recommendations", "body": "<p>The MNP governance review of Victoria City Council surfaced specific recommendations on conflict-of-interest management, council-staff boundaries, transparency in decision-making, and the establishment of an <strong>Integrity Commissioner</strong> to investigate complaints against elected officials and recommend remedies. Implementation of those recommendations has lagged. Council members across the political spectrum have advocated for it — Coun. Gardiner most consistently (\"the MNP recommendations should be addressed before further major decisions\" — <em>Capital Daily</em>), Coun. Coleman (process-integrity advocate), Coun. Hammond (council-conduct accountability). We will:</p><ul><li><strong>Establish an arm's-length Integrity Commissioner office</strong> for the City of Victoria, with jurisdiction over conflicts of interest, gifts and benefits, post-employment restrictions, and council code-of-conduct breaches. A shared-service model with one or more adjacent municipalities is acceptable and likely cheaper</li><li><strong>Publish a complete implementation tracker</strong> for the MNP governance report recommendations, with status and target completion dates for each</li><li><strong>Annual public report</strong> on Integrity Commissioner caseload, outcomes, and systemic recommendations</li></ul><p>This is not a partisan tool. An Integrity Commissioner protects councillors of every persuasion from frivolous attacks and protects the public from genuine misconduct in equal measure.</p>", "budget": "$200–300K/year for a shared-service Integrity Commissioner office. Cost is far less than the litigation, FOI battles, and reputational damage of unresolved governance complaints."},
  {"id": "79c", "pillar": "democratic", "section": "Direct Democracy and Transparency", "tier": "sub", "title": "Published mandate letters and quarterly portfolio scorecards", "body": "<p><strong>Canadians already know this instrument.</strong> Federal and British Columbia cabinet ministers receive published mandate letters stating what each is responsible for delivering. No equivalent exists at Victoria City Hall — councillors hold liaison, committee, and external-board roles with no published deliverables, and residents cannot tell who owns what. Under BC's Community Charter the mayor is one vote of nine and cannot direct councillors — so this measure imposes nothing. It publishes.</p><p><strong>What we will do:</strong></p><ul><li><strong>The mayor goes first</strong> — within 30 days of taking office, the mayor publishes their own mandate letter: the commitments they personally own, mapped to the 12-commitments scorecard and the quarterly dashboard (Measure 67)</li><li><strong>Council is invited, by resolution</strong> — council may adopt published mandate letters for each liaison, committee-chair, and external-board appointment (CRD, police board, library board), stating the assignment's purpose and reporting cadence. Participation is voluntary and stated as such: the Community Charter lets a mayor publish, not command</li><li><strong>Quarterly portfolio scorecards</strong> — each published mandate reports progress quarterly on the Measure 67 dashboard, in plain language, including \"not started\" and \"off track\" where that is the truth</li><li><strong>No theatre</strong> — scorecards report the mandate, not the person. This is the accountability infrastructure of Measures 67 and 79 extended to elected roles, not a performance review of colleagues</li></ul><p>Residents should never have to file an FOI request to learn who at City Hall is responsible for what.</p>", "budget": "$0 — drafting and publication absorbed within the mayor's office and existing Measure 67 dashboard operations."},
  {"id": "79d", "pillar": "democratic", "section": "Direct Democracy and Transparency", "tier": "sub", "title": "A public lobbyist registry for development files", "body": "<p><strong>Currently:</strong> British Columbia operates a Lobbyists Transparency Registry for provincial public office holders. <strong>It does not cover municipal government.</strong> In Victoria, a development proponent may meet City staff and members of Council repeatedly across the life of an application, and no record of those meetings is published anywhere. The applications are public and the decisions are public. <strong>The access is not.</strong> This is among the cheapest trust measures available to a municipality and Victoria has not taken it.</p><p><strong>ACTW:</strong></p><ul><li><strong>A searchable public registry</strong> of meetings between development proponents or their representatives and members of Council or City staff, on files that are or become land-use applications</li><li><strong>What is recorded:</strong> date, participants, the file or address, and the subject in one line. Not a transcript, and not a deterrent to meeting</li><li><strong>Filed by the City side within 10 business days</strong>, so the obligation sits with the public body rather than with the applicant, and compliance does not depend on the goodwill of the party being recorded</li><li><strong>Published on the open data portal</strong> (per Measure 56) and summarized quarterly on the Measure 67 dashboard</li><li><strong>Exclusions stated in advance:</strong> routine counter service, permit intake, inspection, and code interpretation are not lobbying and are not recorded. <strong>Nothing here should make it harder to ask a simple question</strong></li><li><strong>Applies to everyone, including the mayor.</strong> A registry with an exemption at the top is not a registry</li></ul><p>Meeting a developer is a legitimate and necessary part of the job. Doing it unrecorded is the part residents object to.</p>", "budget": "<strong>25 to 40K one-time</strong> for the register and intake form, built on existing City web infrastructure, then <strong>10 to 15K per year</strong> for administration, <strong>offset against the Measure 68 technology and attrition envelope</strong> and reported within Measure 67. No hardware and no monitoring capability, on the same construction as the Measure 28c registry. <strong>KPI:</strong> registry live within 6 months; entries filed within 10 business days, target 95%; quarterly summary published 4 of 4 quarters."},
  {"id": "79e", "pillar": "democratic", "section": "Direct Democracy and Transparency", "tier": "sub", "title": "Abolish the freedom-of-information application fee", "body": "<p><strong>Currently:</strong> British Columbia introduced a <strong>10 dollar application fee</strong> for general freedom-of-information requests in 2021. Public bodies <strong>may</strong> charge it; they are not required to. Victoria charges it. Ten dollars does not fund an access-to-information programme and was never going to. What it does is place a payment step, a receipt, and a small deterrent in front of the one instrument residents have when the City will not tell them something voluntarily. <strong>ACTW:</strong> Waive it.</p><ul><li><strong>The City will waive the application fee</strong> for general freedom-of-information requests, by Council policy, in the first quarter of the term</li><li><strong>Processing fees for large requests are unaffected.</strong> Where a request requires substantial search and preparation time, the existing statutory fee schedule continues to apply. <strong>This measure removes the entry toll, not the cost-recovery mechanism for genuinely large files</strong></li><li><strong>Published annually:</strong> requests received, median response time, share responded to within the statutory 30 business days, and share where an extension was taken</li><li><strong>Read alongside the rest of this pillar.</strong> Measures 31b, 66d, 67, 70c, 79, 79c, 79d and 82b all exist so the information arrives without anyone having to ask for it. <strong>A rising FOI volume against this framework would be evidence that its transparency measures are failing, and we would rather see that number than suppress the requests that produce it</strong></li></ul><p>We would rather publish it than charge you to ask for it.</p>", "budget": "forgone fee revenue of roughly <strong>5 to 15K per year</strong> at Victoria's request volume, <strong>offset against the Measure 68 attrition envelope.</strong> The fee is a barrier rather than a revenue line and no service depends on it. Annual reporting absorbed within Measure 67. <strong>KPI:</strong> fee waived within the first quarter; requests received, median response time, and statutory-compliance share published annually."},
  {"id": "79f", "pillar": "democratic", "section": "Direct Democracy and Transparency", "tier": "sub", "title": "Council remuneration changes take effect only after the next election", "body": "<p><strong>Currently:</strong> Victoria's Council sets its own remuneration by bylaw, and the MNP governance review recommended a formal review of base Council remuneration including comparators, benchmarks, and a regular review framework. <strong>The structural problem is not the amount.</strong> It is the timing: a body voting on its own pay during its own term holds a conflict that no review methodology, comparator set, or independent consultant removes. <strong>ACTW:</strong> Keep the review. Change when the result applies.</p><ul><li><strong>Any change to Council remuneration takes effect only at the start of the following term</strong>, so the councillors who vote for it are not the councillors who receive it, and the electorate has an opportunity to respond before it is paid</li><li><strong>Adopted in the first year of the term</strong>, before the next remuneration discussion rather than after it, so that it binds the council enacting it and not only its successors</li><li><strong>The independent review still happens</strong> (per the MNP recommendation and Measure 79b): published comparators, published methodology, published recommendation. <strong>Transparency about the number and independence about the timing are two different problems, and this measure solves the second</strong></li><li><strong>Published:</strong> current remuneration by position, the last change and its effective date, and any pending recommendation, on the Measure 67 dashboard</li><li><strong>Stated limit, because this framework does not overclaim:</strong> this binds by bylaw and by public commitment, and a future council may amend it as it may amend any bylaw. <strong>What it cannot do is amend it quietly</strong>, because the amendment would itself be a recorded public vote on Council pay</li></ul><p>An honest pay process costs a council nothing except the ability to benefit from its own decision.</p>", "budget": "<strong>zero.</strong> This is a timing rule, not a pay change, and it takes no position on whether Council remuneration is currently too high or too low. Publication absorbed within Measure 67. <strong>In the year of adoption it defers cost rather than adding it.</strong> <strong>KPI:</strong> bylaw or policy adopted within 12 months; remuneration and effective dates published 4 of 4 quarters."},
  {"id": "80", "pillar": "democratic", "section": "Direct Democracy and Transparency", "tier": "core", "title": "Neighbourhood empowerment", "body": "<p>Strengthen support for neighbourhood associations in Fernwood, James Bay, Fairfield, Vic West, Hillside-Quadra, and every community. Small grants for community-led meetings. Expand \"My Great Neighbourhood\" program. Expand the Local Champions Program — train residents to lead engagement in their own communities. The people who live in a neighbourhood know it best.</p>", "budget": "$0 net new. Delivered through the existing My Great Neighbourhood grant line ($200K in the adopted 2026 plan) and the Neighbourhoods division ($267K), sustained and expanded inside that envelope. The substantive change is role rather than money: neighbourhood associations become the delivery partner for Measure 45c shortlisting and Measure 82 survey design, instead of an audience that gets consulted after the decision is drafted."},
  {"id": "80b", "pillar": "democratic", "section": "Direct Democracy and Transparency", "tier": "sub", "title": "Civic access in Canada's two official languages", "body": "<p>Victoria's civic processes should operate in the languages of the country, English primarily and French, and should be written clearly enough that any resident can actually use them. Neither provincial nor federal law requires a BC municipality to provide service in French, and Victoria does not do so today. We will, on the same principle that governs the rest of this framework: the standard is national, not demographic. Access to City Hall should not depend on which community happens to be largest.</p><ul><li><strong>Plain-language standard in English</strong> for all grant applications, eligibility criteria, permit forms, and consultation materials — readability-tested, with jargon and legal boilerplate stripped. This is the single change that reaches the most residents: native English speakers, seniors, people with cognitive disabilities (per Measure 25b), and anyone reading in a second language</li><li><strong>French provision for the core corpus</strong> — principal service pages of the City website, permit and grant application forms, tax and utility notices, emergency and public-safety communications, and consultation summaries. AI-assisted translation with mandatory human review for anything legally operative</li><li><strong>Interpretation on individual request</strong> in either official language at service counters, permit intake, and public hearings — provided to the person who asks, when they ask</li><li><strong>No parallel community-language channels.</strong> The City will not operate separate application streams or standing translation programs by community. Residents needing settlement support in other languages are referred to the provincially and federally funded settlement sector, whose mandate and funding this already is (per Measure 70b)</li><li><strong>One civic process for everyone</strong> — same forms, same criteria, same queue, same published decision rules (per Measure 10)</li></ul><p>The two official languages are the common ground of Canadian civic life. Serving in them is a national standard, not an accommodation program.</p>", "budget": "$80–120K/year for plain-language rewriting, readability testing, and on-demand individual interpretation. Lower than the parallel-translation model it replaces, and the readability gains reach every resident rather than a subset."},
  {"id": "80c", "pillar": "democratic", "section": "Direct Democracy and Transparency", "tier": "sub", "title": "Bring back Local Area Plans", "body": "<p><strong>Currently:</strong> Victoria 2050, the Official Community Plan adopted in 2025, replaced the 2012 plan and is written at city scale. Beneath it, the neighbourhood-level plans that gave residents and small builders parcel-level certainty about what could be built where have not been renewed, and several are old enough to predate the conditions they govern. A resident asking what is permitted next door is answered by a citywide document written in discretionary language, <strong>and that discretion is where public trust in the planning process has been lost.</strong> This framework has a Measure 80 on neighbourhood <em>empowerment</em> and, until now, nothing on neighbourhood <em>planning</em>, which is the instrument neighbourhoods have actually been asking for. <strong>ACTW:</strong> Rebuild the layer beneath the OCP, on a published schedule.</p><ul><li><strong>A rolling Local Area Plan programme:</strong> <strong>two neighbourhood plans per year</strong>, published schedule, every neighbourhood either covered within the term or carrying a dated commitment for the remainder</li><li><strong>Parcel-level clarity as the deliverable:</strong> built form, height, and use expectations legible to a resident and to a small builder <strong>without hiring a planning consultant</strong>, so that Measure 7's speed and Measure 7b's pattern book have a rulebook to be fast against</li><li><strong>Infrastructure-linked capacity</strong> stated in each plan using the Measure 53 GIS layers: what the sewer, water, and road network in that neighbourhood can carry, and what must be built before more is added. Growth that outruns its infrastructure is a cost the whole city pays later, and Measure 66c is where it lands</li><li><strong>Written with the neighbourhood, not presented to it:</strong> community associations and land-use committees as drafting participants from the outset, delivered through the Measure 80 envelope and subject to the Measure 79 draft-back standard before adoption</li><li><strong>Housing capacity is not reduced by this measure, and we say so at the outset.</strong> Each plan must accommodate its share of the Measure 6 targets, including the 25% missing-middle and 20% family-sized composition splits. <strong>A Local Area Plan is a statement of where and how, not whether.</strong> The instrument has been used elsewhere to mean no. It will not be used that way here</li><li><strong>Published:</strong> plans adopted against schedule, and <strong>permit-processing time inside plan-covered areas versus uncovered areas</strong>, on the Measure 67 dashboard. If the plans do not make approvals faster and more predictable, they are not working and the number will say so</li></ul><p><strong>On the alternative.<strong> Repealing and replacing the 2025 OCP has been proposed in this election cycle. It is a defensible diagnosis of the same problem, and we decline the remedy: a repeal would consume a term, reopen every settled question, and stall the housing supply Measure 6 depends on. </strong>Local Area Plans deliver the parcel-level certainty without the demolition.</strong></p>", "budget": "two plans per year delivered <strong>inside the existing Planning and Development programme by re-sequencing the post-OCP local-area work the department was always going to do</strong>, rather than as a new line. Any incremental consultation and drafting capacity above that, estimated at <strong>150 to 250K per year, is placed in the gated conditional tier</strong> and excluded from the Balance Sheet, proceeding in Year 2 only if the Measure 15, Measure 65 and Measure 68 savings are verified as tracking at the end of Year 1. Infrastructure capacity inputs come from Measure 53 at no incremental cost. <strong>KPI:</strong> plans adopted against the published schedule; share of neighbourhoods covered; permit-processing time inside plan-covered areas versus uncovered."},
  {"id": "81", "pillar": "democratic", "section": "Direct Democracy and Transparency", "tier": "core", "title": "Saanich amalgamation — finish the file, don't restart it", "body": "<p><strong>Currently:</strong> The question is no longer whether to study amalgamation. It has been studied. Residents of both municipalities voted in 2014 to explore the idea, and again in 2018 on whether to spend up to $250,000 establishing a Citizens' Assembly to examine the costs, benefits, and disadvantages. A majority in both municipalities said yes; Victoria, Saanich, and the Province each contributed roughly $250,000. Work resumed after pandemic delay, and the Assembly was established in 2024 with MASS LBP support under Terms of Reference approved by both Councils: <strong>48 randomly selected residents from Victoria and Saanich, meeting for eight full-day sessions between September 2024 and April 2025.</strong> It concluded deliberations on <strong>April 5, 2025</strong>, recommending that the City of Victoria and the District of Saanich amalgamate into a single municipality, and presented its Final Report to Council in July 2025. Where the file then stalled is the part that matters. On <strong>July 31, 2025</strong> Council resolved to receive the report and direct staff to work with their Saanich counterparts on a short ballot question. In <strong>October 2025</strong> the two mayors jointly requested provincial authorization to hold a referendum during the 2026 general local elections. In <strong>April 2026</strong> the Minister of Housing and Municipal Affairs replied that a referendum would only be considered following additional analysis of the <strong>financial, transitional, and service impacts</strong> of amalgamation, and <strong>consultation with area First Nations.</strong> In <strong>July 2026</strong> both Councils settled on placing the same non-binding question on their ballots: <em>\"Do you support Saanich and Victoria becoming one municipality?\"</em> So on October 17, 2026 residents will answer a question that carries no legal force, on a file where the deliberative work is finished and the outstanding work is analysis the Province asked for over a year ago and neither municipality has delivered. <strong>ACTW:</strong> Twelve years of consultation has produced a recommendation and a ballot question. What it has not produced is the analysis that would let anyone act on either. We will finish the file rather than restart it.</p><ul><li><strong>Do not re-run the Assembly.</strong> It sat, it deliberated, it reported. Convening a second body would insult the 48 residents who did the work and would postpone the answer by another term</li><li><strong>Publish the result against the Minister's conditions within 90 days of the vote</strong> — the ballot result by neighbourhood, set beside a plain statement of which of the three impact analyses remain outstanding, what each would cost, and how long each would take</li><li><strong>Commission the outstanding analysis jointly with Saanich, on a published timeline</strong> — a financial, transitional, and service-impact study to the standard the Ministry has asked for, procured jointly, with terms of reference published before the contract is awarded</li><li><strong>Begin the First Nations consultation the Minister named</strong> through the Measure 1 government-to-government working tables, at the outset rather than as a late-stage sign-off. This is a condition the Province set, not an optional courtesy</li><li><strong>Return to the Province with the completed analysis and a request for a binding referendum</strong>, and publish both the request and the reply</li><li><strong>Report quarterly</strong> on the performance dashboard (Measure 67) until the file is closed in one direction or the other</li></ul><p><strong>On the word \"binding.\"</strong> Earlier versions of this measure proposed a binding referendum question drafted by a new Assembly. That is not available. Amalgamation requires provincially conducted referendums in each municipality, and in April 2026 the Province declined to authorize one until its conditions are met. Promising a binding vote that a municipality cannot call would breach this framework's own rule against promising what is not ours to deliver. The honest commitment is to <strong>remove the obstacle the Province actually named</strong>, and then ask again. <strong>On the Citizens' Assembly Council Committee.</strong> Victoria's Citizens' Assembly Council Committee, chaired in this term by Coun. Chris Coleman, is the existing body with custody of this file. Its remaining work is implementation follow-through, not fresh deliberation, and this measure is scoped to that.</p>", "budget": "Victoria's share of a joint financial, transitional, and service-impact study: $150–300K one-time, cost-shared with Saanich, with a provincial contribution requested on the 2018 precedent. First Nations consultation capacity is delivered within the existing Measure 1 working-table envelope. Reporting absorbed within Measure 67. <strong>No amalgamation savings or costs are booked anywhere in this framework</strong> — see Savings &amp; Revenue Analysis, Part G. A structural change of this size is not a fiscal claim until the analysis exists."},
  {"id": "82", "pillar": "democratic", "section": "Direct Democracy and Transparency", "tier": "core", "title": "Annual community surveys", "body": "<p>Track satisfaction, priorities, and safety perceptions across every neighbourhood. Publish results. Adjust course. No governing in the dark.</p>", "budget": "<strong>$40 to $60K per year</strong> for an annual statistically valid survey across all 12 neighbourhoods, absorbed within the Measure 67 dashboard envelope and disclosed in the Savings &amp; Revenue Analysis Part C1. Measure 82b's post-election turnout report is a separate commitment and is costed there. <strong>KPI:</strong> survey fielded 1 of 1 years; results published by neighbourhood within 90 days; and at least one published change in service delivery attributable to a survey finding each year, because a survey that changes nothing is a cost with no benefit."},
  {"id": "82b", "pillar": "democratic", "section": "Direct Democracy and Transparency", "tier": "sub", "title": "Turnout and access to the ballot", "body": "<p><strong>Currently:</strong> Victoria's 2022 general local election drew roughly <strong>38% turnout</strong>, about <strong>27,452 votes cast</strong>, down from 44.9% in 2018. A council elected by a bit over a third of eligible residents has a legitimacy problem it does not discuss. This framework has a Democratic pillar containing referendums, published dashboards, mandate letters, an Integrity Commissioner, and community surveys, and until now no commitment on the one act of participation that determines who gets to do any of it. For 2026, all four advance voting days — October 7, 13, 14, and 15 — fall on weekdays. <strong>ACTW:</strong> Turnout is the outcome. Access is the commitment, and access is squarely within municipal control through election bylaws adopted by Council under the <em>Local Government Act</em>.</p><ul><li><strong>More advance voting opportunities</strong>, at the statutory maximum where demand supports it, including <strong>at least one weekend advance voting day</strong> — an obvious gap in the current schedule</li><li><strong>More and better-placed voting places</strong>, reviewed against the Measure 82 survey data and turnout by voting place, with placement weighted toward the neighbourhoods that turned out <strong>lowest</strong> rather than the ones that turned out highest</li><li><strong>Voting where people already are</strong> — on post-secondary campuses (per Measure 13c), in large multi-unit residential buildings, and at seniors' residences and care facilities</li><li><strong>Mail ballot access</strong> on the broadest basis the statute permits, with a published application process that does not require a reason</li><li><strong>Plain-language voter information</strong> in both official languages (per Measure 80b), delivered early, stating what the ballot contains, where and when to vote, and what each office actually does. For 2026 that includes plainly explaining that the ballot elects <strong>three CRD Directors</strong> and <strong>School District 61 trustees</strong> as well as mayor and council, and that the amalgamation question is <strong>non-binding</strong> (per Measure 81)</li><li><strong>A published post-election turnout report within 90 days</strong>, by voting place and neighbourhood, so the next council inherits evidence rather than anecdote</li><li><strong>All election bylaw decisions taken at least 12 months before the vote</strong>, in open session, so no council of the day is setting the rules of its own re-election in the final year</li></ul><p><strong>A target, stated honestly.</strong> We will set and publish a turnout target of <strong>50% for the 2030 general local election</strong> and report the access measures delivered against it every year. We cannot promise turnout, because turnout is the residents' decision and not ours. We can promise that no resident failed to vote because the City made it inconvenient, and we can be measured on that.</p>", "budget": "<strong>75 to 150K per four-year election cycle</strong> for additional advance voting opportunities, campus and multi-unit voting places, and plain-language voter information, which is roughly <strong>20 to 40K per year amortized</strong>, absorbed within the existing election reserve contribution. The post-election turnout report carries no incremental cost, absorbed within Measure 67 reporting. <strong>KPI:</strong> advance voting days and voting places delivered against plan, including at least one weekend day; turnout published by neighbourhood within 90 days; election bylaws adopted 12 or more months before the vote."},
];

const PILLARS = {
  foundation:{label:"Honouring the Host Nations",color:"#7A6B3D",emoji:"🌿",desc:"Government-to-government tables, Indigenous procurement, place names, cultural protocols, urban Indigenous services.",tagline:"A city that works begins with right relations",intro:"<p>Victoria is built on the unceded traditional territories of the lək̓ʷəŋən-speaking peoples, today represented by the <strong>Songhees Nation</strong> and the <strong>Esquimalt Nation.</strong> This is a foundation, not a pillar, because relationship with the host Nations precedes and underlies every other commitment. The federal Crown holds the formal relationship with First Nations. But the City of Victoria sits inside this geography every day, makes decisions that affect this geography every day, and depends on functional working relationships to deliver on land use, infrastructure, policing, and economic development. This framework treats those relationships as ongoing operational work, not symbolic gesture. We will not promise outcomes that require the Nations' agreement to deliver. What we will promise is that the relationship operates at the level of a government-to-government working partnership, not consultative tokenism.</p>"},
  liveable:{label:"A Liveable City",color:"#1A3668",emoji:"🏠",desc:"Housing, families, childcare, cleanliness, mobility, accessibility.",tagline:"A city that works is a city where we're happy to live",intro:"<p>Victoria must be liveable for families, renters, workers, and seniors. We will make it possible to find housing, access childcare, keep the city clean, and ensure quality of life in every neighbourhood. Victoria's population is growing but liveability is declining. We will make Victoria a city where people want to stay, not a city they're forced to leave.</p>"},
  safe:{label:"A Safe City",color:"#B5341F",emoji:"🛡️",desc:"Public safety, order, accountability, modern infrastructure, Vision Zero.",tagline:"A city that works is a city where you feel safe",intro:"<p>Victorians deserve the level of safety and calm that makes a city liveable for everyone: seniors walking to the store, families at the playground, tourists visiting our waterfront, businesses keeping their doors open. Safety is the first freedom.</p>"},
  beautiful:{label:"A Beautiful City",color:"#227247",emoji:"🌳",desc:"Heritage, parks, urban aesthetics, technology leadership, climate resilience.",tagline:"A city that works protects what makes it extraordinary",intro:"<p>Victoria's soul rests on its heritage, its gardens, its waterfront, its trees. We will combine the best of Victoria's heritage with the best of modern technology to make Victoria a city admired by all. Not a museum, but a living, evolving city that honours its past while building its future.</p>"},
  managed:{label:"A Well-Managed City",color:"#8B6914",emoji:"💰",desc:"Taxes, permits, performance, fiscal discipline, cost of living.",tagline:"Victoria owes results, and we will deliver them",intro:"<p>For years, property taxes have climbed 6–8% annually while basic services lag behind. <strong>The 2026 budget opened at a 13.3% increase in November, was cut to 7.2% at the March draft, and was adopted on May 7 at 7.28%</strong> — a gap bridged with roughly $7M of one-time reductions, not structural savings (<em>CHEK News; Victoria News</em>). <strong>And 7.28% is not what a homeowner paid.</strong> That figure is the increase in total property tax revenue. Council then <strong>distributed it at 9.34% to residential properties and 4.78% to business</strong>, which works out to about <strong>$323 more on an average home assessed at $1,015,000</strong> and $427 on a typical business property assessed at $721,000 (<em>City of Victoria; Victoria News, May 11, 2026</em>). The same split happened the year before: <strong>8.18% residential against 5.6% business in 2025</strong> (<em>Times Colonist</em>). This is deliberate policy: council is moving the business-to-residential ratio from 3.67:1 toward 3:1 by 2030, and it means <strong>the headline number understates what homeowners are billed, every year, by a widening margin.</strong> Measure 66 therefore caps the residential rate rather than the total, and Measure 66d publishes the whole household bill including utilities. The city does not publicly report salary and benefits as a percentage of the operating budget, total municipal debt outstanding, or debt-to-revenue ratios in easily accessible formats. The approved borrowing of <strong>$168.9 million for Crystal Pool</strong> (20-year term) plus a staff-recommended $63 million in additional infrastructure borrowing will substantially increase debt servicing costs, which the City has already cited as a \"main cost driver\" for 2026. The adopted 2026–2030 plan shows debt servicing rising from $9.9M in 2026 to $13.0M in 2027 and roughly $28.2M by 2030.</p><div class=\"tbl-wrap\"><table class=\"dt\"><thead><tr><th>Year</th><th>Operating Budget</th><th>Tax Increase</th><th>VicPD Budget</th></tr></thead><tbody><tr><td>2023</td><td>$297.9M</td><td>6.15%</td><td>$69.5M</td></tr><tr><td>2024</td><td>~$330M</td><td>7.93%</td><td>~$72M</td></tr><tr><td>2025</td><td>~$359M</td><td>6.99%</td><td>$79.0M</td></tr><tr><td>2026 (adopted)</td><td><strong>$394.1M</strong></td><td><strong>13.3% opening draft → 7.28% adopted aggregate → 9.34% residential / 4.78% business</strong></td><td>$86.8M requested</td></tr></tbody></table></div><p>Victoria's operating budget has grown <strong>roughly 32% in three years</strong> — from $297.9M in 2023 to the <strong>$394.1M adopted for 2026</strong>, alongside $160.1M in capital (<em>City of Victoria</em>) — with no competitive benchmarking, no AI, no digital twin, no smart infrastructure, no published processing benchmarks, and no zero-based reviews. <em>(Earlier versions of this framework used the $384.1M draft figure and a 29% growth rate. The adopted number is higher. The 2023 basis should be verified as operating-only before this figure is quoted in campaign materials.)</em> The City funds its priorities with your money but measures success by dollars spent, not results delivered. That changes now.</p>"},
  democratic:{label:"A Democratic City",color:"#3D5A8C",emoji:"🗳️",desc:"Referendums, transparency, participation, public-visualization tools.",tagline:"Victorians decide, City Hall listens",intro:"<p>A mature democracy doesn't fear the judgment of its people. It relies on it.</p>"},
};
const PILLAR_ORDER = ["foundation", "liveable", "safe", "beautiful", "managed", "democratic"];

/* "The Problem" diagnostic that opens each section of the Program. */
const SECTION_INTRO = {
  "Housing: A City Where You Can Live": "<p><strong>The Problem</strong></p><p>The housing picture is paradoxical. Greater Victoria's rental vacancy rate surged to <strong>3.3% in 2025</strong> — the highest since 1999 — driven by reduced immigration and record purpose-built rental completions (<em>Victoria News, CMHC data</em>). Average asking rents are softening: median rent fell roughly 10–11% year-over-year by early 2026 (<em>Zumper</em>). Housing starts reached 4,859 in 2025, up 16% (<em>VRBA</em>). Yet the current council's marquee housing policy — the Missing Middle program — remains a statistical failure. Adopted January 2023 with a goal of <strong>150 permits per year</strong>, it produced just <strong>3 applications in its first six months</strong>, forcing a September 2023 overhaul (<em>CHEK News, Storeys</em>). Even after rule changes, only <strong>61 permits were issued in 2024</strong> — less than half the target (<em>CHEK News</em>). The economics don't work: civil works for a 6-unit project can exceed $200,000, the <strong>258% DCC increase</strong> adds thousands per door, and new Amenity Cost Charges took effect October 2025, further chilling builder economics. Meanwhile, 1,749 people in Greater Victoria experience homelessness (2025 Point-in-Time count, up from 1,665 in 2023), with 318 sleeping outside. Victoria bears a vastly disproportionate regional burden: <strong>89% of shelter beds and 83% of supportive housing</strong> for the Capital Region, despite being one of 13 municipalities. The city has spent <strong>$12 million+ supporting homeless residents</strong> since 2023, plus <strong>$11 million repairing encampment damage</strong> (<em>Globe and Mail</em>). Permit processing times remain a black box — Victoria publishes no benchmarks, while Kingston targets 10 business days for simple permits and Kamloops offers full digital tracking. The root cause is not greed — it is scarcity compounded by regulatory failure. When rules are complex, builders don't build. When costs are hiked 258%, small-scale projects die. When the city takes a year to issue permits, housing doesn't get built fast enough.</p>",
  "A City That Works for Families": "<p><strong>The Problem</strong></p><p>Victoria faces the same crisis as many Canadian cities: young families leave because they cannot find childcare, cannot afford housing big enough for children, and feel the city is designed for adults without kids. The fertility rate in the CRD is among the lowest in BC. Childcare waitlists stretch for months. Parents who cannot find childcare cannot work — it is an economic problem as much as a social one.</p>",
  "A Clean City": "<p><strong>The Problem</strong></p><p>In Victoria, the daily reality is graffiti, needles, litter, and neglected public spaces. The DVBA Clean Team removes over 12,000 graffiti tags per year — and new ones appear daily. Cleanliness is not cosmetic. It is the foundation of civic pride and public safety. A clean city attracts residents, tourists, and businesses. A dirty city repels them.</p>",
  "A City Where You Can Get Around": "<p><strong>The Problem</strong></p><p>Quality of life depends on our ability to move freely — based on our needs, not the constraints imposed by City Hall. Many of us are sometimes drivers, sometimes cyclists, sometimes pedestrians. The approach must not sacrifice one to the other, but create better conditions for all. Victoria's cycling network is a genuine success story: <strong>36 km of AAA routes</strong> built since 2017, with <strong>95% of residents within 500 metres</strong> of a safe cycling route — the highest in Canada. Victoria claims the national title for bike-to-work commuting at <strong>5.3%</strong> (<em>CBC News</em>). Transit ridership has recovered to <strong>25 million trips</strong> (2024/25), exceeding pre-pandemic levels (<em>BC Transit</em>). But gaps remain: only two highway corridors to downtown, peak commutes of 45–60 minutes, buses without contactless payment, and poor street lighting that deters night cycling.</p>",
  "A City That Welcomes Pets": "<p>Victoria has one of the highest rates of pet ownership in Canada. We will:</p><ul><li>Ensure all parks (except children's play areas) are accessible to leashed dogs</li><li>Add dog waste stations and water fountains at all major parks</li><li>Work with taxi and rideshare companies to improve pet-friendly transportation options</li></ul>",
  "A City That Works for Every Body": "<p><strong>The Problem</strong></p><p>Approximately one in four Victorians lives with some form of disability. The City has made real progress on the All Ages &amp; Abilities (AAA) bike network, sidewalk improvements, and accessible transit. But large parts of the city remain difficult or impossible to navigate for people with mobility, vision, or cognitive disabilities. Accessibility audits consistently flag the same gaps: missing curb cuts, narrow sidewalks blocked by encroachments, inconsistent tactile and visual wayfinding, and street furniture that is not usable by everyone. A city that works only works if it works for everyone.</p>",
  "Strengthen Public Safety": "<p><strong>The Problem</strong></p><p>Victoria's Crime Severity Index dropped 11% in 2024 to its lowest since 2020, and property crimes fell to 2013 levels. Real progress worth protecting. But perception diverges sharply from statistics. VicPD's own community survey found only <strong>59% feel safe downtown during the day</strong> (down from 83% in 2020) and just <strong>22% at night</strong> (down from 35%). The DVBA's 2025 survey reported <strong>48% of downtown businesses would consider leaving</strong> if their lease expired (<em>CHEK News</em>). Commercial vacancy on Pandora hit a historical high of 10.7% in February 2025, with longtime businesses like Arq Salon (28 years) closing due to street disorder. VicPD is <strong>50–55 officers short</strong> of authorized strength — a 13% vacancy rate. Recruitment is so challenging the department launched a Temporary Employee Program in October 2025, bringing retired officers back at <strong>$160,000/year</strong> — 115% of first-class constable rate (<em>Victoria News</em>). Bylaw enforcement operates only 7 AM to 4 PM, with nearly <strong>80% of officers' time</strong> consumed by encampment management rather than general enforcement. The current council's Community Safety and Well-Being (CSWB) plan wasn't endorsed until June 2025 — nearly <strong>three years into the term</strong>. Mayor Alto publicly admitted in November 2025 that \"it took nearly a year before council's focus turned to community safety\" (<em>Times Colonist</em>). The plan's $10.35 million Phase 1 was funded not through operational savings but by <strong>raiding reserves</strong>: $2.5M from Centennial Square revitalization, $4M from the Financial Stability Reserve, $1.5M from Royal Athletic Park upgrades (<em>Victoria Buzz</em>). This is structurally unsustainable. BC's decriminalization pilot ended January 31, 2026 after the province concluded it had not delivered results — over 1,800 people died from toxic drugs in BC in 2025 (<em>CBC News</em>).</p><p><strong>The Legal Framework — Rules Already Exist</strong></p><p>Before proposing new policies, we must acknowledge what is already on the books:</p><ul><li><strong>Parks:</strong> Victoria's rules allow temporary overnight sheltering only in designated parks, with shelters removed by 7 AM (with location/spacing restrictions). If tents stay up all day, that is an enforcement problem, not a missing-rule problem</li><li><strong>Sidewalks:</strong> Victoria's Streets &amp; Traffic Bylaw restricts obstructing sidewalks, including specific downtown geography and time windows</li><li><strong>Public drug use:</strong> Since May 7, 2024, using illicit drugs is prohibited in public spaces. Police can direct a person to leave, seize drugs, or arrest where required</li></ul><p>The rules exist. What's missing is the capacity and consistency to enforce them. That is what we will fix.</p><p><strong>Implementation Timeline — Phased, Realistic, Credible</strong></p><p><strong>Phase A: Days 0–90 — Visible Order + Fast Cleanup</strong></p><ul><li>Launch the Downtown Public Order Team (DPOT) immediately</li><li>Daily hot-spot deployment on Pandora, Princess, and the downtown core</li><li>Extend bylaw coverage into evenings and weekends</li><li>Aggressive public-space maintenance: sharps removal, pressure-wash schedules, garbage pickup, lighting fixes, graffiti removal</li><li>Reduce \"attractors\" and improve normal use of public spaces</li></ul><p><strong>Phase B: Months 3–12 — Build Capacity So Enforcement Sticks</strong></p><ul><li>\"Move along\" only works if there is somewhere to move to. We will scale managed alternatives outside the core: shelter mats, modular supportive housing, managed sites with services</li><li>Tie every enforcement action to a clear offer: \"You cannot stay here, but you can go there tonight; transport and intake are available.\"</li><li>Track refusals vs. acceptances — this data becomes ammunition for advocacy to the Province</li><li>Increase capacity faster than enforcement ramps up</li></ul><p><strong>Phase C: Months 12–36 — Reduce Inflow + Address Root Causes</strong></p><ul><li>Supportive housing and treatment capacity (provincial lead, relentless municipal pressure). Use permitting fast-tracking, land contributions, partnerships, and constant escalation</li><li>Target the small group driving chronic disorder: trafficking, weapons, violent repeat offenders. Data-driven. Coordinated with Crown and courts</li><li>Measure and report progress quarterly. Adjust tactics based on what's working</li></ul>",
  "Better Lighting for Better Safety": "<p><strong>The Problem</strong></p><p>The best current evidence is the updated 21-study systematic review and meta-analysis conducted to Campbell Collaboration guidelines (Welsh, Farrington &amp; Douglas, published by the Swedish National Council for Crime Prevention (Brå) and in <em>Criminology &amp; Public Policy</em>, 2022): improved street lighting is followed by a significant <strong>14% reduction in total crime</strong> in treated areas versus comparable controls — revised down from the 21% in the earlier 13-study review (Farrington &amp; Welsh, 2007). We cite the newer, lower number deliberately. Notably, effects are at least as strong in studies measuring daytime crime as night-only crime: lighting works by signalling investment and strengthening informal guardianship, not merely by visibility. Darkness creates fear and opportunity. Light removes both — and no camera or microphone is required for it to do so.</p>",
  "Vision Zero: Trending Toward Zero Traffic Deaths": "<p><strong>The Problem</strong></p><p>Recent years: 1–3 fatalities per year within Victoria proper. Dozens injured at high-collision intersections (Blanshard &amp; Hillside, Douglas Street). 161 cyclist-involved crashes in the Capital Region in 2022. Every one is preventable. <strong>Target:</strong> A <strong>50% reduction in serious injury and fatality collisions by 2030</strong>, trending toward zero — the honest version of Vision Zero. No mature Vision Zero city has achieved literal zero; what they achieve is a sustained downward trajectory through engineering, enforcement, and education.</p>",
  "The Politics of Beauty": "<p><strong>The Problem</strong></p><p>Victoria is one of Canada's most beautiful cities: 254 hectares of parkland, Tree City of the World, 13 Heritage Conservation Areas, 195+ protected heritage properties in Old Town. But growth pressures threaten character. New development doesn't always respect the human scale. Street furniture is replaced with generic modern fixtures. Maintenance of public spaces is uneven. The unique aesthetic character that makes Victoria special is being eroded by indifference.</p>",
  "Climate Resilience — Practical, Not Ideological": "<p><strong>The Problem</strong></p><p>Climate impacts are here now — cracked stormwater pipes, flooded streets, wildfire smoke days, and extreme heat. Victoria's infrastructure was built for a climate that no longer exists. The question isn't whether to act — it's whether to act practically or symbolically. Victoria declared a climate emergency in 2019. The city has achieved a <strong>31% GHG reduction from 2007 levels</strong> but needs another <strong>19 percentage points by 2030</strong> to meet its 50% target (<em>City of Victoria</em>). The gap is primarily in building emissions — natural gas heating accounts for the largest share. The adoption of BC's highest Zero Carbon Step Code for new construction (effective July 2025) is progressive, but the Climate Friendly Homes retrofit program <strong>lacks published uptake numbers</strong>. The urban forest comprises ~150,000 trees with approximately 30% canopy cover. The CRD's Regional Water Supply Master Plan envisions <strong>$2 billion in capital upgrades over 30 years</strong>, including a $1.1 billion filtration plant at Goldstream (<em>CRD</em>). Victoria's stormwater utility fee is $218.42/year per property. Real foundations worth building on — but the gap between targets and delivery is growing, and the current council has not deployed a single modern efficiency tool to close it.</p>",
};
const SECTION_ORDER = ["Honouring the Host Nations", "Housing: A City Where You Can Live", "A City That Works for Families", "A Clean City", "A City Where You Can Get Around", "A City That Welcomes Pets", "A City That Works for Every Body", "Strengthen Public Safety", "Restore Order to Public Spaces", "Better Lighting for Better Safety", "Vision Zero: Trending Toward Zero Traffic Deaths", "The Politics of Beauty", "Liberate Cultural, Festive, and Sporting Life", "Victoria as a Technology Leader", "Climate Resilience — Practical, Not Ideological", "Spend Less, Deliver More", "Grow the Tax Base, Don't Just Tax More", "Lower the Cost of Living — Specific Measures", "Direct Democracy and Transparency"];

const COMMITMENTS = [
  {n:1,c:"Residential tax rate",t:"≤6.5% Year 1, ≤5% Year 2, about CPI + population growth Year 3 onward. Capped on the residential rate, not the total levy",b:"9.34% residential in 2026 (7.28% total levy, 4.78% business). Four straight years above inflation plus growth"},
  {n:2,c:"Verified annual savings",t:"$8–14M per year in operating savings verified and banked by Year 4, published line by line against the year they were promised",b:"$0 currently reported. No competitive benchmarking, no zero-based review, and no published savings register exist today"},
  {n:3,c:"New homes (composition)",t:"12,000+ net new units by 2030, 25% missing middle, 20% 3BR+, 15% non-market",b:"2,359 net new units delivered in 2 years, against a 5-year provincial target of 4,902"},
  {n:4,c:"Rental vacancy rate",t:"5%",b:"3.3% (2025, highest since 1999)"},
  {n:5,c:"Unsheltered homelessness",t:"-50%",b:"~320 people"},
  {n:6,c:"Crime severity",t:"-15%",b:"CSI 152.65 (2024, down 11%)"},
  {n:7,c:"Graffiti removal",t:"90% within 48h",b:"No current standard"},
  {n:8,c:"Permit speed (by category)",t:"Simple under 6 weeks, complex under 6 months, rezoning under 9 months",b:"3–18+ months by type; no benchmark currently published"},
  {n:9,c:"Downtown vacancy",t:"5% storefronts",b:"~11% (current)"},
  {n:10,c:"Dangerous intersections redesigned",t:"All 10 of the top 10 by collision history, redesigned or reconstructed within the term",b:"0 redesigned, and no published collision inventory exists, so the top 10 has never been named"},
  {n:11,c:"Transparency delivered",t:"Lobbyist registry live, FOI application fee abolished, Integrity Commissioner appointed, and all 16 quarterly reports published within 30 days of quarter end",b:"0 of 3 in place, and no quarterly performance report is published at all"},
  {n:12,c:"Climate and canopy",t:"-50% GHG by 2030 (vs 2007); 35% tree canopy by 2035",b:"-31% achieved, 19 pts to go; canopy roughly 30%"},
];

const FAQ = [
  {q:"You're too pro-business / anti-environment",a:"This framework supports both business and the environment. Small businesses are the backbone of our community, and practical environmental policies work better than symbolic ones. The framework includes 50% GHG reduction by 2030, 5,000 new trees, 60% green mobility, and Climate Friendly Homes expansion, with published uptake numbers, which the current council has not provided. That is not anti-environment. It is results-oriented environmentalism."},
  {q:"You're cutting services / austerity",a:"We are not cutting services. We are ensuring every dollar delivers value. Good management isn't austerity, it's responsibility. Every dollar saved through zero-based budgeting and competitive bidding gets redirected to frontline services: more bylaw officers, faster permits, cleaner streets, modern infrastructure."},
  {q:"You don't care about homelessness",a:"Compassion without accountability helps no one. This framework commits to a 50% reduction in unsheltered homelessness through Housing-First, supportive housing, wraparound services, and relentless advocacy to the Province. But we also enforce the rules, because residents, businesses and vulnerable people themselves deserve safe, orderly public spaces. The phased implementation plan proves we understand you cannot enforce without capacity."},
  {q:"You just want to privatize everything",a:"We want competitive testing for the services where cost and quality can actually be measured, which means waste collection and street cleaning. The test runs in both directions against the same specification, so the cheaper competent option wins whether that turns out to be the in-house crew or a contractor. Workers are protected with mandatory re-employment clauses. The City retains oversight and audits performance. The Phoenix \"managed competition\" model even lets City workers bid against private firms to keep services public when public delivery is competitive. This is not ideology. It is the same approach used in cities across Canada and the world, by governments of every political stripe."},
  {q:"Referendums slow everything down",a:"Only new (non-lifecycle) capital projects over $25M go to referendum, within the BC statutory framework. Lifecycle maintenance is excluded so essential infrastructure work proceeds. That means a handful of major new-build decisions per term, not every speed bump and park bench. The Crystal Pool referendum (February 2025, 58.7% Yes) proved Victorians can make informed decisions on major spending. When the City spends big on new capital, residents should decide."},
  {q:"You're going to put surveillance in our streetlights",a:"No. This framework explicitly <em>rejects</em> audio surveillance, behavioural AI, gunshot/scream detection, and any \"directed brightness at suspect\" functionality on public streetlights. The streetlight measure (Measure 30) is the Kelowna/Halifax model: LED conversion, IoT-connected platform for outage detection and brightness modulation, optional environmental sensors. The crime-reduction benefit of streetlighting itself is real and requires no surveillance: about 14% on the updated 2022 systematic-review evidence, revised down from 21% in the earlier review. We cite the lower, current number deliberately."},
  {q:"How does this differ from a candidate platform?",a:"This is a framework, not a campaign. It is open for adoption by any candidate, in whole or in part. Multiple candidates can run on these ideas, and they should. The goal is to raise the standard of debate, and to make costed, sourced, measurable platforms with quarterly accountability the new normal in Victoria."},
];

function esc(s){return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");}
const $=(s,r)=>(r||document).querySelector(s);
const $$=(s,r)=>Array.from((r||document).querySelectorAll(s));

/* Which pillar a section belongs to. Sections are unique across the Program,
   so the first measure that names one settles it; the measure-less sections
   fall back to the order table. */
const SECTION_PILLAR={};
MEASURES.forEach(function(m){ if(!SECTION_PILLAR[m.section]) SECTION_PILLAR[m.section]=m.pillar; });
SECTION_PILLAR["A City That Welcomes Pets"]=SECTION_PILLAR["A City That Welcomes Pets"]||"liveable";
function sectionPillar(s){ return SECTION_PILLAR[s]; }

function renderPillars(){
  var c=$("#pgd"); if(!c) return; var h="";
  PILLAR_ORDER.forEach(function(k){
    var p=PILLARS[k];
    var n=MEASURES.filter(function(m){return m.pillar===k;}).length;
    h+='<a class="pc" data-pj="'+k+'" href="#measures" style="border-top:3px solid '+p.color+'">'+
       '<div class="pch"><span class="pce">'+p.emoji+'</span><span class="pct" style="color:'+p.color+'">'+n+' measures</span></div>'+
       '<div class="pti" style="color:'+p.color+'">'+esc(p.label)+'</div>'+
       '<div class="pd">'+esc(p.desc)+'</div>'+
       '<div class="pca" style="color:'+p.color+'">View measures <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/></svg></div>'+
       '</a>';
  });
  c.innerHTML=h;
  $$("[data-pj]").forEach(function(a){a.addEventListener("click",function(){setTimeout(function(){setFilter(a.getAttribute("data-pj"));},80);});});
}

/* Stable, readable ids for the section wrappers. Derived from the section
   title rather than an index, so an id keeps working when a section moves. */
function slug(s){
  return String(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'')
    .replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'');
}

function renderMeasures(){
  var c=$("#mctr"); if(!c) return; var h="";
  PILLAR_ORDER.forEach(function(pk){
    var p=PILLARS[pk];
    var items=MEASURES.filter(function(m){return m.pillar===pk;});
    if(!items.length) return;
    /* Iterate the Program's own section order rather than only sections that
       contain measures, so a documented section with no numbered measures
       (A City That Welcomes Pets) still shows its text. */
    var sections=SECTION_ORDER.filter(function(s){
      if(SECTION_INTRO[s]&&sectionPillar(s)===pk) return true;
      return items.some(function(m){return m.section===s;});
    });
    items.forEach(function(m){ if(sections.indexOf(m.section)<0) sections.push(m.section); });
    var f=items[0].id, l=items[items.length-1].id;
    /* The em-dash prefix reads as one level of indent inside the jump list,
       which is a flat <select> on this page — the sections and the pillar
       groups inside Every Measure are not the same kind of destination. */
    h+='<div class="pgr" id="pg-'+pk+'" data-jump-label="— '+esc(p.emoji+' '+p.label)+'" data-pg="'+pk+'" style="border-top-color:'+p.color+'40">'+
       '<div class="pgh"><div class="pgt" style="color:'+p.color+'"><span style="font-size:1.1em">'+p.emoji+'</span> '+esc(p.label)+'</div>'+
       '<span class="pgg" style="color:'+p.color+'">'+items.length+' measures · M'+f+'–M'+l+'</span></div>';
    if(p.tagline) h+='<p class="pgtag">'+esc(p.tagline)+'</p>';
    if(p.intro) h+='<div class="pgintro">'+p.intro+'</div>';
    sections.forEach(function(sec){
      var sm=items.filter(function(m){return m.section===sec;});
      h+='<div id="sec-'+slug(sec)+'" data-sec="'+esc(sec)+'" data-p="'+pk+'"'+(sm.length?'':' data-empty="1"')+'><div class="shd">◆ '+esc(sec)+'</div>';
      if(SECTION_INTRO[sec]) h+='<div class="secintro">'+SECTION_INTRO[sec]+'</div>';
      sm.forEach(function(m){
        var tg=m.tier==="sub"?'<span class="mtg">Sub-measure</span>':"";
        var bu=m.budget?'<div class="mbu"><div class="mbl">Budget Impact</div><div class="mbx">'+m.budget+'</div></div>':"";
        var search=(m.title+" "+m.body+" "+(m.budget||"")+" M"+m.id+" "+m.section).toLowerCase().replace(/<[^>]+>/g," ");
        /* Collapsed by default: 100 expanded measures made the homepage 132
           screens tall on mobile. The <h3> stays inside <summary> so the
           heading outline is unchanged for screen readers. */
        h+='<details class="mi mit" id="m'+esc(m.id)+'" data-p="'+pk+'" data-s="'+esc(search)+'">'+
           '<summary class="misum">'+
           '<div class="mnu">M'+esc(m.id)+'</div>'+
           '<div class="mb2"><h3 class="mti" style="color:'+p.color+'">'+esc(m.title)+tg+'</h3></div>'+
           '<svg class="mchev" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><polyline points="6 9 12 15 18 9"/></svg>'+
           '</summary>'+
           '<div class="mbody">'+m.body+'</div>'+bu+
           /* A measure is the unit people actually argue about, so each one
              needs its own address to send. jumpnav.js opens whatever
              <details> a hash resolves into, so the link arrives expanded. */
           '<a class="mlink" href="#m'+esc(m.id)+'">Link to M'+esc(m.id)+'</a>'+
           '</details>';
      });
      h+='</div>';
    });
    h+='</div>';
  });
  c.innerHTML=h;
}

var cf="all", cs="", lastCs="", bulk=false;
function visibleMeasures(){
  return $$(".mit").filter(function(el){return !el.classList.contains("hbf");});
}
function applyFilters(){
  var v=0, searching=!!cs, csChanged=(cs!==lastCs);
  $$(".mit").forEach(function(el){
    var po=cf==="all"||el.getAttribute("data-p")===cf;
    var so=!cs||el.getAttribute("data-s").indexOf(cs)>=0;
    if(po&&so){el.classList.remove("hbf");v++;}else{el.classList.add("hbf");}
    /* Typing a query opens the matches so the hit is visible without a second
       click; clearing the query collapses everything back down. */
    if(csChanged) el.open=searching&&po&&so;
  });
  /* Hide sections whose measures are all filtered out. A section with no
     numbered measures shows only while its pillar is in scope and no search
     is narrowing the list, so it never looks like a stray empty result. */
  $$("[data-sec]").forEach(function(sc){
    var has=sc.querySelectorAll(".mit:not(.hbf)").length;
    if(sc.getAttribute("data-empty")==="1"){
      var inScope=(cf==="all"||sc.getAttribute("data-p")===cf);
      sc.style.display=(!searching&&inScope)?"":"none";
    }else{
      sc.style.display=has?"":"none";
    }
  });
  $$("[data-pg]").forEach(function(g){
    var has=g.querySelectorAll(".mit:not(.hbf)").length;
    g.style.display=has?"":"none";
  });
  /* A count of what the filter returned is useful; a headline total is not.
     The framework no longer publishes one, because three earlier versions
     published a figure that did not survive a hand count. So this reads out a
     number only while something is actually narrowing the list. */
  var mc=$("#mcount");
  if(mc) mc.textContent=(searching||cf!=="all") ? (v+" shown") : "All measures";
  lastCs=cs;
  syncExpandAll();
}
function setFilter(k){
  cf=k;
  $$(".cp").forEach(function(c){
    var on=c.getAttribute("data-f")===k;
    c.classList.toggle("a",on);
    c.setAttribute("aria-pressed",on?"true":"false");
  });
  applyFilters();
}
function syncExpandAll(){
  var b=$("#mexp"); if(!b) return;
  var vis=visibleMeasures();
  var allOpen=vis.length>0&&vis.every(function(el){return el.open;});
  b.setAttribute("aria-expanded",allOpen?"true":"false");
  b.disabled=!vis.length;
  var l=$(".mexpl",b); if(l) l.textContent=allOpen?"Collapse all":"Expand all";
}
function setupFilters(){
  $$(".cp").forEach(function(c){c.addEventListener("click",function(){setFilter(c.getAttribute("data-f"));});});
  var s=$("#ms"); if(s) s.addEventListener("input",function(e){cs=e.target.value.trim().toLowerCase();applyFilters();});
  var b=$("#mexp");
  if(b) b.addEventListener("click",function(){
    var vis=visibleMeasures();
    var allOpen=vis.length>0&&vis.every(function(el){return el.open;});
    bulk=true;
    vis.forEach(function(el){el.open=!allOpen;});
    bulk=false;
    syncExpandAll();
  });
  $$(".mit").forEach(function(el){el.addEventListener("toggle",function(){if(!bulk)syncExpandAll();});});
  syncExpandAll();
}
/* Measures are collapsed on screen; open them all for printing so the paper
   version stays complete, then restore whatever the reader had open. */
function setupPrint(){
  var saved=null;
  window.addEventListener("beforeprint",function(){
    bulk=true;
    saved=$$(".mit").map(function(el){return el.open;});
    $$(".mit").forEach(function(el){el.open=true;});
    bulk=false;
  });
  window.addEventListener("afterprint",function(){
    if(!saved) return;
    bulk=true;
    $$(".mit").forEach(function(el,i){el.open=saved[i];});
    bulk=false; saved=null; syncExpandAll();
  });
}

function renderScorecard(){
  var tb=$("#ctbl"); if(!tb) return; var t="", c="";
  COMMITMENTS.forEach(function(x){
    t+='<tr><td class="cnu">'+x.n+'</td><td class="ccm">'+esc(x.c)+'</td><td>'+esc(x.t)+'</td><td class="cba">'+esc(x.b)+'</td></tr>';
    c+='<div class="scc"><div class="scr"><div class="scn">'+x.n+'</div><div class="scl">'+esc(x.c)+'</div></div><div class="sme"><strong>Target:</strong> '+esc(x.t)+'</div><div class="sme"><strong>Baseline:</strong> '+esc(x.b)+'</div></div>';
  });
  tb.innerHTML=t;
  var cc=$("#ccrd"); if(cc) cc.innerHTML=c;
}

function renderFaq(){
  var c=$("#fqc"); if(!c) return; var h="";
  FAQ.forEach(function(i){
    h+='<details class="fqi"><summary class="fqs"><span class="fqq">"'+esc(i.q)+'"</span>'+
       '<span class="fqp"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg></span></summary>'+
       '<div class="fqa">'+esc(i.a)+'</div></details>';
  });
  c.innerHTML=h;
}

/* Back-to-top: reveals itself once you are past the first screen. It is a real
   anchor to #top, so it still works with JS disabled — the class only controls
   whether it is visible. */
function setupBackToTop(){
  var b=$("#jb"); if(!b) return;
  var tk=false;
  window.addEventListener("scroll",function(){
    if(tk)return; tk=true;
    requestAnimationFrame(function(){ b.classList.toggle("hd",window.scrollY<=600); tk=false; });
  },{passive:true});
}

function checkSubscribed(){
  if(new URLSearchParams(window.location.search).get("subscribed")==="true"){
    var s=$("#smg"); if(s) s.classList.add("sh");
  }
}

document.addEventListener("DOMContentLoaded",function(){
  renderPillars(); renderMeasures(); renderScorecard(); renderFaq();
  setupFilters(); setupBackToTop(); setupPrint(); checkSubscribed();
});
